-- test.lua
--  →  → Ui  →  API  + 
local _scriptDir   = gg.getFile():match("(.*/)") or ""
local _moduleCache = {}
local _moduleLoaded = {}
loadModule = function(name)
	local key = name:gsub("^%./", "")
	if not key:match("%.lua$") then key = key .. ".lua" end
	local path = _scriptDir .. key
	if _moduleLoaded[path] then return _moduleCache[path] end
	local chunk = dofile(path)
	_moduleCache[path] = chunk
	_moduleLoaded[path] = true
	return chunk
end

local _ok, _err = pcall(loadModule, "core/initialize.lua")
if not _ok then
	gg.alert("⚠️ \n\n" .. tostring(_err))
	os.exit()
end
