	toast       = gg.toast,
	alert       = gg.alert,
	choice      = gg.choice,
	multiChoice = gg.multiChoice,
	prompt      = gg.prompt,
}
local ggg = yj.ui.raw

yj.ui.ENGINE_GG      = "gg"
yj.ui.ENGINE_LUAJAVA = "luajava"

local _savedEngine
if yj.config and yj.config.configItem then
	_savedEngine = yj.config.configItem("UI.Engine")
end
if _savedEngine == "luajava" or _savedEngine == "gg" then
	yj.ui.engine = _savedEngine
else
	yj.ui.engine = "gg"
end

function yj.ui.setEngine(name)
	if name ~= "gg" and name ~= "luajava" then return false end
	yj.ui.engine = name
	if yj.config and yj.config.configItem then
		yj.config.configItem("UI.Engine", name)
	end
	return true
end

local function _getCtx()
	local Tools = yj.java and yj.java.Classes and yj.java.Classes.Tools
	return Tools and Tools.e() or nil
end

local function _luaJavaReady()
	local Tools = yj.java and yj.java.Classes and yj.java.Classes.Tools
	local Ui    = yj.java and yj.java.Classes and yj.java.Classes.Ui
	return Tools and Ui and Tools.e() ~= nil
end

local function _themeJson()
	local t = (Stack and Stack.UITheme) or {}
	if yj.json and yj.json.encode then
		local ok, s = pcall(yj.json.encode, t)
		if ok and type(s) == "string" then return s end
	end
	return "{}"
end

function yj.ui.toast(s, fast)
	if yj.ui.engine == "luajava" and _luaJavaReady() then
		local ctx = _getCtx()
		pcall(function()
			yj.java.Classes.Ui.showToast(ctx, tostring(s), fast == true)
		end)
		return
	end
	return ggg.toast(s, fast)
end

function yj.ui.alert(header, positive, negative, neutral)
	positive = positive or L("Xác nhận")
	if yj.ui.engine == "luajava" and _luaJavaReady() then
		local ctx    = _getCtx()
		local Array  = yj.java.Classes.Array
		local String = yj.java.Classes.String
		local Empty  = Array.newInstance(String, 0)
		local function toArr(b)
			if not b then return Empty end
			local a = Array.newInstance(String, 1)
			Array.set(a, 0, tostring(b))
			return a
		end
		local ok, r = pcall(function()
			return yj.java.Classes.Ui.showDialog(
				ctx, "", tostring(header),
				toArr(positive), toArr(negative), toArr(neutral),
				_themeJson()
			)
		end)
		if not ok then
			log.warn("[ui] LuaJava alert  gg:", r)
			return ggg.alert(header, positive, negative, neutral)
		end
		if r == 0 then return nil end
		return r
	end
	return ggg.alert(header, positive, negative, neutral)
end

function yj.ui.choice(options, selected, header)
	if yj.ui.engine == "luajava" and _luaJavaReady() then
		local ctx    = _getCtx()
		local Array  = yj.java.Classes.Array
		local String = yj.java.Classes.String
		local n = #options
		local arr = Array.newInstance(String, n)
		for i = 1, n do Array.set(arr, i - 1, tostring(options[i])) end
		local ok, idx = pcall(function()
			return yj.java.Classes.Ui.showList(
				ctx, tostring(header or ""), "",
				arr, false, _themeJson()
			)
		end)
		if not ok or idx == nil then
			log.warn("[ui] LuaJava choice / gg:", idx)
			return ggg.choice(options, selected, header)
		end
		local i = tonumber(tostring(idx))
		if not i or i < 1 then return nil end
		return i
	end
	return ggg.choice(options, selected, header)
end

function yj.ui.multiChoice(options, selected, header)
	if yj.ui.engine == "luajava" and _luaJavaReady() then
		local ctx    = _getCtx()
		local Array  = yj.java.Classes.Array
		local String = yj.java.Classes.String
		local n = #options
		local arr = Array.newInstance(String, n)
		for i = 1, n do Array.set(arr, i - 1, tostring(options[i])) end
		local ok, res = pcall(function()
			return yj.java.Classes.Ui.showList(
				ctx, tostring(header or ""), "",
				arr, true, _themeJson()
			)
		end)
		if not ok or not res then
			log.warn("[ui] LuaJava multiChoice / gg:", res)
			return ggg.multiChoice(options, selected, header)
		end
		local out = {}
		local len = res.length or 0
		for i = 0, len - 1 do out[#out + 1] = res[i] end
		if #out == 0 then return nil end
		return out
	end
	return ggg.multiChoice(options, selected, header)
end

function yj.ui.prompt(prompts, defaults, types)
	if yj.ui.engine == "luajava" and _luaJavaReady() then
		local ctx    = _getCtx()
		local Array  = yj.java.Classes.Array
		local String = yj.java.Classes.String
		local n = #prompts
		local labels    = Array.newInstance(String, n)
		local defaultsA = Array.newInstance(String, n)
		local typesA    = Array.newInstance(String, n)
		for i = 1, n do
			Array.set(labels,    i - 1, tostring(prompts[i]))
			Array.set(defaultsA, i - 1, tostring((defaults and defaults[i]) or ""))
			Array.set(typesA,    i - 1, tostring((types and types[i]) or "text"))
		end
		local ok, res = pcall(function()
			return yj.java.Classes.Ui.showPrompt(
				ctx, "", labels, defaultsA, typesA, _themeJson()
			)
		end)
		if not ok or not res then
			log.warn("[ui] LuaJava prompt / gg:", res)
			return nil
		end
		local out = {}
		for i = 1, #prompts do
			out[i] = tostring(Array.get(res, i - 1))
		end
		return out
	end
	return ggg.prompt(prompts, defaults, types)
end

function gg.toast(toast, fast)
	return yj.ui.toast(EMOJI .. "\t" .. tostring(toast) .. "\t" .. EMOJI, fast)
end

function gg.alert(alert, b1, b2, b3)
	return yj.ui.alert(EMOJI .. "\t" .. tostring(alert) .. "\t" .. EMOJI, b1, b2, b3)
end

function gg.choice(options, selected, header)
	local tt = {}
	for i, v in ipairs(options) do
		tt[i] = EMOJI .. "\t\t" .. v .. "\t\t" .. EMOJI
	end
	local result = yj.ui.choice(tt, selected, header)
	if result and options[result] then
		log.info(": ", options[result])
	end
	return result
end

function gg.multiChoice(options, selected, header)
	local tt = {}
	for i, v in ipairs(options) do
		tt[i] = EMOJI .. "\t\t" .. v .. "\t\t" .. EMOJI
	end
	return yj.ui.multiChoice(tt, selected, header)
end

function gg.prompt(options, defaults, types)
	local tt = {}
	for i, v in ipairs(options) do
		tt[i] = EMOJI .. "\t\t" .. v .. "\t\t" .. EMOJI
	end
	return yj.ui.prompt(tt, defaults, types)
end

