__vfs['core/log.lua'] = [[do
	local path    = "/storage/emulated/0/anhdepzai_debug.log"
	local enabled = true
	local buffer  = {}
	local flushAt = 16
	local startAt = os.time()
	local lines   = 0

	local f, err = io.open(path, "a")
	if f then
		f:close()
	else
		path = nil
		print("[log] ")
		if type(gg) == "table" and gg.toast then
			gg.toast("Logger disabled: " .. tostring(err))
		end
	end

	local function _ts()
		local rel = os.difftime(os.time(), startAt)
		return string.format("%s +%ds", os.date("%H:%M:%S"), rel)
	end

	local function _dump()
		if not path or #buffer == 0 then return end
		local fh = io.open(path, "a")
		if not fh then return end
		for i = 1, #buffer do fh:write(buffer[i], "\n") end
		fh:close()
		buffer = {}
	end

	local function _write(level, ...)
		if not enabled then return end
		lines = lines + 1
		local parts = {}
		for i = 1, select("#", ...) do
			local v = select(i, ...)
			parts[i] = v == nil and "nil" or tostring(v)
		end
		local line = string.format("%s [%s#%d] %s",
			_ts(), level, lines, table.concat(parts, " "))
		if path then
			buffer[#buffer + 1] = line
			if #buffer >= flushAt or level == "ERROR" then _dump() end
		else
			print(line)
		end
	end

	log = {}
	function log.info(...)  _write("INFO",  ...) end
	function log.warn(...)  _write("WARN",  ...) end
	function log.error(...) _write("ERROR", ...) end
	function log.flush(...)
		if select("#", ...) > 0 then
			log.error(...)
		else
			_dump()
		end
	end

	log.info("", "══════ anhdepzai ══════")
	log.info(":", os.date())
	log.info(":", tostring(path))
	log.flush()
end
]]

__vfs['core/type.lua'] = [[yj.types = yj.types or {}
yj.types.base     = yj.types.base     or {}
