	get = function(addr) return yj.mem.dword.get(addr) end,
	set = function(addr, value)
		if type(value) ~= "number" then return false end
		return yj.mem.dword.set(addr, value)
	end,
}

BASE.int64 = {
	size = 8,
	get = function(addr) return yj.mem.qword.get(addr) end,
	set = function(addr, value)
