	get = function(addr) return yj.mem.double.get(addr) end,
	set = function(addr, value)
		if type(value) ~= "number" then return false end
		return yj.mem.double.set(addr, value)
	end,
}

BASE.bool = {
	size = 1,
	get = function(addr)
		local v = yj.mem.byte.get(addr)
		if v == nil then return nil end
		return v ~= 0
	end,
	set = function(addr, value)
		return yj.mem.byte.set(addr, value and 1 or 0)
