}

local function _safeint()
	return yj.types.safeint or loadModule("core/types/safeint.lua")
end

BASE.SafeInt = {
	size = 0x20,
	get = function(addr) return _safeint().SafeInt.get(addr) end,
	set = function(addr, v) return _safeint().SafeInt.set(addr, v) end,
}

BASE.SafeInt32 = {
	size = 0x8,
	get = function(addr) return _safeint().SafeInt32.get(addr) end,
	set = function(addr, v) return _safeint().SafeInt32.set(addr, v) end,
}

BASE.JSONSafeInt = {
	size = 0x20,
	get = function(addr) return _safeint().JSONSafeInt.get(addr) end,
	set = function(addr, v) return _safeint().JSONSafeInt.set(addr, v) end,
}

BASE.Rect = {
	size = 0x10,
	get = function(addr)
		local v = yj.mem.dword.getBulk({
			addr, addr + 0x4, addr + 0x8, addr + 0xC,
		})
		local function pick(a)
			for i = 1, #v do
				if v[i].address == a then return v[i].value end
			end
			return nil
		end
		local x = pick(addr)
		if x == nil then return nil end
		return {
			x      = x,
			y      = pick(addr + 0x4)  or 0,
			width  = pick(addr + 0x8)  or 0,
			height = pick(addr + 0xC)  or 0,
		}
	end,
	set = function(addr, value)
		if type(value) ~= "table" then return false end
		yj.mem.dword.setBulk({
			{ address = addr,        value = math.floor(value.x      or 0) },
			{ address = addr + 0x4,  value = math.floor(value.y      or 0) },
			{ address = addr + 0x8,  value = math.floor(value.width  or 0) },
			{ address = addr + 0xC,  value = math.floor(value.height or 0) },
		})
		return true
	end,
}

BASE.Color3B = {
	size = 3,
	get = function(addr)
		local v = yj.mem.byte.getBulk({ addr, addr + 1, addr + 2 })
		local function pick(a)
			for i = 1, #v do
				if v[i].address == a then return v[i].value end
			end
			return nil
		end
		local r = pick(addr)
		if r == nil then return nil end
		return {
			r = r,
			g = pick(addr + 1) or 0,
			b = pick(addr + 2) or 0,
		}
	end,
	set = function(addr, value)
		if type(value) ~= "table" then return false end

		local function byte(v)
			return type(v) == "number" and v >= 0 and v <= 255
		end
		if not (byte(value.r) and byte(value.g) and byte(value.b)) then
			return false
		end
		yj.mem.byte.setBulk({
			{ address = addr,     value = value.r },
			{ address = addr + 1, value = value.g },
			{ address = addr + 2, value = value.b },
		})
		return true
	end,
}

BASE.Color4B = {
	size = 4,
	get = function(addr)
		local v = yj.mem.byte.getBulk({ addr, addr + 1, addr + 2, addr + 3 })
		local function pick(a)
			for i = 1, #v do
				if v[i].address == a then return v[i].value end
			end
			return nil
		end
		local r = pick(addr)
		if r == nil then return nil end
		return {
			r = r,
			g = pick(addr + 1) or 0,
			b = pick(addr + 2) or 0,
			a = pick(addr + 3) or 0,
		}
	end,
	set = function(addr, value)
		if type(value) ~= "table" then return false end
		local function byte(v)
			return type(v) == "number" and v >= 0 and v <= 255
		end

		local a = value.a
		if a == nil then a = 255 end
		if not (byte(value.r) and byte(value.g) and byte(value.b) and byte(a)) then
			return false
		end
		yj.mem.byte.setBulk({
			{ address = addr,     value = value.r },
			{ address = addr + 1, value = value.g },
			{ address = addr + 2, value = value.b },
			{ address = addr + 3, value = a },
		})
		return true
	end,
}

local function isCharNode(node)
	while node and node.kind == "const" do node = node.base end
	return node and node.kind == "base"
		and (node.name == "char"
			or node.name == "signed char"
			or node.name == "_CharT")
end

MODIFIER.ptr = function(inner, node)

	if inner == BASE.SafeInt32 or inner == BASE.SafeInt
		or inner == BASE.JSONSafeInt then
		return inner
	end

	local isCharPtr = isCharNode(node.base)
	return {
		size = 8,
		get = function(addr)
			local p = yj.mem.qword.get(addr)
			if not p or p == 0 then return nil end
			if isCharPtr then
				return yj.mem.cstring.read(p)
			end
			if inner == BASE.rawptr then
				return string.format("0x%X", p)
			end
			return inner.get(p)
		end,
		set = function(addr, value)
			local p = yj.mem.qword.get(addr)
			if not p or p == 0 then return false end
			if isCharPtr then
				if type(value) ~= "string" then return false end
				yj.mem.cstring.write(p, value)
				return true
			end
			if inner == BASE.rawptr then return false end
			return inner.set(p, value)
		end,
	}
end

MODIFIER.ref = MODIFIER.ptr

MODIFIER.array = function(inner, node)
	local len  = node.length
	local size = inner.size
	if not size then
		log.warn("[types]  size")
		return nil
	end
	return {
		size = len * size,
		get = function(addr)
			local out = {}
			for i = 0, len - 1 do
				out[i + 1] = inner.get(addr + i * size)
			end
			return out
		end,
		set = function(addr, value)
			if type(value) ~= "table" then return false end
			local ok = true
			for i = 0, len - 1 do
				if value[i + 1] ~= nil then
					ok = inner.set(addr + i * size, value[i + 1]) and ok
				end
			end
			return ok
		end,
	}
end

MODIFIER.RepeatedPtrField = function(inner, node)
	return {
		size = 0x18,
		get = function(addr)
			local h = yj.mem.rpf.readHeader(addr)
			if not h then return nil end
			local ptrs = yj.mem.rpf.readElements(addr) or {}
			local out = {}
			for i, p in ipairs(ptrs) do
				out[i] = inner.get(p)
			end
			return out
		end,
		set = function() return false end,
	}
end

MODIFIER.RepeatedField = function(inner, node)
	local size = inner.size
	if not size then
		log.warn("[types] RepeatedField  size")
		return nil
	end
	return {
		size = 0x4,
		get = function(addr)
			local n     = yj.mem.dword.get(addr + 0x8)
			local elems = yj.mem.qword.get(addr)
			if not n or n <= 0 or not elems or elems == 0 then return {} end
			local out = {}
			for i = 0, n - 1 do
				out[i + 1] = yj.mem.dword.get(elems + i * size)
			end
			return out
		end,
		set = function() return false end,
	}
end

local VECTOR_OBJECT_SIZE = 0x18
local VECTOR_MAX_ELEMS   = 4096

BASE.string.stride  = 0x18
BASE.cstring.stride = 0x08

MODIFIER.vector = function(inner, node)

	local elemSize = inner.size or inner.stride
	if not elemSize then
		log.info("[types] vector  size/stride rawptr")
		return BASE.rawptr
	end

	local function readBeginEnd(addr)
		local vals = yj.mem.qword.getBulk({ addr, addr + 0x8 })
		if #vals < 2 then return nil end
		local begin_ = vals[1].value
		local end_   = vals[2].value
		if not begin_ or begin_ == 0 then return nil end
		if not end_ or end_ < begin_ then return nil end
		local count = math.floor((end_ - begin_) / elemSize)
		if count < 0 then count = 0 end
		if count > VECTOR_MAX_ELEMS then
			log.warn("[types] vector :", count, "->", VECTOR_MAX_ELEMS)
			count = VECTOR_MAX_ELEMS
		end
		return begin_, count
	end

	return {
		size = VECTOR_OBJECT_SIZE,

		get = function(addr)
			local begin_, count = readBeginEnd(addr)
			if not begin_ then return {} end
			local out = {}
			for i = 0, count - 1 do
				local ok, v = pcall(inner.get, begin_ + i * elemSize)
				if ok then
					out[i + 1] = v
				else
					out[i + 1] = nil
				end
			end
			return out
		end,

		set = function(addr, value)
			local begin_, count = readBeginEnd(addr)
			if not begin_ then return false end

			local ok = true
			if type(value) == "table" then
				local n = math.min(count, #value)
				for i = 1, n do
					ok = inner.set(begin_ + (i - 1) * elemSize, value[i]) and ok
				end
			else

				if inner.size then
					for i = 0, count - 1 do
						ok = inner.set(begin_ + i * elemSize, value) and ok
					end
				else
					ok = false
				end
			end
			return ok
		end,
	}
end

