local function tryMakeVectorBase(name)
	local scalar, n = name:match("^(%a+)(%d+)$")
	if not scalar then return nil end
	n = tonumber(n)
	if not n or n < 1 or n > 16 then return nil end

	local elem, esize
	if scalar == "float" then
		elem, esize = BASE.float, 4
	elseif scalar == "double" then
		elem, esize = BASE.double, 8
	elseif scalar == "int" or scalar == "uint" or scalar == "int32" then
		elem, esize = BASE.int32, 4
	elseif scalar == "int64" or scalar == "long" then
		elem, esize = BASE.int64, 8
	elseif scalar == "bool" then
		elem, esize = BASE.bool, 1
	end
	if not elem then return nil end

	return {
		size = esize * n,
		get = function(addr)
			local out = {}
			for i = 0, n - 1 do
				out[i + 1] = elem.get(addr + i * esize)
			end
			return out
		end,
		set = function(addr, value)
			if type(value) ~= "table" then return false end
			local ok = true
			for i = 0, n - 1 do
				if value[i + 1] ~= nil then
					ok = elem.set(addr + i * esize, value[i + 1]) and ok
				end
			end
			return ok
		end,
	}
end

local function build(node)
	if not node or type(node) ~= "table" then
		return nil, "invalid AST node"
	end

	local k = node.kind

	if k == "base" then
		local name = ALIAS[node.name] or node.name
		local b = BASE[name]
		if not b then
			b = tryMakeVectorBase(name)
		end
		if not b then

			log.info("[types]  base rawptr: ", node.name)
			return BASE.rawptr
		end
		return b
	end

	if k == "ptr" or k == "ref" then
		local inner, err = build(node.base)
		if not inner then return nil, err end
		return MODIFIER[k](inner, node)
	end

	if k == "array" then
		local inner, err = build(node.base)
		if not inner then return nil, err end
		local obj = MODIFIER.array(inner, node)
		if not obj then return nil, "array modifier failed" end
		return obj
	end

	if k == "const" then
		return build(node.base)
	end

	if k == "template" and (node.name == "array" or node.name == "std::array") then
		local elemArg = node.args[1]
		local lenArg  = node.args[2]
		if not elemArg or not lenArg then
			log.info("[types] array<T,N>  rawptr")
			return BASE.rawptr
		end

		local lenStr = (lenArg.kind == "base") and lenArg.name or nil
		local len = nil
		if type(lenStr) == "string" then
			len = tonumber(lenStr:match("^%d+"))
		end
		if not len or len <= 0 then
			log.info("[types] array<T,N> : ", tostring(lenStr))
			return BASE.rawptr
		end

		local inner, err = build(elemArg)
		if not inner then return nil, err end

		local obj = MODIFIER.array(inner, { length = len })
		if not obj then
			log.info("[types] array<T,N> modifier  rawptr")
			return BASE.rawptr
		end
		return obj
	end

	if k == "template" then

		local tname = node.name
			:gsub("^std::__1::", "")
			:gsub("^__1::", "")
			:gsub("^std::", "")
		local mod = MODIFIER[tname] or MODIFIER[node.name]
		if not mod then
			log.info("[types]  template rawptr: ", node.name)
			return BASE.rawptr
		end
		local inner, err = build(node.args[1])
		if not inner then return nil, err end
		local obj = mod(inner, node)
		if not obj then return nil, "template modifier failed: " .. node.name end
		return obj
	end

	return nil, "unexpected AST kind: " .. tostring(k)
end

function yj.types.resolve(typeName)
	if type(typeName) ~= "string" then return nil end

	local hit = _resolveCache[typeName]
	if hit ~= nil then
		return hit or nil
	end

	local ast = yj.parseTypeString(typeName)
	if not ast then
		_resolveCache[typeName] = false
		return nil
	end

	local obj, err = build(ast)
	if not obj then
		log.error("", err or ("build : " .. typeName))
		_resolveCache[typeName] = false
		return nil
	end

	_resolveCache[typeName] = obj
	return obj
end

function yj.types.get(baseAddr, field)
	if not baseAddr or not field then return nil, "invalid args" end
	local t = field.type

	if not t or t == "pad" or t == "UnknownFieldSet" then
		return nil, "skip"
	end

	local obj = yj.types.resolve(t)
	if not obj then
		return nil, "resolve failed: " .. tostring(t)
	end

	local ok, value = pcall(obj.get, baseAddr + (field.offset or 0))
	if not ok then
		log.error("", "get : " .. tostring(t) .. " | " .. tostring(value))
		return nil, tostring(value)
	end

	return value
end

function yj.types.set(baseAddr, field, value)
	if not baseAddr or not field then return false, "invalid args" end
	local t = field.type
	if not t or t == "pad" or t == "UnknownFieldSet" then
		return false, "skip"
	end

	local obj = yj.types.resolve(t)
	if not obj then
		return false, "resolve failed: " .. tostring(t)
	end

	local ok, result = pcall(obj.set, baseAddr + (field.offset or 0), value)
	if not ok then
		log.error("", "set : " .. tostring(t) .. " | " .. tostring(result))
		return false, tostring(result)
	end
	return result
end

function yj.types.register(name, impl)
	if type(name) ~= "string" or type(impl) ~= "table" then return end
	BASE[name] = impl
	_resolveCache = {}
	log.info("[types]  base: ", name)
end

function yj.types.registerModifier(name, fn)
	if type(name) ~= "string" or type(fn) ~= "function" then return end
	MODIFIER[name] = fn
	_resolveCache = {}
	log.info("[types]  modifier: ", name)
end

function yj.types.registerAlias(from, to)
	ALIAS[from] = to
	_resolveCache = {}
end

function yj.types.clearCache()
	_resolveCache = {}
end

return yj.types
]]

