__vfs['core/boot/detectVirtualSpace.lua'] = [[local PKG = Info.game.package

local function shell(cmd)
	if type(gg.shell) ~= "function" then return nil end
	local ok, out = pcall(gg.shell, cmd)
	return ok and out or nil
end

local function detectVirtualSpace()
	local C = yj.java and yj.java.Classes
	local vSpaceReal = C and C.Config and C.Config.vSpaceReal
	if not vSpaceReal then
		log.info("detectVM", "Real root detected.")
		return 1, "/data/data/" .. PKG .. "/"
	end

	local vm_pkg = C.Config.E
	if not vm_pkg then return 2, nil end

	local vm_dir = "/data/data/" .. vm_pkg .. "/rootfs/data/user/"
	if not yj.fs.pathExists(vm_dir) then return 2, nil end

	local directory = C.File(vm_dir)
	if not directory then return 2, nil end

	local files = directory:listFiles()

	local candidates = {}
	for i = 1, #files do
		local f = files[i]
		local name = f:getName()
		if name and name:match("^%d+$") then
			local path = vm_dir .. name .. "/" .. PKG .. "/"
			if yj.fs.pathExists(path) then
				candidates[#candidates + 1] = path
			end
		end
	end

	if #candidates == 0 then return 2, nil end
	if #candidates == 1 then
		log.info("detectVM", "Single HCR2 path: " .. candidates[1])
		return 1, candidates[1]
	end

	log.info("detectVM", "Multiple HCR2 paths: " .. #candidates)
	local items = {}
	for i, p in ipairs(candidates) do
		items[i] = string.format("User %s: %s", p:match("/user/(%d+)/") or "?", p)
	end
	local sel = gg.choice(items, nil, L(""))
