end

local hasPack = (type(string.pack) == "function" and type(string.unpack) == "function")

local MAX_CHAR_ARGS = 200

local function packToArr(fmt, v)
	if not hasPack then return nil, "string.pack " end
	local s = string.pack(fmt, v)
	return { s:byte(1, #s) }
end

local function arrToPack(fmt, arr)
	if not hasPack then return nil, "string.unpack " end
	if #arr > MAX_CHAR_ARGS then return nil, "arr too long" end
	local s = string.char(unpack(arr))
	return (string.unpack(fmt, s))
end

