	end
	return "h " .. table.concat(hex, " ")
end

local function pack(signed_fmt, unsigned_fmt, val)
	if type(val) ~= "number" then return nil, "expect number" end
	local fmt = (val < 0) and signed_fmt or unsigned_fmt
	local ok, s = pcall(string.pack, fmt, val)
	if not ok then return nil, tostring(s) end
	return to_h(s)
end

local function to_signed(val, bits)
	if bits <= 0 or bits >= 64 then return val end
	local mask = (1 << bits) - 1
	val = val & mask
	local sign = 1 << (bits - 1)
	return (val >= sign) and (val - (sign << 1)) or val
end

function yj.cast.toUint8(val)  return val & 0xFF        end

function yj.cast.toInt8(val)   return to_signed(val, 8)  end

function yj.cast.toUint16(val) return val & 0xFFFF      end

function yj.cast.toInt16(val)  return to_signed(val, 16) end

function yj.cast.toUint32(val) return val & 0xFFFFFFFF  end

function yj.cast.toInt32(val)  return to_signed(val, 32) end

function yj.cast.byte(val)   return pack("<b",  "<B",  val) end

function yj.cast.word(val)   return pack("<h",  "<H",  val) end

function yj.cast.dword(val)  return pack("<i4", "<I4", val) end

function yj.cast.qword(val)
