end

function yj.cast.double(val)
	if type(val) ~= "number" then return nil, "expect number" end
	return to_h(string.pack("<d", val))
end

function yj.cast.xor(val, key)
	return to_h(string.pack("<I4", (val & 0xFFFFFFFF) ~ (key & 0xFFFFFFFF)))
end

function yj.cast.raw(text)
	if type(text) ~= "string" then return nil, "expect string" end
	return to_h(text)
end
yj.cast.utf8 = yj.cast.raw

function yj.cast.utf16le(text)
	if type(text) ~= "string" then return nil, "expect string" end
	local out = {}
	for i = 1, #text do
		out[i] = string.pack("<I2", text:byte(i))
	end
