	end
	return "h " .. table.concat(f, " ")
end

function yj.cast.arm32(opcode) return to_h(string.pack("<I4", opcode & 0xFFFFFFFF)) end

function yj.cast.thumb(opcode) return to_h(string.pack("<I2", opcode & 0xFFFF))     end

function yj.cast.arm64(opcode) return to_h(string.pack("<I4", opcode & 0xFFFFFFFF)) end

function yj.cast.aob(values)
	if type(values) ~= "table" then return nil, "expect table" end
	local parts = {}
	for i = 1, #values do
		local v = values[i]
		if type(v) ~= "string" then
			return nil, "aob item " .. i .. " "
		end
		parts[i] = v:sub(3)
	end
	return "h " .. table.concat(parts, " ")
end

function yj.cast.toInt32Safe(x)
	if type(x) ~= "number" then return x end
	local U32 = 4294967296
	local I32 = 2147483648
