__vfs['core/utils/cast/numArrayToAob.lua'] = [[function yj.cast.numArrayToAob(nums)
	if type(nums) ~= "table" then
		return nil, "nums "
	end
	if #nums < 1 then
		return nil, "nums "
	end

	local parts = { "h" }
	for idx = 1, #nums do
		local n = nums[idx]
		if type(n) == "string" then
			if n:match("^0[xX]") then
				n = tonumber(n:sub(3), 16)
			else
				n = tonumber(n)
			end
		end
		if type(n) ~= "number" then
			return nil, "nums[" .. idx .. "] "
		end
		n = n & 0xFFFFFFFF
		for i = 0, 3 do
			local b = (n >> (i * 8)) & 0xFF
			parts[#parts + 1] = string.format("%02X", b)
		end
	end
	return table.concat(parts, " ")
end

return yj.cast.numArrayToAob
]]

