__vfs['core/utils/config/fetchCloudFile.lua'] = [[do
	yj.net = yj.net or {}
	yj.config = yj.config or {}
	if not yj.net.httpGetSafe then

		local ok, makeRequest = pcall(loadModule, "core/utils/net/makeRequest.lua")
		if ok and type(makeRequest) == "function" then

			yj.net.httpGetSafe = function(url, timeoutMs)
				local ok2, content = pcall(makeRequest, url)
				if ok2 and type(content) == "string" then return content end
				return nil
			end
		end
	end
	if not yj.config.file then
		yj.config.file = loadModule("core/utils/config/file.lua")
	end
end

local function nowMs()

	return os.time() * 1000
end

local function toast(s)
	if type(showToast) == "function" then
		showToast(s)
	elseif type(gg) == "table" and type(gg.toast) == "function" then
		gg.toast(s)
	else
		print(s)
	end
end

local function alert(msg, pos, neg)
	return gg.alert(msg, pos, neg)
end

local function fetchCloudData(url, onFail, opts)
	opts = opts or {}
	local retryMs   = opts.retryMs   or 500
	local maxWaitMs = opts.maxWaitMs or 5000
	local prefix    = opts.toastPrefix or ""

	toast(prefix .. ".....")

	while true do
		local data, start

		start = nowMs()
		while nowMs() - start < maxWaitMs do
			data = yj.net.httpGetSafe(url)
			if type(data) == "string" and #data > 0 then
				toast(prefix .. "")
				return data
			end
			gg.sleep(retryMs)
		end

		if onFail then
			local v = onFail()
			if v ~= nil then return v end
		end
		toast(prefix .. ".....")
	end
end

function yj.config.fetchCloudFile(url, relativePath, name, builtin, force)

	if type(name) ~= "string" or name == "" then
		log.warn("fetchCloudFile: ", tostring(name))
		return nil
	end
	local relativeDir = type(relativePath) == "string" and relativePath or ""

	local hasBuiltin = (builtin ~= nil)

	if not force then
		local cached = yj.config.file(relativeDir, name)
		if cached ~= nil then
			log.info("fetchCloudFile: ", relativeDir, name)
			return cached
		end
	end

	if type(url) ~= "string" or url == "" then
		if hasBuiltin then
			log.info("fetchCloudFile:  url ", name)
			return builtin
		end
		log.warn("fetchCloudFile:  url ", name)
		return nil
	end

	local ok, result = pcall(fetchCloudData, url, function()

		local choice = alert(
			"\n\n",
			"",
			""
		)

		if choice == 2 or choice == nil then
			if hasBuiltin then
				toast(": " .. name)
				return builtin
			end
			log.warn("fetchCloudFile: ", name)
			return ""
		end
		return nil
	end)

	if not ok then
		log.error("fetchCloudFile: fetchCloudData ", tostring(result))
		if hasBuiltin then return builtin end
		return nil
	end

	local data = result

	if type(data) ~= "string" or #data == 0 then

		if hasBuiltin then return builtin end
		return nil
	end

	local writeOk = pcall(yj.config.file, relativeDir, name, data)
	if not writeOk then
		log.warn("fetchCloudFile: ", relativeDir, name)
		toast("")
	end

	return data
end

return yj.config.fetchCloudFile
]]

__vfs['core/utils/config/file.lua'] = [[yj.fs.createDirectory = yj.fs.createDirectory or loadModule("core/utils/fs/createDirectory.lua")
yj.fs.pathExists      = yj.fs.pathExists      or loadModule("core/utils/fs/pathExists.lua")

local function normalizeDir(relativePath)
	if relativePath == nil then return nil end
	if type(relativePath) ~= "string" then return nil end
	local rel = relativePath:gsub("^%./", "")

	rel = rel:gsub("^/+", "")

	if rel ~= "" and rel:sub(-1) ~= "/" then rel = rel .. "/" end
	return rel
end

function yj.config.file(relativePath, name, data)

	if type(name) ~= "string" or name == "" then
		log.warn("file: ", tostring(name))
		return nil
	end

	local base = (Info.paths and Info.paths.data) or (Info.paths and Info.paths.cache)
	if not base then
		log.warn("file: Info.paths.data/cache ")
		return nil
	end
	if base:sub(-1) ~= "/" then base = base .. "/" end

	local rel = normalizeDir(relativePath)
	if rel == nil then
		log.warn("file: ", tostring(relativePath))
		return nil
	end

	local dir  = base .. rel
	local file = dir .. name .. ".cfg"

	if not yj.fs.pathExists(dir) then
		if not yj.fs.createDirectory(dir) then
			log.warn("file: ", dir)
			return nil
		end
	end

	if data ~= nil then

		if type(gg) == "table" and type(gg.saveVariable) == "function" then
			local ok, err = pcall(gg.saveVariable, data, file)
			if ok then return true end
			log.warn("file: saveVariable  writeFile", tostring(err))
		end

		local fw = yj.fs.writeFile
		if not fw then
			local ok, mod = pcall(loadModule, "core/utils/fs/writeFile.lua")
			if ok then fw = mod end
		end
		if not fw then
			log.error("file: writeFile ")
			return nil
		end
		local body = "return " .. (yj.json and yj.json.encode and yj.json.encode(data) or "{}")
		local ok, err = fw(file, body)
		if not ok then
			log.error("file: writeFile ", tostring(err))
			return nil
		end
		return true
	end

	if not yj.fs.pathExists(file) then
		return nil
	end

	if type(gg) == "table" and type(gg.loadVariable) == "function" then
		local ok, v = pcall(gg.loadVariable, file)
		if ok and v ~= nil then return v end
	end

	local chunk, lerr = loadfile(file)
	if not chunk then
		log.warn("file: loadfile ", file, tostring(lerr))
		return nil
	end
	local ok, v = pcall(chunk)
	if not ok then
		log.warn("file: ", file, tostring(v))
		return nil
	end
	return v
end

return yj.config.file
]]

