__vfs['core/utils/fs/compileLuaToFile.lua'] = [[yj.fs.isValidPath = yj.fs.isValidPath or loadModule("core/utils/fs/isValidPath.lua")

function yj.fs.compileLuaToFile(outPath, luaCode)
	if not yj.fs.isValidPath(outPath) then return false, "invalid path" end
	if type(luaCode) ~= "string" then return false, "invalid lua code" end

	local func, err
	if _ENV ~= nil then
		func, err = load(luaCode, "=chunk", "t", _ENV)
	else
		func, err = loadstring(luaCode, "=chunk")
	end
	if not func then
		if log and log.error then log.error("", "Lua: " .. tostring(err)) end
		return false, tostring(err)
	end

	local ok, bytecode = pcall(string.dump, func, true)
	if not ok then

		ok, bytecode = pcall(string.dump, func)
	end
	if not ok then
		if log and log.error then log.error("", ": " .. tostring(bytecode)) end
		return false, tostring(bytecode)
	end

	local f, ferr = io.open(outPath, "wb")
	if not f then
		if log and log.error then log.error("", ": " .. tostring(ferr)) end
		return false, tostring(ferr)
	end
	f:write(bytecode)
	f:close()
	if log and log.info then log.info("", "") end
	return true
end

return yj.fs.compileLuaToFile
]]

