function yj.fs.copyFile(from, to)
	if not yj.fs.isValidPath(from) or not yj.fs.isValidPath(to) then
		return false, "invalid path"
	end
	local src, err = io.open(from, "rb")
	if not src then return false, err end

	local data, rerr = src:read("*a")
	src:close()
	if data == nil then return false, rerr or "read failed" end

	local dst, err2 = io.open(to, "wb")
	if not dst then return false, err2 end
	dst:write(data)
	dst:close()
	return true
end

return yj.fs.copyFile
]]

