__vfs['core/utils/json/decode.lua'] = [[yj.json.decode = yj.json.decode or function(input)
	if type(input) ~= "string" then
		return nil, ""
	end
	input = input:match("^%s*(.-)%s*$")
	if input == "" then
		return nil, "JSON "
	end
	local pos = 1
	local len = #input

	local parseValue, parseString, parseNumber, parseArray, parseObject, skipWhitespace

	function skipWhitespace()
		while pos <= len and input:sub(pos, pos):match("%s") do
			pos = pos + 1
		end
	end

	function parseString()
		if input:sub(pos, pos) ~= '"' then
			return nil, " '\"'"
		end
		pos = pos + 1
		local result = {}
		local escape = false
		while pos <= len do
			local char = input:sub(pos, pos)
			pos = pos + 1
			if escape then
				if char == '"' then result[#result+1] = '"'
				elseif char == '\\' then result[#result+1] = '\\'
				elseif char == '/' then result[#result+1] = '/'
				elseif char == 'b' then result[#result+1] = '\b'
				elseif char == 'f' then result[#result+1] = '\f'
				elseif char == 'n' then result[#result+1] = '\n'
				elseif char == 'r' then result[#result+1] = '\r'
				elseif char == 't' then result[#result+1] = '\t'
				elseif char == 'u' then
					local hex = input:sub(pos, pos + 3)
					pos = pos + 4
					local code = tonumber(hex, 16)
					if code then
						if code <= 255 then
							result[#result+1] = string.char(code)
						elseif utf8 and utf8.char then
							result[#result+1] = utf8.char(code)
						end
					else
						result[#result+1] = '?'
					end
				else result[#result+1] = char
				end
				escape = false
			elseif char == '\\' then
				escape = true
			elseif char == '"' then
				return table.concat(result)
			else
				result[#result+1] = char
			end
		end
		return nil, ""
	end

	function parseNumber()
		local startPos = pos
		if input:sub(pos, pos) == '-' then pos = pos + 1 end
		while pos <= len and input:sub(pos, pos):match("%d") do pos = pos + 1 end
		if pos <= len and input:sub(pos, pos) == '.' then
			pos = pos + 1
			while pos <= len and input:sub(pos, pos):match("%d") do pos = pos + 1 end
		end
		if pos <= len and input:sub(pos, pos):lower() == 'e' then
			pos = pos + 1
			if pos <= len and (input:sub(pos, pos) == '+' or input:sub(pos, pos) == '-') then
				pos = pos + 1
			end
			while pos <= len and input:sub(pos, pos):match("%d") do pos = pos + 1 end
		end
		return tonumber(input:sub(startPos, pos - 1))
	end

	function parseArray()
		pos = pos + 1
		local arr = {}
		skipWhitespace()
		if input:sub(pos, pos) == ']' then
			pos = pos + 1
			return arr
		end
		local index = 1
		while pos <= len do
			local value, err = parseValue()
			if err then return nil, err end
			arr[index] = value
			index = index + 1
			skipWhitespace()
			local char = input:sub(pos, pos)
			if char == ']' then
				pos = pos + 1
				return arr
			elseif char == ',' then
				pos = pos + 1
				skipWhitespace()
			else
				return nil, " ','  ']' '" .. char .. "'"
			end
		end
		return nil, ""
	end

	function parseObject()
		pos = pos + 1
		local obj = {}
		skipWhitespace()
		if input:sub(pos, pos) == '}' then
			pos = pos + 1
			return obj
		end
		while pos <= len do            skipWhitespace()
			if input:sub(pos, pos) ~= '"' then
				return nil, ""
			end
			local key, err = parseString()
			if err then return nil, err end
			skipWhitespace()
			if input:sub(pos, pos) ~= ':' then
				return nil, " ':'"
			end
			pos = pos + 1
			skipWhitespace()
			local value, err2 = parseValue()
			if err2 then return nil, err2 end
			obj[key] = value
			skipWhitespace()
			local char = input:sub(pos, pos)
			if char == '}' then
				pos = pos + 1
				return obj
			elseif char == ',' then
				pos = pos + 1
				skipWhitespace()
			else
				return nil, " ','  '}' '" .. char .. "'"
			end
		end
		return nil, ""
	end

	function parseValue()
		skipWhitespace()
		if pos > len then return nil, "" end
		local char = input:sub(pos, pos)
		if char == '"' then return parseString()
		elseif char == '{' then return parseObject()
		elseif char == '[' then return parseArray()
		elseif char == 't' then
			if input:sub(pos, pos + 3) == "true" then
				pos = pos + 4
				return true
			end
			return nil, " 'true'"
		elseif char == 'f' then
			if input:sub(pos, pos + 4) == "false" then
				pos = pos + 5
				return false
			end
			return nil, " 'false'"
		elseif char == 'n' then
			if input:sub(pos, pos + 3) == "null" then
				pos = pos + 4
				return nil
			end
			return nil, " 'null'"
		elseif char == '-' or char:match("%d") then
			return parseNumber()
		else
			return nil, " '" .. char .. "'"
		end
	end

	local result, err = parseValue()
	if err then return nil, err end
	skipWhitespace()
	if pos <= len then
		return nil, "JSON "
	end
	return result
end

return yj.json.decode
]]

__vfs['core/utils/json/encode.lua'] = [[yj.json.escapeString = yj.json.escapeString
	or loadModule("core/utils/json/escapeString.lua")

yj.json.encode = yj.json.encode or function(value)
	local t = type(value)
	if t == "nil" then
		return "null"
	elseif t == "boolean" then
		return tostring(value)
	elseif t == "number" then
		return tostring(value)
	elseif t == "string" then
		return '"' .. yj.json.escapeString(value) .. '"'
	elseif t == "table" then
		local isArray = true
		local maxIndex = 0
		for k, _ in pairs(value) do
			if type(k) ~= "number" then
				isArray = false
				break
			end
			if k > maxIndex then maxIndex = k end
		end
		local items = {}
		if isArray and maxIndex == #value and maxIndex > 0 then
			for i = 1, maxIndex do
				items[#items + 1] = yj.json.encode(value[i])
			end
			return "[" .. table.concat(items, ",") .. "]"
		end
		for k, v in pairs(value) do
			items[#items + 1] = '"' .. yj.json.escapeString(tostring(k)) .. '":' .. yj.json.encode(v)
		end
		return "{" .. table.concat(items, ",") .. "}"
	end
	return "null"
end

return yj.json.encode
]]

__vfs['core/utils/json/encrypted.lua'] = [[yj.json = yj.json or {}
