yj.fs.writeFile  = yj.fs.writeFile  or loadModule("core/utils/fs/writeFile.lua")
yj.fs.deleteFile = yj.fs.deleteFile or loadModule("core/utils/fs/deleteFile.lua")

local function getCrypto()
	local J = yj.java
	return J and J.Classes and J.Classes.Crypto
end

function yj.json.encrypted.read(srcPath)
	if type(srcPath) ~= "string" or srcPath == "" then
		return nil, "srcPath "
	end
	local Crypto = getCrypto()
	if not Crypto then
		return nil, "Crypto "
	end

	local dec = srcPath .. ".pem_tmp"

	local meta = Crypto.decrypt(srcPath, dec)
	if not meta then
		return nil, ": " .. srcPath
	end

	local content, readErr = yj.fs.readFile(dec)
	yj.fs.deleteFile(dec)
	if not content then
		return nil, ": " .. tostring(readErr)
	end

	local ok, data = pcall(yj.json.decode, content)
	if not ok or not data then
		return nil, "JSON : " .. tostring(data)
	end

	return data, nil, meta
end

function yj.json.encrypted.write(dstPath, data, meta)
	if type(dstPath) ~= "string" or dstPath == "" then
		return false, "dstPath "
	end
	if type(data) ~= "table" then
		return false, "data "
	end
	local Crypto = getCrypto()
	if not Crypto then
		return false, "Crypto "
	end

	local ok, content = pcall(yj.json.encode, data)
	if not ok or not content then
		return false, "JSON "
	end

	local dec = dstPath .. ".pem_tmp"
	local wok, werr = yj.fs.writeFile(dec, content)
	if not wok then
		return false, ": " .. tostring(werr)
	end

	local ok2, err = pcall(Crypto.encrypt, dec, dstPath, meta)
	yj.fs.deleteFile(dec)
	if not ok2 then
		return false, ": " .. tostring(err)
	end
	return true
end

return yj.json.encrypted
]]

