__vfs['core/utils/mem/align4.lua'] = [[function yj.mem.align4(v)
	local n
	if type(v) == "string" then
		n = tonumber(v, 16)
		if not n then return nil, "invalid hex: " .. v end
	elseif type(v) == "number" then
		n = v
	else
		return nil, "must be hex string or number"
