__vfs['core/utils/mem/dwordsToString.lua'] = [[function yj.mem.dwordsToString(dwordStr, skipFirstByte)
	if type(dwordStr) ~= "string" or dwordStr == "" then return "" end

	local out = {}
	local first = true
	for numStr in dwordStr:gmatch("%d+") do
		local d = tonumber(numStr)
		if d then
			local bytes = {}
			for k = 1, 4 do
				local b = d & 0xFF
				if not (skipFirstByte and first and k == 1) then
					bytes[#bytes + 1] = string.char(b)
				end
				d = d >> 8
			end
			out[#out + 1] = table.concat(bytes)
		end
		first = false
	end
	return table.concat(out)
end

return yj.mem.dwordsToString
]]

