__vfs['core/utils/mem/resolvePointerChain.lua'] = [[function yj.mem.resolvePointerChain(startAddress, is64, ...)
	local offsetTable = { ... }
	local skip = 0xFFFFFFFF
	local flag = 4
	if is64 then
		skip = 0xFFFFFFFFFFFF
		flag = 32
	end

	startAddress = gg.getValues({{
		address = startAddress,
		flags = flag
	}})[1].value
	startAddress = startAddress & skip

	for i = 1, #offsetTable do
		if offsetTable[i + 1] then
			startAddress = gg.getValues({{
				address = startAddress + offsetTable[i],
				flags = flag
			}})[1].value
			startAddress = startAddress & skip
		else
			startAddress = startAddress + offsetTable[i]
		end
	end
	return startAddress
end

return yj.mem.resolvePointerChain
