__vfs['core/utils/mem/cstring/read.lua'] = [[yj.mem = yj.mem or {}
yj.mem.cstring = yj.mem.cstring or {}

function yj.mem.cstring.read(addr)
	if addr == 0 or not addr then
		return ""
	end
	local bytes = {}
	local requests = {}
	for i = 0, 255 do
		requests[i + 1] = {
			address = addr + i,
			flags = 1
		}
	end
	local values = gg.getValues(requests)
	for i, v in ipairs(values) do
		local byteValue = v.value
		if byteValue == 0 then
			break
		end
		if byteValue < 0 then
			byteValue = byteValue + 256
		end
		bytes[#bytes + 1] = Stack.BYTE2CHAR.byId[byteValue]
	end
	return table.concat(bytes)
end

return yj.mem.cstring.read
]]

__vfs['core/utils/mem/cstring/write.lua'] = [[yj.mem = yj.mem or {}
yj.mem.cstring = yj.mem.cstring or {}

yj.str.stringToBytes = yj.str.stringToBytes or loadModule("core/utils/str/stringToBytes.lua")

function yj.mem.cstring.write(addr, str)
	local edits = {}
	local bytes = yj.str.stringToBytes(str)
	local len = #bytes
	for i = 1, len do
		edits[i] = {
			address = addr + i - 1,
			flags = 1,
			value = bytes[i]
		}
	end
	edits[len + 1] = {
		address = addr + len,
		flags = 1,
		value = 0
	}
	gg.setValues(edits)
	return len
end

return yj.mem.cstring.write
]]

