__vfs['core/utils/mem/rpf/readElements.lua'] = [[yj.mem.rpf = yj.mem.rpf or {}
yj.mem.rpf.readHeader = yj.mem.rpf.readHeader
	or loadModule("core/utils/mem/rpf/readHeader.lua")

function yj.mem.rpf.readElements(baseAddr, n, maxCount)
	local h = yj.mem.rpf.readHeader(baseAddr)
	if not h then return nil end
	local count = n or h.currentSize
	if count <= 0 then return {} end
	maxCount = maxCount or 4096
	if count > maxCount then count = maxCount end
	if not h.elements or h.elements == 0 then return nil end

	local requests = {}
	for i = 0, count - 1 do
		requests[i + 1] = {
			address = h.elements + i * 8,
			flags = 32,
		}
	end
	local vals = gg.getValues(requests)
	local out = {}
	for i = 1, count do
		local v = vals[i]
		if v and v.value and v.value ~= 0 then
			out[i] = v.value
		end
	end
	return out
end

return yj.mem.rpf.readElements
