__vfs['core/utils/mem/vector/writeHeaderBulk.lua'] = [[yj.mem = yj.mem or {}
yj.mem.vector = yj.mem.vector or {}

yj.mem.vector.const = yj.mem.vector.const
	or loadModule("core/utils/mem/vector/_const.lua")

local C = yj.mem.vector.const

local MAX_REQ_PER_BATCH = 512

local MAX_REQ_PER_OBJ = 3

function yj.mem.vector.writeHeaderBulk(items, batchSize)
	if type(items) ~= "table" then
		return 0
	end

	local maxPerBatch = math.floor(MAX_REQ_PER_BATCH / MAX_REQ_PER_OBJ)
	batchSize = tonumber(batchSize) or maxPerBatch
	batchSize = math.floor(batchSize)
	if batchSize < 1 then
		batchSize = maxPerBatch
	elseif batchSize > maxPerBatch then
		batchSize = maxPerBatch
	end

	local total = #items
	local written = 0

	local function writeBatch(startIndex, endIndex)
		local edits = {}
		local touched = {}

		for i = startIndex, endIndex do
			local it = items[i]
			if type(it) == "table"
				and type(it.vecAddr) == "number" and it.vecAddr ~= 0
				and type(it.header) == "table" then
				local h = it.header
				local addr = it.vecAddr
				local touchedThis = false

				if h.begin_ ~= nil and type(h.begin_) == "number" then
					edits[#edits + 1] = {
						address = addr + C.OFF_BEGIN,
						flags = 32,
						value = h.begin_ & 0xFFFFFFFFFFFFFFFF,
					}
					touchedThis = true
				end
				if h.end_ ~= nil and type(h.end_) == "number" then
					edits[#edits + 1] = {
						address = addr + C.OFF_END,
						flags = 32,
						value = h.end_ & 0xFFFFFFFFFFFFFFFF,
					}
					touchedThis = true
				end
				if h.cap_ ~= nil and type(h.cap_) == "number" then
					edits[#edits + 1] = {
						address = addr + C.OFF_CAP,
						flags = 32,
						value = h.cap_ & 0xFFFFFFFFFFFFFFFF,
					}
					touchedThis = true
				end

				if touchedThis then
					touched[i] = true
				end
			end
		end

		if #edits == 0 then return end

		gg.setValues(edits)

		for i = startIndex, endIndex do
			if touched[i] then
				written = written + 1
			end
		end
	end

	for s = 1, total, batchSize do
		local e = math.min(s + batchSize - 1, total)
		writeBatch(s, e)
	end

	return written
end

return yj.mem.vector.writeHeaderBulk
]]

