__vfs['core/utils/memory/memory.lua'] = [[yj.memory = yj.memory or {}

local function target()
	return gg.getTargetInfo()
end

local function pidFile()
	local t = target()
	return t and (gg.EXT_FILES_DIR .. "/" .. t.packageName) or nil
end

local function storageName(id)
	local t = target()
	return t and (gg.EXT_FILES_DIR .. "/" .. t.packageName .. "-mh-" .. tostring(id)) or nil
end

local function idsFile()
	local t = target()
	return t and (gg.EXT_FILES_DIR .. "/" .. t.packageName .. "-mh-ids") or nil
end

function yj.memory.checkSession()
	local t = target()
	if not t then return false end
	local path = pidFile()
	if not path then return false end

	local f = io.open(path, "r")
	local oldPid = f and tonumber(f:read("*all"))
	if f then f:close() end

	if oldPid == t.pid then return true end

	yj.memory.clearAll()
	local w = io.open(path, "w")
	if w then w:write(tostring(t.pid)); w:close() end
	return false
end

function yj.memory.save(id, data)
	yj.memory.checkSession()
	local name = storageName(id)
	if not (name and data ~= nil) then return false end

	gg.saveVariable(data, name, 0, false)

	local path = idsFile()
	if path then
		local f = io.open(path, "a")
		if f then f:write(tostring(id), "\n"); f:close() end
	end
	return true
end

function yj.memory.load(id)
	if not yj.memory.checkSession() then return nil end
	local name = storageName(id)
	if not name then return nil end

	local chunk = loadfile(name)
	if not chunk then return nil end

	local ok, data = pcall(chunk)
	if not ok then
		log.warn("memory.load: ", name, data)
		return nil
	end
	return data
end

function yj.memory.remove(id)
	local name = storageName(id)
	if not name then return false end
	return os.remove(name) ~= nil
end

function yj.memory.clearAll()
	local path = idsFile()
	if not path then return false end

	local f = io.open(path, "r")
	if not f then return true end

	local seen = {}
	local removed = 0
	for id in f:lines() do
		if not seen[id] then
			seen[id] = true
			local name = storageName(id)
			if name and os.remove(name) then
				removed = removed + 1
			end
		end
	end
	f:close()
	os.remove(path)
	return removed > 0
end

return yj.memory
]]

