			end
		end
	end

	MENU_CONFIG.__title = MENU_CONFIG.__title .. " " .. name
	yj.menu.unifiedRenderer(opts.detailFunc, {parentBaseAddr, parentField, name, Return, returnArgs}, MENU_CONFIG)
end

return yj.menu.renderRPFStringList
