__vfs['core/utils/net/translateTable.lua'] = [[yj.net.translateText = yj.net.translateText or loadModule("core/utils/net/translateText.lua")

function yj.net.translateTable(tbl, sourceLang, targetLang)
	if not tbl or #tbl == 0 then
		return {}
	end
	local temp = {}
	for i, v in ipairs(tbl) do
		temp[#temp + 1] = "[" .. i .. "]" .. v
	end
	local result = yj.net.translateText(
		table.concat(temp, "\n"),
		sourceLang,
		targetLang
	)
	local output = {}
	for i = 1, #tbl do
		local start = result:find("%[" .. i .. "%]")
		if start then
			local nextPos = result:find("%[" .. (i + 1) .. "%]", start + 1)
			if nextPos then
				output[i] = result:sub(start + #tostring(i) + 2, nextPos - 1)
			else
				output[i] = result:sub(start + #tostring(i) + 2)
			end
			output[i] = output[i]:gsub("^%s+", ""):gsub("%s+$", "")
		else
			output[i] = tbl[i]
		end
	end
	return output
end

return yj.net.translateTable
]]

__vfs['core/utils/net/translateText.lua'] = [[yj.json = yj.json or loadModule("core/utils/json/json.lua")

function yj.net.translateText(text, sourceLang, targetLang)
	if not text or text == "" then
		return text
	end
	local source = sourceLang or "vi"
	local target = targetLang or "vi"
	local url = "https://api.mymemory.translated.net/get?q="
		.. text:gsub(" ", "%%20")
		.. "&langpair=" .. source .. "|" .. target
	local response = gg.makeRequest(url)
	if not response or not response.content then
		return text
	end
	local data = yj.json.decode(response.content)
	return (data.responseData and data.responseData.translatedText) or text
end

return yj.net.translateText
]]

