__vfs['core/utils/net/webhookTransport.lua'] = [[yj.json = yj.json or loadModule("core/utils/json/json.lua")

yj.net.webhookDefaultName = yj.net.webhookDefaultName or "Gentle 🐰"

yj.net.webhookLimit = yj.net.webhookLimit or function(s, max)
	s = tostring(s or "")
	if #s <= max then return s end
	local suffix = "\n...[truncated]"
	return s:sub(1, max - #suffix) .. suffix
end

yj.net.webhookPost = yj.net.webhookPost or function(body, contentType)
	if type(gg.makeRequest) ~= "function" then
		return false, "gg.makeRequest not"
	end
	if not Info.net.webhookUrl or Info.net.webhookUrl == "" then
		return false, "not Webhook URL"
	end
	local ok, res = pcall(function()
		return gg.makeRequest(
			Info.net.webhookUrl,
			{
				["Content-Type"] = contentType,
				["User-Agent"] = "GENTLE/1.0"
			},
			body
		)
	end)
	if not ok then return false, tostring(res) end
	if type(res) ~= "table" then return false, "HTTP nil" end
	local code = tonumber(res.code)
	return code == 200 or code == 204, code
end

return {
	defaultName = yj.net.webhookDefaultName,
	limit       = yj.net.webhookLimit,
	post        = yj.net.webhookPost,
}
]]

__vfs['core/utils/offset/getOffsetfile.lua'] = [[yj.runtime.findFunction = yj.runtime.findFunction or loadModule("core/utils/runtime/findFunction.lua")

function yj.offset.getOffsetfile(filename, func, force)
	local file = Info.paths.offset
		.. Stack.TargetInfo.packageName
		.. "_"
		.. Stack.TargetInfo.versionName
		.. "_"
		.. filename .. ".cfg"

	log.info("", " " .. filename .. " :",
		force and "()" or "")

	if not force then
		local preload = loadfile(file)
		local savedOffset
		if preload ~= nil then savedOffset = preload() end
		if savedOffset ~= nil and savedOffset[1] ~= nil then
			log.info("", "",
				string.format("%s ", filename))
			return savedOffset[1]
		end
	end

	log.info("", ":", filename)

	local fn = yj.runtime.findFunction(func)
	if type(fn) ~= "function" then
		log.warn("", ":", func)
		return nil
	end

	local offset = fn()
	if not offset then
		log.warn("", " nil:", filename)
		return nil
	end

	gg.saveVariable({ offset }, file)
	log.info("", "",
		string.format("%s", filename))
	return offset
end

return yj.offset.getOffsetfile
]]

__vfs['core/utils/runtime/awaitLib.lua'] = [[function yj.runtime.awaitLib(lib, maxTicks)
	maxTicks = maxTicks or 120
	local tickCount = 0
	while true do
		local ranges = gg.getRangesList(lib)
		if #ranges > 0 then
			return ranges[1].start
		end
		tickCount = tickCount + 1
		if tickCount % 7 == 0 then
			gg.toast(L("" .. lib))
		end
		if tickCount >= maxTicks then
			log.error("", lib .. " ")
			log.flush()
			gg.alert(lib .. L(""))
			os.exit()
		end
		gg.sleep(500)
	end
end

return yj.runtime.awaitLib
]]

