__vfs['core/utils/runtime/findFunction.lua'] = [=[function yj.runtime.findFunction(funcName)
	local target = _G
	local parts = {}
	for part in funcName:gmatch("[^.]+") do
		parts[#parts + 1] = part
	end
	for i = 1, #parts - 1 do
		if target and target[parts[i]] then
			target = target[parts[i]]
		else
			return nil
		end
	end
	return target and target[parts[#parts]]
end

return yj.runtime.findFunction
