__vfs['core/utils/str/base64.lua'] = [[yj.str = yj.str or {}

local CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local ENC = {}
for i = 1, #CHARS do
	ENC[CHARS:byte(i)] = i - 1
end

function yj.str.base64Encode(str)
	if type(str) ~= "string" then return nil end
	local len = #str
	local out = {}
	local i = 1
	while i <= len do
		local n = math.min(3, len - i + 1)
		local b1 = str:byte(i) or 0
		local b2 = str:byte(i + 1) or 0
		local b3 = str:byte(i + 2) or 0

		local e1 = b1 >> 2
		local e2 = ((b1 & 0x03) << 4) | (b2 >> 4)
		local e3 = ((b2 & 0x0F) << 2) | (b3 >> 6)
		local e4 = b3 & 0x3F

		out[#out + 1] = CHARS:sub(e1 + 1, e1 + 1)
		out[#out + 1] = CHARS:sub(e2 + 1, e2 + 1)
		out[#out + 1] = (n >= 2) and CHARS:sub(e3 + 1, e3 + 1) or "="
		out[#out + 1] = (n >= 3) and CHARS:sub(e4 + 1, e4 + 1) or "="

		i = i + 3
	end
	return table.concat(out)
end

function yj.str.base64Decode(b64)
	if type(b64) ~= "string" then return nil end

	b64 = b64:gsub("%s+", "")

	local data = b64:gsub("=+$", "")
	if #data % 4 == 1 then return nil, "invalid base64 length" end

	local out = {}
	local acc = 0
	local bits = 0
	for i = 1, #data do
		local c = data:byte(i)
		local v = ENC[c]
		if not v then return nil, "invalid base64 char at " .. i end
		acc = (acc << 6) | v
		bits = bits + 6
		if bits >= 8 then
			bits = bits - 8
			out[#out + 1] = string.char((acc >> bits) & 0xFF)
		end
	end
	return table.concat(out)
end

return yj.str
]]

