__vfs['core/utils/str/parseTypeString.lua'] = [[local M = {}

local SYMBOLS = {
	["<"] = true,
	[">"] = true,
	[","] = true,
	["*"] = true,
	["&"] = true,
	["["] = true,
	["]"] = true,
	["("] = true,
	[")"] = true,
}

local function isIdentChar(c)
	return c:match("[%w_]") ~= nil
end

local function isSpace(c)
	return c:match("%s") ~= nil
end

local function readIdent(s, i)
	local n = #s
	local j = i
	while j <= n do
		local c = s:sub(j, j)
		if isIdentChar(c) then
			j = j + 1
		elseif c == ":" and s:sub(j + 1, j + 1) == ":" then
			j = j + 2
		else
			break
		end
	end
	return s:sub(i, j - 1), j
end

function M.tokenize(s)
	if type(s) ~= "string" then
		log.error("", ": " .. tostring(s))
		return nil
	end

	local tokens = {}
	local i = 1
	local n = #s

	while i <= n do
		local c = s:sub(i, i)

		if isSpace(c) then
			i = i + 1

		elseif isIdentChar(c) then
			local value, nextPos = readIdent(s, i)
			tokens[#tokens + 1] = {
				type = "ident",
				value = value,
				pos = i,
			}
			i = nextPos

		elseif SYMBOLS[c] then
			tokens[#tokens + 1] = {
				type = "symbol",
				value = c,
				pos = i,
			}
			i = i + 1

		else
			local preview = s:sub(math.max(1, i - 5), math.min(n, i + 5))
			log.error("", string.format(
				" '%s'  %d (: ...%s...)",
				c, i, preview
			))
			return nil
		end
	end

	return tokens
end

local Parser = {}
Parser.__index = Parser

function Parser.new(tokens)
	return setmetatable({ tokens = tokens, pos = 1 }, Parser)
end

function Parser:peek(offset)
	return self.tokens[self.pos + (offset or 0)]
end

function Parser:next()
	local t = self.tokens[self.pos]
	self.pos = self.pos + 1
	return t
end

function Parser:expect(value)
	local t = self:next()
	if not t or t.value ~= value then
		log.error("", " '" .. value .. "' '" .. tostring(t and t.value or "<EOF>") .. "'")
		return nil
	end
	return t
end

function Parser:isIdent(value)
	local t = self:peek()
	return t and t.type == "ident" and t.value == value
end

function Parser:isSymbol(value)
	local t = self:peek()
	return t and t.type == "symbol" and t.value == value
end

function Parser:parseType()
	local isConst = false
	while self:isIdent("const") do
		self:next()
		isConst = true
	end

	local base = self:parseBase()
	if not base then return nil end

	while true do
		if self:isSymbol("*") then
			self:next()
			base = { kind = "ptr", base = base }
		elseif self:isSymbol("&") then
			self:next()
			base = { kind = "ref", base = base }
		elseif self:isSymbol("[") then
			self:next()
			local num = self:next()
			local len = tonumber(num and num.value)
			if not len then
				log.error("", ": " .. tostring(num and num.value))
				return nil
			end
			if not self:expect("]") then return nil end
			base = { kind = "array", base = base, length = len }
		else
			break
		end
	end

	if isConst then
		base = { kind = "const", base = base }
	end

	return base
end

function Parser:parseBase()
	local t = self:next()
	if not t or t.type ~= "ident" then
		log.error("", " '" .. tostring(t and t.value) .. "'")
		return nil
	end
	local name = t.value

	if self:isSymbol("<") then
		self:next()
		local args = {}
		args[#args + 1] = self:parseType()
		if not args[#args] then return nil end

		while self:isSymbol(",") do
			self:next()
			local a = self:parseType()
			if not a then return nil end
			args[#args + 1] = a
		end

		if not self:expect(">") then return nil end
		return { kind = "template", name = name, args = args }
	end

	return { kind = "base", name = name }
end

yj = yj or {}

function yj.parseTypeString(typeName)
	local tokens = M.tokenize(typeName)
	if not tokens then return nil end

	local p = Parser.new(tokens)
	local ast = p:parseType()
	if not ast then return nil end

	if p.pos <= #p.tokens then
		local rest = p:peek()
		log.error("", " token '" .. tostring(rest.value) .. "'  " .. typeName)
		return nil
	end

	return ast
end

return yj.parseTypeString
