function yj.str.parseXml(xmlString)
	if type(xmlString) ~= "string" then return {} end
	local result = {}
	for line in xmlString:gmatch("[^\n]+") do
		local tagName, attrName, attrValue = line:match(
			'<([%w_]+)%s+name="([^"]+)"%s+value="([^"]+)"%s*/>')
		if tagName then
			result[tagName] = result[tagName] or {}
			result[tagName][#result[tagName] + 1] = {
				name  = attrName,
				value = attrValue,
			}
		end
	end
	return result
end

function yj.str.generateXml(result)
	if type(result) ~= "table" then return "" end
	local out = {
		"<?xml version='1.0' encoding='utf-8' standalone='yes' ?>",
		"<map>",
	}

	local tags = {}
	for k in pairs(result) do tags[#tags + 1] = k end
	table.sort(tags)
	for _, tagName in ipairs(tags) do
		for _, v in ipairs(result[tagName]) do
			out[#out + 1] = string.format(
				'  <%s name="%s" value="%s"/>',
				tagName, xmlEscape(v.name), xmlEscape(v.value))
		end
	end
	out[#out + 1] = "</map>"
	return table.concat(out, "\n")
end

