__vfs['core/utils/str/xor.lua'] = [[function yj.str.xor(buf, key, offset)
	offset = offset or 0
	if type(key) == "string" then
		local kb = { key:byte(1, #key) }
		key = kb
	end
	local klen = #key
	if klen == 0 then return buf end

	local out = {}
	for i = 1, #buf do
		local b = buf:byte(i)
		if i > offset then
			local k = ((i - offset - 1) % klen) + 1
			out[i] = string.char(b ~ key[k])
		else
			out[i] = string.char(b)
		end
	end
	return table.concat(out)
end

return yj.str.xor
]]

