		for k, _ in pairs(value) do
			if type(k) ~= "number" then total = total + 1 end
		end

		for i, v in ipairs(value) do
			if count >= MAX_ITEMS then
				parts[#parts + 1] = string.format("...  %d ", total)
				break
			end
			parts[#parts + 1] = string.format("[%d]=%s", i, tostring(v))
			count = count + 1
		end

		for k, v in pairs(value) do
			if type(k) ~= "number" then
				if count >= MAX_ITEMS then
					if parts[#parts] and not parts[#parts]:find("") then
						parts[#parts + 1] = string.format("...  %d ", total)
