	if elemShort == "int" or elemShort == "int32" or elemShort == "uint"
		or elemShort == "uint32" or elemShort == "int32_t" or elemShort == "uint32_t" then
		return 4, { get = yj.mem.dword.get, set = yj.mem.dword.set }, "int"
	end
	if elemShort == "float" or elemShort == "float32" then
		return 4, { get = yj.mem.float.get, set = yj.mem.float.set }, "float"
	end
	if elemShort == "int64" or elemShort == "long" or elemShort == "int64_t" then
		return 8, { get = yj.mem.qword.get, set = yj.mem.qword.set }, "int"
	end
	if elemShort == "double" then
		return 8, { get = yj.mem.double.get, set = yj.mem.double.set }, "float"
	end
