local function readVecHeader(addr)
	local v = yj.mem.qword.getBulk({
		addr + VEC_OFF_BEGIN,
		addr + VEC_OFF_END,
		addr + VEC_OFF_CAP,
	})
	local function pick(a)
		for i = 1, #v do
