	if not input or not input[1] then return nil end
	local n = tonumber(input[1])
	if not n then
		gg.alert(L("Dữ liệu nhập không hợp lệ"))
		return nil
	end
	n = math.floor(n)
	if n < 0 or n > VEC_MAX_ELEMS then
