	local oldVals = {}
	if oldSize > 0 then
		local addrs = {}
		for i = 1, oldSize do
			addrs[i] = begin_ + (i - 1) * elemSize
		end
		local vals
		if elemSize == 4 then
			vals = yj.mem.dword.getBulk(addrs)
			if kind == "float" then vals = yj.mem.float.getBulk(addrs) end
		else
			vals = yj.mem.qword.getBulk(addrs)
			if kind == "float" then vals = yj.mem.double.getBulk(addrs) end
		end
		for i = 1, oldSize do
			oldVals[i] = vals[i] and vals[i].value or 0
		end
	end

	local newSize = promptVectorSize(label, oldSize)
	if newSize == nil then return false end

	local newVals = {}
	if newSize > 0 then
		local prompts, defaults, types = {}, {}, {}
		for i = 1, newSize do
			prompts[i] = string.format("[%d]", i)
			defaults[i] = tostring(oldVals[i] or 0)
			types[i] = kind == "float" and "number" or "number"
		end
		local input = gg.prompt(prompts, defaults, types)
		if not input then return false end
		for i = 1, newSize do
			local n = tonumber(input[i])
			if n == nil then n = oldVals[i] or 0 end
			newVals[i] = n
		end
	end

	local needBytes = newSize * elemSize
	local capBytes  = (begin_ ~= 0 and cap_ > begin_) and (cap_ - begin_) or 0

	if newSize == oldSize then

		local edits = {}
		for i = 1, newSize do
			if newVals[i] ~= oldVals[i] then
				edits[#edits + 1] = { address = begin_ + (i-1)*elemSize, flags = (elemSize==4 and (kind=="float" and 16 or 4) or (kind=="float" and 64 or 32)), value = newVals[i] }
			end
		end
		if #edits > 0 then gg.setValues(edits) end
		gg.toast(L(""))
		return true

	elseif newSize < oldSize then

		local edits = {}
		for i = 1, newSize do
			if newVals[i] ~= oldVals[i] then
				edits[#edits + 1] = { address = begin_ + (i-1)*elemSize, flags = (elemSize==4 and (kind=="float" and 16 or 4) or (kind=="float" and 64 or 32)), value = newVals[i] }
			end
		end
		if #edits > 0 then gg.setValues(edits) end
		writeVecHeader(vecAddr, begin_, begin_ + needBytes, cap_, false)
		gg.toast(L(""))
		return true

	else
		if capBytes >= needBytes then

			local edits = {}
			for i = 1, newSize do
				if i > oldSize or newVals[i] ~= oldVals[i] then
					edits[#edits + 1] = { address = begin_ + (i-1)*elemSize, flags = (elemSize==4 and (kind=="float" and 16 or 4) or (kind=="float" and 64 or 32)), value = newVals[i] }
				end
			end
			if #edits > 0 then gg.setValues(edits) end
			writeVecHeader(vecAddr, begin_, begin_ + needBytes, cap_, false)
			gg.toast(L(""))
			return true
		else

			local newBuf = yj.mem.allocZeroPage(needBytes)
			if not newBuf or newBuf == 0 then
				gg.alert(L("Không thể cấp phát bộ nhớ"))
				return false
			end
			local edits = {}
			for i = 1, newSize do
				edits[#edits + 1] = { address = newBuf + (i-1)*elemSize, flags = (elemSize==4 and (kind=="float" and 16 or 4) or (kind=="float" and 64 or 32)), value = newVals[i] }
			end
			gg.setValues(edits)
			writeVecHeader(vecAddr, newBuf, newBuf + needBytes, newBuf + needBytes, true)
			gg.toast(L(""))
			return true
		end
	end
end

local function copyString24(src, dst)
	local vals = gg.getValues({
		{ address = src + 0x00, flags = 4 },
		{ address = src + 0x04, flags = 4 },
		{ address = src + 0x08, flags = 4 },
		{ address = src + 0x0C, flags = 4 },
		{ address = src + 0x10, flags = 4 },
		{ address = src + 0x14, flags = 4 },
	})
	local edits = {}
	for i = 1, 6 do
		edits[i] = { address = dst + (i-1)*4, flags = 4, value = vals[i] and vals[i].value or 0 }
	end
	gg.setValues(edits)
end

local function editVectorString(baseAddr, field, label)
	local STRIDE = 0x18
	local vecAddr = baseAddr + (field.offset or 0)

	local begin_, end_, cap_ = readVecHeader(vecAddr)
	local oldSize = 0
	if begin_ ~= 0 and end_ > begin_ then
		oldSize = math.floor((end_ - begin_) / STRIDE)
		if oldSize > VEC_MAX_ELEMS then oldSize = VEC_MAX_ELEMS end
	end
	local oldStrs = {}
	if oldSize > 0 then
		local addrs = {}
		for i = 1, oldSize do addrs[i] = begin_ + (i-1)*STRIDE end
		local results = yj.mem.stdstring.readBulk(addrs)
		for i = 1, #results do
			for j = 1, oldSize do
				if results[i].address == addrs[j] then
					oldStrs[j] = results[i].str
				end
			end
		end
	end

	local newSize = promptVectorSize(label, oldSize)
	if newSize == nil then return false end

	local newStrs = {}
	if newSize > 0 then
		local prompts, defaults, types = {}, {}, {}
		for i = 1, newSize do
			prompts[i] = string.format("[%d]", i)
			defaults[i] = oldStrs[i] or ""
			types[i] = "text"
		end
		local input = gg.prompt(prompts, defaults, types)
		if not input then return false end
		for i = 1, newSize do
			newStrs[i] = input[i] or (oldStrs[i] or "")
		end
	end

	local needBytes = newSize * STRIDE
	local capBytes  = (begin_ ~= 0 and cap_ > begin_) and (cap_ - begin_) or 0

	local function writeElem(dstAddr, i)
		if i <= oldSize and newStrs[i] == oldStrs[i] then

			copyString24(begin_ + (i-1)*STRIDE, dstAddr)
		else

			yj.mem.stdstring.write(dstAddr, newStrs[i] or "")
		end
	end

	if newSize == oldSize then
		for i = 1, newSize do
			if newStrs[i] ~= oldStrs[i] then
				yj.mem.stdstring.write(begin_ + (i-1)*STRIDE, newStrs[i] or "")
			end
		end
		gg.toast(L(""))
		return true

	elseif newSize < oldSize then

		for i = 1, newSize do
			if newStrs[i] ~= oldStrs[i] then
				yj.mem.stdstring.write(begin_ + (i-1)*STRIDE, newStrs[i] or "")
			end
		end
		writeVecHeader(vecAddr, begin_, begin_ + needBytes, cap_, false)
		gg.toast(L(""))
		return true

	else
		if capBytes >= needBytes then

			for i = 1, newSize do
				if i <= oldSize then
					if newStrs[i] ~= oldStrs[i] then
						yj.mem.stdstring.write(begin_ + (i-1)*STRIDE, newStrs[i] or "")
					end
				else
					yj.mem.stdstring.write(begin_ + (i-1)*STRIDE, newStrs[i] or "")
				end
			end
			writeVecHeader(vecAddr, begin_, begin_ + needBytes, cap_, false)
			gg.toast(L(""))
			return true
		else

			local newBuf = yj.mem.allocZeroPage(needBytes)
			if not newBuf or newBuf == 0 then
				gg.alert(L("Không thể cấp phát bộ nhớ"))
				return false
			end
			for i = 1, newSize do
				writeElem(newBuf + (i-1)*STRIDE, i)
			end
			writeVecHeader(vecAddr, newBuf, newBuf + needBytes, newBuf + needBytes, true)
			gg.toast(L(""))
			return true
		end
	end
end

local RPF_OFF_ELEMENTS       = 0x0
local RPF_OFF_CURRENT_SIZE   = 0x8
local RPF_OFF_ALLOCATED_SIZE = 0xC
local RPF_OFF_TOTAL_SIZE     = 0x10
local RPF_STR_SIZE = 0x18

local function rpfCeilPow2(n)
	if n <= 1 then return 1 end
	n = n - 1
	n = n | (n >> 1)
	n = n | (n >> 2)
	n = n | (n >> 4)
	n = n | (n >> 8)
	n = n | (n >> 16)
	return n + 1
end

local function rpfReadHeader(addr)
	local vals = gg.getValues({
		{ address = addr + RPF_OFF_ELEMENTS,       flags = 32 },
		{ address = addr + RPF_OFF_CURRENT_SIZE,   flags = 4  },
		{ address = addr + RPF_OFF_ALLOCATED_SIZE, flags = 4  },
		{ address = addr + RPF_OFF_TOTAL_SIZE,     flags = 4  },
	})
	if #vals < 4 then return nil end
	return {
		elements      = vals[1].value or 0,
		currentSize   = vals[2].value or 0,
		allocatedSize = vals[3].value or 0,
		totalSize     = vals[4].value or 0,
	}
end

local function rpfWriteHeader(addr, h)
	local edits = {}
	if h.elements ~= nil then
		edits[#edits + 1] = { address = addr + RPF_OFF_ELEMENTS, flags = 32, value = h.elements }
	end
	if h.currentSize ~= nil then
		edits[#edits + 1] = { address = addr + RPF_OFF_CURRENT_SIZE, flags = 4, value = h.currentSize }
	end
	if h.allocatedSize ~= nil then
		edits[#edits + 1] = { address = addr + RPF_OFF_ALLOCATED_SIZE, flags = 4, value = h.allocatedSize }
	end
	if h.totalSize ~= nil then
		edits[#edits + 1] = { address = addr + RPF_OFF_TOTAL_SIZE, flags = 4, value = h.totalSize }
	end
	if #edits > 0 then gg.setValues(edits) end
end

local function rpfReadPtrs(elementsAddr, count)
	if count <= 0 or not elementsAddr or elementsAddr == 0 then return {} end
	local addrs = {}
	for i = 1, count do
		addrs[i] = elementsAddr + (i - 1) * 8
	end
	local vals = yj.mem.qword.getBulk(addrs)
	local out = {}
	for i = 1, count do out[i] = 0 end
	for i = 1, #vals do
		for j = 1, count do
			if vals[i].address == addrs[j] then
				out[j] = vals[i].value or 0
			end
		end
	end
	return out
end

local function editRPFString(baseAddr, field, label)
	local rpfAddr = baseAddr + (field.offset or 0)

	local h = rpfReadHeader(rpfAddr)
	if not h then
		gg.alert(L(" RepeatedPtrField "))
		return false
	end

	local oldSize = h.currentSize
	if oldSize < 0 then oldSize = 0 end
	if oldSize > VEC_MAX_ELEMS then oldSize = VEC_MAX_ELEMS end

	local oldPtrs = rpfReadPtrs(h.elements, oldSize)
	local oldStrs = {}
	if oldSize > 0 then

		local validAddrs = {}
		local validIdx = {}
		for i = 1, oldSize do
			if oldPtrs[i] and oldPtrs[i] ~= 0 then
				validAddrs[#validAddrs + 1] = oldPtrs[i]
				validIdx[#validIdx + 1] = i
			end
		end
		if #validAddrs > 0 then
			local results = yj.mem.stdstring.readBulk(validAddrs)
			for r = 1, #results do
				for k = 1, #validAddrs do
					if results[r].address == validAddrs[k] then
						oldStrs[validIdx[k]] = results[r].str
					end
				end
			end
		end
	end

	local newSize = promptVectorSize(label, oldSize)
	if newSize == nil then return false end

	local newStrs = {}
	if newSize > 0 then
		local prompts, defaults, types = {}, {}, {}
		for i = 1, newSize do
			prompts[i] = string.format("[%d]", i)
			defaults[i] = oldStrs[i] or ""
			types[i] = "text"
		end
		local input = gg.prompt(prompts, defaults, types)
		if not input then return false end
		for i = 1, newSize do
			newStrs[i] = input[i] or (oldStrs[i] or "")
		end
	end

	if newSize == oldSize then

		for i = 1, newSize do
			if newStrs[i] ~= oldStrs[i] and oldPtrs[i] and oldPtrs[i] ~= 0 then
				yj.mem.stdstring.write(oldPtrs[i], newStrs[i] or "")
			end
		end
		gg.toast(L(""))
		return true

	elseif newSize < oldSize then

		for i = 1, newSize do
			if newStrs[i] ~= oldStrs[i] and oldPtrs[i] and oldPtrs[i] ~= 0 then
				yj.mem.stdstring.write(oldPtrs[i], newStrs[i] or "")
			end
		end
		rpfWriteHeader(rpfAddr, { currentSize = newSize })
		gg.toast(L(""))
		return true

	else

		local canInPlace = h.totalSize >= newSize

		if canInPlace then

			for i = 1, oldSize do
				if newStrs[i] ~= oldStrs[i] and oldPtrs[i] and oldPtrs[i] ~= 0 then
					yj.mem.stdstring.write(oldPtrs[i], newStrs[i] or "")
				end
			end

			for i = oldSize + 1, newSize do
				local newStrPtr = yj.mem.allocZeroPage(RPF_STR_SIZE)
				if not newStrPtr or newStrPtr == 0 then
					gg.alert(L("Không thể cấp phát bộ nhớ"))
					return false
				end
				yj.mem.stdstring.write(newStrPtr, newStrs[i] or "")
				yj.mem.qword.set(h.elements + (i - 1) * 8, newStrPtr)
			end
			rpfWriteHeader(rpfAddr, {
				currentSize = newSize,
				allocatedSize = math.max(h.allocatedSize, newSize),
			})
			gg.toast(L(""))
			return true

		else

			local newTotal = rpfCeilPow2(newSize)
			local elemsBytes = newTotal * 8
			local newElems = yj.mem.allocZeroPage(elemsBytes)
			if not newElems or newElems == 0 then
				gg.alert(L("Không thể cấp phát bộ nhớ"))
				return false
			end

			local edits = {}
			for i = 1, newSize do
				local strPtr
				if i <= oldSize and oldPtrs[i] and oldPtrs[i] ~= 0 then
					if newStrs[i] == oldStrs[i] then

						strPtr = oldPtrs[i]
					else

						strPtr = yj.mem.allocZeroPage(RPF_STR_SIZE)
						if not strPtr or strPtr == 0 then
							gg.alert(L("Không thể cấp phát bộ nhớ"))
							return false
						end
						yj.mem.stdstring.write(strPtr, newStrs[i] or "")
					end
				else

					strPtr = yj.mem.allocZeroPage(RPF_STR_SIZE)
					if not strPtr or strPtr == 0 then
						gg.alert(L("Không thể cấp phát bộ nhớ"))
						return false
					end
					yj.mem.stdstring.write(strPtr, newStrs[i] or "")
				end

				edits[#edits + 1] = {
					address = newElems + (i - 1) * 8,
					flags = 32,
					value = strPtr,
				}
			end

			if #edits > 0 then gg.setValues(edits) end

			rpfWriteHeader(rpfAddr, {
				elements      = newElems,
				currentSize   = newSize,
				allocatedSize = newSize,
				totalSize     = newTotal,
			})
			gg.toast(L(""))
			return true
		end
	end
end

local function editRPFSafeInt32(baseAddr, field, label)
	local rpfAddr = baseAddr + (field.offset or 0)

	local h = rpfReadHeader(rpfAddr)
	if not h then
		gg.alert(L(" RepeatedPtrField "))
		return false
	end

	local oldSize = h.currentSize
	if oldSize < 0 then oldSize = 0 end
	if oldSize > VEC_MAX_ELEMS then oldSize = VEC_MAX_ELEMS end

	local oldPtrs = rpfReadPtrs(h.elements, oldSize)

	local SI = yj.types.safeint or loadModule("core/types/safeint.lua")
	local oldVals, prompts, defaults, types = {}, {}, {}, {}
	for i = 1, oldSize do
		local v = nil
		if oldPtrs[i] and oldPtrs[i] ~= 0 then
			v = SI.SafeInt32.get(oldPtrs[i])
		end
		oldVals[i] = v
		prompts[i] = string.format("[%d]", i)
		defaults[i] = (v ~= nil) and tostring(v) or "0"
		types[i] = "number"
	end

	local newSize = promptVectorSize(label, oldSize)
	if newSize == nil then return false end

	local newVals = {}
	if newSize > 0 then
		local p2, d2, t2 = {}, {}, {}
		for i = 1, newSize do
			p2[i] = string.format("[%d]", i)
			d2[i] = defaults[i] or "0"
			t2[i] = "number"
		end
		local input = gg.prompt(p2, d2, t2)
		if not input then return false end
		for i = 1, newSize do
			local n = tonumber(input[i])
			if n == nil then n = oldVals[i] or 0 end
			newVals[i] = n
		end
	end

	if newSize == oldSize then

		for i = 1, newSize do
			if oldVals[i] ~= newVals[i] then
				local p = oldPtrs[i]
				if not p or p == 0 then
					p = yj.mem.allocZeroPage(S32_SIZE or 0x28)
					if not p or p == 0 then
						gg.alert(L("Không thể cấp phát bộ nhớ"))
						return false
					end
					yj.mem.qword.set(h.elements + (i - 1) * 8, p)
				end
				SI.SafeInt32.set(p, newVals[i])
			end
		end
		gg.toast(L(""))
		return true

	elseif newSize < oldSize then

		for i = 1, newSize do
			if oldVals[i] ~= newVals[i] and oldPtrs[i] and oldPtrs[i] ~= 0 then
				SI.SafeInt32.set(oldPtrs[i], newVals[i])
			end
		end
		rpfWriteHeader(rpfAddr, { currentSize = newSize })
		gg.toast(L(""))
		return true

	else
		local canInPlace = h.totalSize >= newSize
		if canInPlace then

			for i = 1, newSize do
				if i <= oldSize then
					if oldVals[i] ~= newVals[i] and oldPtrs[i] and oldPtrs[i] ~= 0 then
						SI.SafeInt32.set(oldPtrs[i], newVals[i])
					end
				else
					local p = yj.mem.allocZeroPage(S32_SIZE or 0x28)
					if not p or p == 0 then
						gg.alert(L("Không thể cấp phát bộ nhớ"))
						return false
					end
					SI.SafeInt32.set(p, newVals[i])
					yj.mem.qword.set(h.elements + (i - 1) * 8, p)
				end
			end
			rpfWriteHeader(rpfAddr, {
				currentSize   = newSize,
				allocatedSize = math.max(h.allocatedSize, newSize),
			})
			gg.toast(L(""))
			return true
		else

			local newTotal = rpfCeilPow2(newSize)
			local newElems = yj.mem.allocZeroPage(newTotal * 8)
			if not newElems or newElems == 0 then
				gg.alert(L("Không thể cấp phát bộ nhớ"))
				return false
			end
			for i = 1, newSize do
				local p
				if i <= oldSize and oldPtrs[i] and oldPtrs[i] ~= 0
				   and oldVals[i] == newVals[i] then
					p = oldPtrs[i]
				else
					p = yj.mem.allocZeroPage(S32_SIZE or 0x28)
					if not p or p == 0 then
						gg.alert(L("Không thể cấp phát bộ nhớ"))
						return false
					end
					SI.SafeInt32.set(p, newVals[i] or 0)
				end
				yj.mem.qword.set(newElems + (i - 1) * 8, p)
			end
			rpfWriteHeader(rpfAddr, {
				elements      = newElems,
				currentSize   = newSize,
				allocatedSize = newSize,
				totalSize     = newTotal,
			})
			gg.toast(L(""))
			return true
		end
	end
end

local RF_OFF_SIZE     = 0x8
local RF_OFF_ELEMENTS = 0x0

local function rfReadHeader(addr)
	local v = gg.getValues({
		{ address = addr + RF_OFF_SIZE,     flags = 4  },
		{ address = addr + RF_OFF_ELEMENTS, flags = 32 },
	})
	return (v[1] and v[1].value) or 0,
		   (v[2] and v[2].value) or 0
end

local function rfWriteHeader(addr, size, elements)
	local edits = {}
	if size ~= nil then
		edits[#edits + 1] = { address = addr + RF_OFF_SIZE, flags = 4, value = size }
	end
	if elements ~= nil then
		edits[#edits + 1] = { address = addr + RF_OFF_ELEMENTS, flags = 32, value = elements }
	end
	if #edits > 0 then gg.setValues(edits) end
end

local function editRepeatedField(baseAddr, field, label, elemSize, rw, kind)
	local rfAddr = baseAddr + (field.offset or 0)

	local oldSize, elems = rfReadHeader(rfAddr)
	if oldSize < 0 then oldSize = 0 end
	if oldSize > VEC_MAX_ELEMS then oldSize = VEC_MAX_ELEMS end

	local oldVals = {}
	if oldSize > 0 and elems and elems ~= 0 then
		local addrs = {}
		for i = 1, oldSize do
			addrs[i] = elems + (i - 1) * elemSize
		end
		local vals
		if elemSize == 4 then
			vals = (kind == "float") and yj.mem.float.getBulk(addrs) or yj.mem.dword.getBulk(addrs)
		else
			vals = (kind == "float") and yj.mem.double.getBulk(addrs) or yj.mem.qword.getBulk(addrs)
		end
		for i = 1, oldSize do
			oldVals[i] = vals[i] and vals[i].value or 0
		end
	end

	local newSize = promptVectorSize(label, oldSize)
	if newSize == nil then return false end

	local newVals = {}
	if newSize > 0 then
		local prompts, defaults, types = {}, {}, {}
		for i = 1, newSize do
			prompts[i] = string.format("[%d]", i)
			defaults[i] = tostring(oldVals[i] or 0)
			types[i] = "number"
		end
		local input = gg.prompt(prompts, defaults, types)
		if not input then return false end
		for i = 1, newSize do
			local n = tonumber(input[i])
			if n == nil then n = oldVals[i] or 0 end
			newVals[i] = n
		end
	end

	local flag = (elemSize == 4) and (kind == "float" and 16 or 4)
								or (kind == "float" and 64 or 32)

	if newSize == oldSize then

		local edits = {}
		for i = 1, newSize do
			if newVals[i] ~= oldVals[i] then
				edits[#edits + 1] = {
					address = elems + (i-1)*elemSize,
					flags = flag,
					value = newVals[i],
				}
			end
		end
		if #edits > 0 then gg.setValues(edits) end
		gg.toast(L(""))
		return true

	elseif newSize < oldSize then

		local edits = {}
		for i = 1, newSize do
			if newVals[i] ~= oldVals[i] then
				edits[#edits + 1] = {
					address = elems + (i-1)*elemSize,
					flags = flag,
					value = newVals[i],
				}
			end
		end
		if #edits > 0 then gg.setValues(edits) end
		rfWriteHeader(rfAddr, newSize, nil)
		gg.toast(L(""))
		return true

	else

		if newSize == 0 then
			rfWriteHeader(rfAddr, 0, 0)
			gg.toast(L(""))
			return true
		end

		local needBytes = newSize * elemSize
		local newBuf = yj.mem.allocZeroPage(needBytes)
		if not newBuf or newBuf == 0 then
			gg.alert(L("Không thể cấp phát bộ nhớ"))
			return false
		end

		local edits = {}
		for i = 1, newSize do
			edits[#edits + 1] = {
				address = newBuf + (i-1)*elemSize,
				flags = flag,
				value = newVals[i],
			}
		end
		if #edits > 0 then gg.setValues(edits) end

		rfWriteHeader(rfAddr, newSize, newBuf)
		gg.toast(L(""))
		return true
	end
end

function yj.types.show.editPtrListElements(ptrs, reader, title, opts)
	opts = opts or {}
	local back = opts.back
	local maxItems = opts.maxItems or 64

	local function backTo()
		if back then return back() end
	end

	if type(ptrs) ~= "table" or #ptrs == 0 then
		gg.alert(title .. "\n\n" .. L(""))
		return backTo()
	end

	if #ptrs > maxItems then
		gg.alert(string.format("%s\n\n%s", title,
			L("") .. #ptrs .. L("")))
		return backTo()
	end

	local oldVals, prompts, defaults, types = {}, {}, {}, {}
	for i = 1, #ptrs do
		local v = reader.get(ptrs[i])
		oldVals[i] = v
		prompts[i] = string.format("[%d]", i)
		if v == nil then
			defaults[i] = "0"
		else
			defaults[i] = tostring(v)
		end
		types[i] = "number"
	end

	local input = gg.prompt(prompts, defaults, types)
	if not input then return backTo() end

	local changed = 0
	for i = 1, #ptrs do
		local nv = tonumber(input[i])
		if nv ~= nil and nv ~= oldVals[i] then
			if reader.set(ptrs[i], nv) then
				changed = changed + 1
			end
		end
	end

	if changed > 0 then
		gg.toast(string.format(L(" %d "), changed))
		return true
	else
		gg.toast(L(""))
		return false
	end
end

function yj.types.show.dispatch(baseAddr, field, label)
	label = label or field.name or tostring(field.offset)

	local obj = yj.types.resolve(field.type)
	if not obj then
		gg.alert(string.format("%s\n(%s)\n\n%s",
			label, field.type, L("")))
		return false
	end

	local value, err = yj.types.get(baseAddr, field)
	if value == nil then
		gg.alert(string.format("%s\n(%s)\n\n%s",
			label, field.type, err or L("")))
		return false
	end

	if type(value) == "table" then
		local bt = baseTypeName(field.type)
		if bt == "Rect" then
			return editRect(baseAddr, field, label)
		end
		if bt == "Color3B" then
			return editColorB(baseAddr, field, label, false)
		end
		if bt == "Color4B" then
			return editColorB(baseAddr, field, label, true)
		end
		if bt == "Color4F" then
			return editColorF(baseAddr, field, label)
		end

		if bt == "vector" then
			local elemShort = parseVectorElem(field.type)
			if elemShort then
				local elemSize, rw, kind = scalarRW(elemShort)
				if elemSize then
					return editVectorScalar(baseAddr, field, label, elemSize, rw, kind)
				end
				if elemShort == "string" or elemShort == "std::string" then
					return editVectorString(baseAddr, field, label)
				end
			end

		end

		if bt == "RepeatedPtrField" then
			local elemShort = parseVectorElem(field.type)
			if elemShort == "string" or elemShort == "std::string" then
				return editRPFString(baseAddr, field, label)
			end
			if elemShort == "SafeInt32" then
				return editRPFSafeInt32(baseAddr, field, label)
			end

		end
		if bt == "RepeatedField" then
			local elemShort = parseVectorElem(field.type)
			if elemShort then
				local elemSize, rw, kind = scalarRW(elemShort)
				if elemSize then
					return editRepeatedField(baseAddr, field, label, elemSize, rw, kind)
				end
			end

		end

	end

	if type(value) == "table" then
		local bt = baseTypeName(field.type)
		local hint = L("")

		if field.type:match("^array<") or field.type:match("%[%d+%]$") then
			hint = L("")
		end
		gg.alert(string.format("%s = %s\n(%s)\n\n%s",
			label, formatValue(value), field.type, hint))
		return false
	end

	if type(value) == "string" then
		local input = gg.prompt(
			{ string.format("%s\n(%s)\n%s", label, field.type, L("")) },
			{ value },
			{ "text" }
		)
		if not input or not input[1] or input[1] == value then
			return false
		end
		local ok, serr = yj.types.set(baseAddr, field, input[1])
		if ok then
			gg.toast(L(""))
			return true
		end
		gg.alert(L("") .. ": " .. tostring(serr))
		return false
	end

	if type(value) == "boolean" then
		local act = gg.alert(
			string.format("%s = %s\n(%s)", label, tostring(value), field.type),
			L(" true"), L(" false"), L("Hủy")
		)
		if act == 1 then
			yj.types.set(baseAddr, field, true)
			gg.toast(L(""))
			return true
		elseif act == 2 then
			yj.types.set(baseAddr, field, false)
			gg.toast(L(""))
			return true
		end
		return false
	end

	if type(value) == "number" then
		local input = gg.prompt(
			{ string.format("%s\n(%s)\n%s", label, field.type, L("")) },
			{ tostring(value) },
			{ "number" }
		)
		if not input or not input[1] then return false end
		local newVal = tonumber(input[1])
		if newVal == nil then
			gg.alert(L("Dữ liệu nhập không hợp lệ"))
			return false
		end
		if newVal == value then return false end
		local ok, serr = yj.types.set(baseAddr, field, newVal)
		if ok then
			gg.toast(L(""))
			return true
		end
		gg.alert(L("") .. ": " .. tostring(serr))
		return false
	end

	gg.alert(string.format("%s = %s\n(%s)\n\n%s",
		label, formatValue(value), field.type, L("")))
	return false
end

return yj.types.show
]=]

