__vfs['modules/boot/findGameStatus.lua'] = [[yj.str.stringToAob = yj.str.stringToAob or loadModule("core/utils/str/stringToAob.lua")

function yj.findGameStatus()
	local SEARCH_REGIONS = {
		{region = gg.REGION_C_ALLOC, name = "C_ALLOC"},
		{region = gg.REGION_OTHER,   name = "OTHER"},
	}

	local hex, header = yj.str.stringToAob("startup_count", true)

	local VALID_VERSIONS = {
		[65792]    = true,
		[65793]    = true,
		[16843008] = true,
		[16843009] = true,
	}

	for _, cfg in ipairs(SEARCH_REGIONS) do
		log.info(": ", cfg.name)
		gg.clearResults()
		gg.setRanges(cfg.region)
		gg.searchNumber(hex, 1)
		gg.refineNumber(header, 1)

		local count = gg.getResultsCount()
		local scanResults = gg.getResults(count)
		gg.clearResults()
		log.info(string.format("%s AOB: %d", cfg.name, count))

		local statusHits = {}
		local statusRawHits = {}
		local ptrZero, verMismatch = 0, 0

		local ptrRequests = {}
		for i, d in ipairs(scanResults) do
			ptrRequests[i] = {
				address = d.address + 0x20,
				flags = 32,
			}
		end
		local ptrValues = #ptrRequests > 0 and gg.getValues(ptrRequests) or {}

		local verRequests = {}
		local validPtrs = {}
		for i, ptr in ipairs(ptrValues) do
			local pv = tonumber(ptr.value)
			if not pv or pv < 0x10000 or pv > 0x7FFFFFFFFFFF then
				ptrZero = ptrZero + 1
			else
				validPtrs[#validPtrs + 1] = pv
				verRequests[#verRequests + 1] = {
					address = pv + 0x10,
					flags = 4,
				}
			end
		end
		local verValues = #verRequests > 0 and gg.getValues(verRequests) or {}

		local secondRequests = {}
		for i, ver in ipairs(verValues) do
			local v = tonumber(ver.value)
			local pv = validPtrs[i]
			if VALID_VERSIONS[v] then
				statusRawHits[#statusRawHits + 1] = ver.address
				secondRequests[#secondRequests + 1] = {
					address = pv + 0x80,
					flags = 32,
				}
			else
				verMismatch = verMismatch + 1
			end
		end

		local secondValues =
			#secondRequests > 0 and gg.getValues(secondRequests) or {}
		for i, tp in ipairs(secondValues) do
			local tpv = tonumber(tp.value)
			if tpv and tpv ~= 0 then

				local td = gg.getValues({
					{address = tpv, flags = 4}
				})[1]
				if td then
					statusHits[#statusHits + 1] = td.address
				end
			end
		end

		log.info(string.format(
			"%s | =%d | =%d | GameStatus=%d",
			cfg.name, ptrZero, verMismatch, #statusHits
		))

		if #statusHits > 0 then
			return {
				address    = statusHits[1],
				rawAddress = statusRawHits[1],
				region     = cfg.region,
				name       = cfg.name,
			}
		end
	end

	log.warn("GameStatus ")
	return nil
end

return yj.findGameStatus
]]

__vfs['modules/get/data/ActiveEventsAddrData.lua'] = [[local _EventDefinition = yj.runtime.requireClass("EventDefinition") or {}

function getDataActiveEventsAddrData(trimData)
	if type(trimData) ~= "table" then
		log.error("ActiveEventsAddrData: trimData ")
		return nil
	end
	local id = trimData.id
	if type(id) ~= "string" or id == "" then
		log.error("ActiveEventsAddrData: trimData.id ")
		return nil
	end

	if type(Stack.Data.ActiveEventsAddrData) ~= "table" then
		Stack.Data.ActiveEventsAddrData = {}
	end
	local cached = Stack.Data.ActiveEventsAddrData[id]
	if cached and cached.address then
		return cached
	end

	local nameOffset      = _EventDefinition.name and _EventDefinition.name.offset
	local idOffset        = _EventDefinition.id and _EventDefinition.id.offset
	local startTimeOffset = _EventDefinition.startTime and _EventDefinition.startTime.offset
	if not nameOffset or not idOffset or not startTimeOffset then
		log.warn("ActiveEventsAddrData: EventDefinition metadata ")
		return nil
	end

	local startTime = tonumber(trimData.startTime)
	local endTime   = tonumber(trimData.endTime)
	if not startTime or not endTime then
		log.error("ActiveEventsAddrData: startTime/endTime ",
			tostring(trimData.startTime), tostring(trimData.endTime))
		return nil
	end
	local aob, aobErr = yj.cast.numArrayToAob({ startTime, endTime })
	if not aob then
		log.error("ActiveEventsAddrData: AOB ", tostring(aobErr))
		return nil
	end

	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	gg.searchNumber(aob, 1)
	local count = gg.getResultsCount()
	if not count or count < 1 then
		log.warn("ActiveEventsAddrData: AOB ")
		gg.clearResults()
		return nil
	end
	local hits = gg.getResults(count)
	gg.clearResults()

	local structAddrList = {}
	local idAddrList = {}
	for i = 1, #hits do
		local structAddr = hits[i].address - startTimeOffset
		structAddrList[i] = structAddr
		idAddrList[i] = structAddr + idOffset
	end

	local idResults = yj.mem.stdstring.readBulk(idAddrList)
	local idAddrToStr = {}
	for _, item in ipairs(idResults) do
		if item and item.address then
			idAddrToStr[item.address] = item.str or ""
		end
	end

	local matchedStructs = {}
	for i = 1, #structAddrList do
		local structAddr = structAddrList[i]
		if idAddrToStr[structAddr + idOffset] == id then
			matchedStructs[#matchedStructs + 1] = structAddr
		end
	end
	if #matchedStructs < 1 then
		log.warn("ActiveEventsAddrData: id ", id)
		return nil
	end

