__vfs['modules/get/data/ActiveEventsAtPresentData.lua'] = [[if type(getDataActiveEventsAllData) ~= "function" then
	loadModule("modules/get/data/ActiveEventsAllData.lua")
end

function getDataActiveEventsAtPresentData(key)

	if type(key) ~= "string" or key == "" then
		log.error("ActiveEventsAtPresentData: key ")
		return nil
	end

	local allData = getDataActiveEventsAllData()
	if not allData or not allData.trimData then
		log.error("ActiveEventsAtPresentData: ActiveEventsAllData ")
		return nil
	end

	local events = allData.trimData[key]
	if type(events) ~= "table" or #events < 1 then
		log.warn("ActiveEventsAtPresentData: ", key)
		return nil
	end

	local currentTimestamp = os.time()
	local candidates = {}
	for i = 1, #events do
		local ev = events[i]

		if ev and currentTimestamp < ev.endTime and currentTimestamp > ev.startTime then
			candidates[#candidates + 1] = ev
		end
	end

	if #candidates == 0 then
		log.warn("ActiveEventsAtPresentData: ", key)
		return nil
	end
	if #candidates == 1 then
		return candidates[1]
	end

	table.sort(candidates, function(a, b) return a.endTime < b.endTime end)
	log.info("ActiveEventsAtPresentData: ",
		key, #candidates, ":", candidates[1].id)
	return candidates[1]
end

return getDataActiveEventsAtPresentData
]]

