			addrToStr[item.address] = item.str or ""
		end
	end

	local out = {}
	for i = 1, #vals do
		local base = vals[i]
		local idVal = addrToStr[base + idOffset]
		if idVal and idVal ~= "" then
			out[#out + 1] = {
				address = base,
				id      = idVal,
				name    = addrToStr[base + nameOffset],
			}
		end
	end

	Stack.Data.DriverAnimationsData = out
	Stack.Data.DriverAnimationsDataLoaded = true
	return out
end

return getDataDriverAnimationsData
