		end
	end

	local data = {}
	for partName, baseList in pairs(baseListByPart) do
		data[partName] = {}
		for i, base in ipairs(baseList) do
			data[partName][i] = {
				address = base,
				id      = addrToStr[base + idOffset],
				name    = addrToStr[base + nameOffset],
