function getOffsetLeagueTasksData(force)
	if type(Stack.Data.LeagueTasksData) ~= "table" then
		Stack.Data.LeagueTasksData = {}
	end
	if Stack.Data.LeagueTasksDataLoaded and not force then
		return Stack.Data.LeagueTasksData
	end
	if force then
		Stack.Data.LeagueTasksData = {}
		Stack.Data.LeagueTasksDataLoaded = false
	end

	local definition = leagueTask
	if not definition then return nil end

	local idOffset     = _LootDefinition.id         and _LootDefinition.id.offset
	local rewardOffset = _LeagueTaskDefinition.reward and _LeagueTaskDefinition.reward.offset
	if not idOffset or not rewardOffset then
		log.warn("LeagueTasksData: metadata ")
		return nil
	end

	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	gg.searchNumber(definition.id, 1)
	gg.refineNumber(definition.head, 1)
	local aobCount = gg.getResultsCount()
	if not aobCount or aobCount < 1 then
		log.warn("LeagueTasksData: AOB ")
		return nil
	end
	local aobHits = gg.getResults(aobCount)
	gg.clearResults()

	local structs = {}
	local idAddrList = {}
	for i, hit in ipairs(aobHits) do
		local structAddr = hit.address - idOffset
		structs[i]    = { address = structAddr, flags = 4 }
		idAddrList[i] = structAddr + idOffset
	end

	local idResults = yj.mem.stdstring.readBulk(idAddrList)
	local structAddrToId = {}
	for _, r in ipairs(idResults) do
		if r and r.address and r.str and r.str ~= "" then
			structAddrToId[r.address - idOffset] = r.str
		end
	end

	gg.loadResults(structs)
	gg.searchPointer(0x0)
	local ptrCount = gg.getResultsCount()
	if not ptrCount or ptrCount < 1 then
		log.warn("LeagueTasksData: ")
		return nil
	end
	local ptrHits = gg.getResults(ptrCount)
	gg.clearResults()

	local out = {}
	for _, hit in ipairs(ptrHits) do
		local rewardId = structAddrToId[hit.value]
		if rewardId then
			out[#out + 1] = {
				address  = hit.address - rewardOffset,
				rewardId = rewardId,
			}
		end
	end

	Stack.Data.LeagueTasksDataLoaded = true
	Stack.Data.LeagueTasksData = out
	log.info("LeagueTasksData", string.format("hits=%d tasks=%d", ptrCount, #out))
	return out
end

return getOffsetLeagueTasksData
]]

