__vfs['modules/get/data/VehiclePaintsData.lua'] = [[if type(getOffsetVehicleSkinsOffset) ~= "function" then
	local ok, err = pcall(loadModule, "modules/get/offset/VehicleSkinsOffset.lua")
	if not ok then
		log.error("VehiclePaints: ", tostring(err))
		return function() return {} end
	end
end

if type(getDataVehiclesData) ~= "function" then
	local ok, err = pcall(loadModule, "modules/get/data/VehiclesData.lua")
	if not ok then
		log.error("VehiclePaints: ", tostring(err))
		return function() return {} end
	end
end

local _Customization = yj.runtime.requireClass("Customization") or {}
local _CarSprite     = yj.runtime.requireClass("CarSprite") or {}
local _CarSpriteType = loadModule("metadata/enums/CarSpriteType.lua") or {}

local ChassisValue = _CarSpriteType.byName and _CarSpriteType.byName.Chassis or 0

function getDataVehiclePaintsData(force)
	if type(Stack.Data.VehiclePaintsData) ~= "table" then
		Stack.Data.VehiclePaintsData = {}
	end
	if Stack.Data.VehiclePaintsDataLoaded and not force then
		return Stack.Data.VehiclePaintsData
	end
	if force then
		Stack.Data.VehiclePaintsData = {}
		Stack.Data.VehiclePaintsDataLoaded = false
	end

	local off = yj.offset.getOffsetfile(
		"VehicleSkinsOffset",
		"getOffsetVehicleSkinsOffset"
	)
	if not off then return {} end

	local vehicleIdOffset  = _Customization.vehicleId and _Customization.vehicleId.offset
	local idOffset         = _Customization.id and _Customization.id.offset
	local spriteTypeOffset = _CarSprite.spriteType and _CarSprite.spriteType.offset
	if not vehicleIdOffset or not idOffset or not spriteTypeOffset then
		return {}
	end

	local VehiclesData = getDataVehiclesData()
	if not VehiclesData or #VehiclesData < 1 then return {} end

	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	gg.searchNumber(Stack.libAddress + off, 32)
	local count = gg.getResultsCount()
	if not count or count < 1 then
		Stack.Data.VehiclePaintsData = {}
		Stack.Data.VehiclePaintsDataLoaded = true
		return Stack.Data.VehiclePaintsData
	end
	local hits = gg.getResults(count)
	gg.clearResults()

	local bases = {}
	local seen = {}
	for i = 1, #hits do
		local base = hits[i].address
		if not seen[base] then
			seen[base] = true
			bases[#bases + 1] = base
		end
	end

	local requests = {}
	for i = 1, #bases do
		requests[i] = { address = bases[i] + spriteTypeOffset, flags = 4 }
	end
	local spriteVals = gg.getValues(requests)

	local filtered = {}
	for i = 1, #spriteVals do
		local item = spriteVals[i]
		if item and item.value ~= nil
		   and item.value == ChassisValue then
			filtered[#filtered + 1] = item.address - spriteTypeOffset
		end
	end
	if #filtered == 0 then
		Stack.Data.VehiclePaintsData = {}
		Stack.Data.VehiclePaintsDataLoaded = true
		return Stack.Data.VehiclePaintsData
	end

	local addressTable = {}
	for i = 1, #filtered do
		local base = filtered[i]
		addressTable[i * 2 - 1] = base + idOffset
		addressTable[i * 2]     = base + vehicleIdOffset
	end
	local strResults = yj.mem.stdstring.readBulk(addressTable)
	local addrToStr = {}
	for _, item in ipairs(strResults) do
		if item and item.address then
			addrToStr[item.address] = item.str or ""
		end
	end

	local sprites = {}
	for i = 1, #filtered do
		local base = filtered[i]
		local idVal = addrToStr[base + idOffset]
		if idVal and idVal ~= "" then
			sprites[#sprites + 1] = {
				address   = base,
				id        = idVal,
				vehicleId = addrToStr[base + vehicleIdOffset],
			}
		end
	end

	local grouped = {}
	for i = 1, #sprites do
		local k = sprites[i]
		local vid = k.vehicleId
		if vid and vid ~= "" then
			grouped[vid] = grouped[vid] or {}
			grouped[vid][#grouped[vid] + 1] = k
		end
	end

	local result = {}
	for i = 1, #VehiclesData do
		local v = VehiclesData[i]
		result[i] = {
			address = v.address,
			id      = v.id,
			name    = v.name,
			Chassis = grouped[v.id] or {},
