local vtable_structure = {
    offset_to_top = -0x10,
    typeinfo      = -0x8,
    slot0         = 0x0,
    slot1         = 0x8,
    typeinfoT = {
        vtable      = 0x0,
        __type_name = 0x8,
    }
}

local function readStrings(ptrs, maxLen)
    maxLen = maxLen or 128
    local out = {}
    local total = #ptrs
    local BATCH = 2048

    for startIdx = 1, total, BATCH do
        local endIdx = math.min(startIdx + BATCH - 1, total)
        local count = endIdx - startIdx + 1
        local requests = {}

        for j = 1, count do
            local ptr = ptrs[startIdx + j - 1]
            for k = 0, maxLen - 1 do
                requests[(j - 1) * maxLen + k + 1] = {
                    address = ptr + k,
                    flags   = 1,
                }
            end
        end

        local values = gg.getValues(requests)

        for j = 1, count do
            local chars = {}
            for k = 0, maxLen - 1 do
                local v = values[(j - 1) * maxLen + k + 1]
                if not v or v.value == nil then break end
                local b = v.value
                if b < 0 then b = b + 256 end
                if b == 0 then break end
                chars[#chars + 1] = Stack.BYTE2CHAR.byId[b]
            end
            if #chars > 0 then
                out[#out + 1] = {
                    ptr  = ptrs[startIdx + j - 1],
                    name = table.concat(chars),
                }
            end
        end
    end

    return out
end

function getOffsetVtablesData()
    local definition = vtable_structure
    if not definition then return {} end

    local vtable_offsets  = getOffsetVtableOffset("GameStatus")
    local vtable_offsets2 = getOffsetVtableOffset("LootDefinition")
    if not vtable_offsets or #vtable_offsets < 1
        or not vtable_offsets2 or #vtable_offsets2 < 1 then
        log.warn("VtablesData: getOffsetVtableOffset ")
        return {}
    end

    local vtableAddr  = Stack.libAddress + vtable_offsets[1]
    local vtableAddr2 = Stack.libAddress + vtable_offsets2[1]

    local typeInfoAddr  = yj.mem.qword.get(vtableAddr  + definition.typeinfo)
    local typeInfoAddr2 = yj.mem.qword.get(vtableAddr2 + definition.typeinfo)
    if not typeInfoAddr or typeInfoAddr == 0
        or not typeInfoAddr2 or typeInfoAddr2 == 0 then
        log.warn("VtablesData: type_info ")
        return {}
    end

    local typeInfoVtableAddr  = yj.mem.qword.get(typeInfoAddr  + definition.typeinfoT.vtable)
    local typeInfoVtableAddr2 = yj.mem.qword.get(typeInfoAddr2 + definition.typeinfoT.vtable)
    if not typeInfoVtableAddr or typeInfoVtableAddr == 0
        or not typeInfoVtableAddr2 or typeInfoVtableAddr2 == 0 then
        log.warn("VtablesData: type_info vtable ")
        return {}
    end

    gg.clearResults()
    gg.setRanges(Info.game.libRegion)
    gg.searchNumber(typeInfoVtableAddr, 32)
    local count = gg.getResultsCount()
    if not count or count < 1 then
        log.warn("VtablesData:  type_info ")
        return {}
    end
    local hits = gg.getResults(count)
    gg.clearResults()

    gg.setRanges(Info.game.libRegion)
    gg.searchNumber(typeInfoVtableAddr2, 32)
    local count2 = gg.getResultsCount()
    if not count2 or count2 < 1 then
        log.warn("VtablesData:  type_info ")
        return {}
    end
    local hits2 = gg.getResults(count2)
    gg.clearResults()

    local hits_end = #hits
    for i = 1, #hits2 do
        hits[hits_end + i] = hits2[i]
    end

    local requests = {}
    for i = 1, #hits do
        requests[i] = {
            address = hits[i].address + definition.typeinfoT.__type_name,
            flags   = 32,
        }
    end
    local spriteVals = gg.getValues(requests)

    local filtered = {}
    for i = 1, #spriteVals do
        local item = spriteVals[i]
        if item and item.value ~= nil and item.value ~= 0 then
            filtered[#filtered + 1] = {
                typeInfoAddr = hits[i].address,
                namePtr      = item.value,
            }
        end
    end

    if #filtered < 1 then
        log.warn("VtablesData:  __type_name ")
        return {}
    end

    local namePtrs = {}
    for i = 1, #filtered do
        namePtrs[i] = filtered[i].namePtr
    end
    local all = readStrings(namePtrs, 128)

    local loadList = {}
    for i = 1, #filtered do
        loadList[i] = { address = filtered[i].typeInfoAddr, flags = 4 }
    end
    gg.loadResults(loadList)
    gg.searchPointer(0x0)
    local vpCount = gg.getResultsCount()

    local typeInfoToVtables = {}
    for i = 1, #filtered do
        typeInfoToVtables[filtered[i].typeInfoAddr] = {}
    end

    if vpCount and vpCount > 0 then
        local vpHits = gg.getResults(vpCount)
        gg.clearResults()
        for _, vh in ipairs(vpHits) do
            if vh.value and vh.value ~= 0 then
                local key = vh.value
                typeInfoToVtables[key] = typeInfoToVtables[key] or {}
                local vt = vh.address - definition.typeinfo
                typeInfoToVtables[key][#typeInfoToVtables[key] + 1] = vt
            end
        end
    end
    gg.clearResults()

    local names = {}
    for i = 1, #all do
        local s = all[i].name
        if s and s:match("^%d") then
            local plainName = s:gsub("^%d+", "")
            local vtList = typeInfoToVtables[filtered[i].typeInfoAddr]
            if vtList and #vtList > 0 then
                local offsets = {}
                local seen = {}
                for _, vt in ipairs(vtList) do
                    local off = vt - Stack.libAddress
                    if not seen[off] then
                        seen[off] = true
                        offsets[#offsets + 1] = off
                    end
                end
                if #offsets > 0 then
                    names[#names + 1] = {
                        name    = plainName,
                        vtables = offsets,
                    }
                end
            end
        end
    end

