__vfs['modules/get/offset/VtableOffset.lua'] = [[local vtable_structure = {
    offset_to_top = -0x10,   -- vptr[-2]
    typeinfo      = -0x8,    -- vptr[-1] type_info 
    slot0         = 0x0,     -- 
    slot1         = 0x8,     -- 
    typeinfoT = {
        vtable      = 0x0,   -- type_info  vptr
        __type_name = 0x8,   -- const char* mangled 
    }
}

function getOffsetVtableOffset(typeName)
    local definition = vtable_structure
    if not definition or type(typeName) ~= "string" then return nil end

    local len = #typeName
    local str = table.concat({tostring(len), typeName})
    local aob = yj.str.stringToAob(str)
    local hex = table.concat({aob, "00"}, " ")

    -- 1)  type_info  mangled name 
    gg.clearResults()
    gg.setRanges(Info.game.libRegion)
    gg.searchNumber(hex, 1)
    gg.setRanges(Info.game.libRegion)
    gg.searchPointer(0x0)
    local count = gg.getResultsCount()
    if not count or count < 1 then return nil end
    local hits = gg.getResults(count)
    gg.clearResults()

    -- 2)  - __type_name  = type_info 
    local typeInfoAddrs = {}
    for i, hit in ipairs(hits) do
        typeInfoAddrs[i] = hit.address - definition.typeinfoT.__type_name
    end

    -- 3)  type_infovtable  vptr[-1]
    local typeInfoResults = {}
    for i, addr in ipairs(typeInfoAddrs) do
        typeInfoResults[i] = { address = addr, flags = 4 }
    end
    gg.loadResults(typeInfoResults)
    gg.searchPointer(0x0)
    local ptrCount = gg.getResultsCount()
    if not ptrCount or ptrCount < 1 then
        log.warn("VtableOffset: ")
        return nil
    end
    local ptrHits = gg.getResults(ptrCount)
    gg.clearResults()

    -- 4)  - typeinfo  = vtable vptr
    local vptrAddrs = {}
    for i, hit in ipairs(ptrHits) do
        vptrAddrs[i] = hit.address - definition.typeinfo
    end

    local vptrVals = yj.mem.qword.getBulk(vptrAddrs)
    if not vptrVals or #vptrVals < 1 then return nil end

    --  value ~= 0
    local structs = {}
    for i = 1, #vptrVals do
        local item = vptrVals[i]
        if item and item.value and item.value ~= 0 then
            structs[#structs + 1] = item
        end
    end
    if #structs == 0 then return nil end

    -- 5)  slot0 / slot1 / offset_to_top
    local checkAddrs = {}
    for i, hit in ipairs(structs) do
        local vptr = hit.address
        checkAddrs[#checkAddrs + 1] = vptr + definition.slot0
        checkAddrs[#checkAddrs + 1] = vptr + definition.slot1
        checkAddrs[#checkAddrs + 1] = vptr + definition.offset_to_top
    end

    local checkVals = yj.mem.qword.getBulk(checkAddrs)
    local addrToVal = {}
    for _, v in ipairs(checkVals) do
        addrToVal[v.address] = v.value
    end

    -- 6) slot0 ≠ 0  slot1 ≠ 0  offset_to_top == 0
    local filtered = {}
    for i, hit in ipairs(structs) do
        local vptr = hit.address
        local slot0 = addrToVal[vptr + definition.slot0]
        local slot1 = addrToVal[vptr + definition.slot1]
        local ott   = addrToVal[vptr + definition.offset_to_top]

        if slot0 and slot0 ~= 0
            and slot1 and slot1 ~= 0
            and ott == 0 then
            filtered[#filtered + 1] = hit.address - Stack.libAddress
        end
    end

    if #filtered == 0 then return nil end
    return filtered
end

return getOffsetVtableOffset]]

