__vfs['modules/ops/CustomUnlock_.lua'] = [[if type(LootDefinitionMenu) ~= "function" then
	loadModule("modules/ops/CustomUnlock_/LootDefinition.lua")
end

if type(getDataWorldsData) ~= "function" then
	loadModule("modules/get/data/WorldsData.lua")
end

local _WorldDefinition = yj.runtime.requireClass("WorldDefinition") or {}
local _LootDefinition  = yj.runtime.requireClass("LootDefinition") or {}

function CustomUnlock_()
	local worldsData = getDataWorldsData()
	if not worldsData or #worldsData < 1 then
		log.error("CustomUnlock_: Không tải được WorldsData")
		yj.runtime.executeFunction("Main")
		return
	end

	local unlockRewardOffset = _WorldDefinition.unlockReward and _WorldDefinition.unlockReward.offset
	local size = _LootDefinition.__Size
	if not unlockRewardOffset or not size or size == 0 then
		log.error("CustomUnlock_: Metadata không đầy đủ")
		yj.runtime.executeFunction("Main")
		return
	end

	local templateLootAddr = nil
	for i = 1, #worldsData do
		local ptr = yj.mem.qword.get(worldsData[i].address + unlockRewardOffset)
		if ptr and ptr ~= 0 then
			templateLootAddr = ptr
			break
		end
	end
	if not templateLootAddr then
		gg.alert(L("Không tìm thấy mẫu LootDefinition"))
		yj.runtime.executeFunction("Main")
		return
	end

	local allocAddr = yj.mem.allocZeroPage(size)
	if not allocAddr or allocAddr == 0 then
		gg.alert(L("Không thể cấp phát bộ nhớ"))
		yj.runtime.executeFunction("Main")
		return
	end

	local reads = {}
	for offset = 0, size - 4, 4 do
		reads[#reads + 1] = { address = templateLootAddr + offset, flags = 4 }
	end
	local srcData = gg.getValues(reads)

	local copyMods = {}
	for i = 1, #srcData do
		copyMods[i] = {
			address = allocAddr + (i - 1) * 4,
			flags   = 4,
			value   = srcData[i].value,
		}
	end
	if #copyMods > 0 then gg.setValues(copyMods) end

	local clearMods = {}
	for key, f in pairs(_LootDefinition) do
		if type(f) == "table" and f.offset and key ~= "__Size" then
			local t = f.type
			local addr = allocAddr + f.offset
			if t == "int" or t == "int32" then
				clearMods[#clearMods + 1] = { address = addr, flags = 4, value = 0 }
			elseif t == "float" then
				clearMods[#clearMods + 1] = { address = addr, flags = 16, value = 0 }
			elseif t == "bool" then
				clearMods[#clearMods + 1] = { address = addr, flags = 1, value = 0 }
			elseif t == "string" or (type(t) == "string" and t:match("^string")) then
				clearMods[#clearMods + 1] = { address = addr,      flags = 32, value = 0 }
				clearMods[#clearMods + 1] = { address = addr + 8,  flags = 32, value = 0 }
				clearMods[#clearMods + 1] = { address = addr + 16, flags = 32, value = 0 }
			elseif type(t) == "string" and t:match("^vector") then
				clearMods[#clearMods + 1] = { address = addr,      flags = 32, value = 0 }
				clearMods[#clearMods + 1] = { address = addr + 8,  flags = 32, value = 0 }
				clearMods[#clearMods + 1] = { address = addr + 16, flags = 32, value = 0 }
			end
		end
	end
	if #clearMods > 0 then gg.setValues(clearMods) end

	gg.setValues({{
		address = worldsData[1].address + unlockRewardOffset,
		flags = 32,
		value = allocAddr,
	}})
	log.info("CustomUnlock_:  LootDefinition", string.format("0x%X", allocAddr),
		"", string.format("0x%X", templateLootAddr),
		"world[1]", string.format("0x%X", worldsData[1].address))

	return LootDefinitionMenu({ allocAddr }, "Main", {})
end
]]

