end

function GameStatusvipstatus_UnlockVIPWithOneClick_Detail(baseAddress, field, name, Return, returnArgs)
	local targetPtr = yj.mem.qword.get(baseAddress + field.offset)
	if not targetPtr or targetPtr == 0 then
		gg.alert(L("Không rõ") .. name)
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	local _VipStatus = yj.runtime.requireClass("VipStatus") or {}
	if yj.table.isEmpty(_VipStatus) then
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	local _SubscriptionTier = yj.runtime.requireClass("SubscriptionTier") or {}
	if yj.table.isEmpty(_SubscriptionTier) then
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if type(getDataSubscriptionsData) ~= "function" then
		if not loadModule("modules/get/data/SubscriptionsData.lua") then
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end

	local function off(key)
		local f = _VipStatus[key]
		return f and f.offset or nil
	end
	local hasBitsOffset      = off("_has_bits_")
	local expOffset          = off("vipexpirationtimestamp_")
	local skipCupsOffset     = off("vipskipcupsremaining_")
	local nextSkipOffset     = off("nextvipskiptimestamp_")
	local nextFreeUpOffset   = off("nextfreevipupgradetimestamp_")
	local nextFreeTuneOffset = off("nextfreeviptuningpartupgradetimestamp_")
	local isVipOffset        = off("isvip_")
	local vipTierOffset      = off("viptier_")
	if not hasBitsOffset or not expOffset or not vipTierOffset then
		gg.alert(L("VipStatus metadata "))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	Stack.Data.SubscriptionsData = getDataSubscriptionsData()
	if not Stack.Data.SubscriptionsData or #Stack.Data.SubscriptionsData < 1 then
		gg.alert(L(""))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = {name = L("Quay lại"), func = "GameStatusC", module = "modules/ops/CommonFunctionArea_/GameStatusC.lua"}
	for i = 1, #Stack.Data.SubscriptionsData do
		local k = Stack.Data.SubscriptionsData[i]
		MENU_CONFIG[#MENU_CONFIG + 1] = {
			name    = k.id or L("Không rõ"),
			address = k.address,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Quay lại"), func = "GameStatusC", module = "modules/ops/CommonFunctionArea_/GameStatusC.lua"}

	local menu = yj.menu.showMenu(
		"GameStatusvipstatus_UnlockVIPWithOneClick_Detail",
		MENU_CONFIG,
		name .. "\n" .. L(" VIP"),
		{baseAddress, field, name, Return, returnArgs}
	)
	if not menu then return end

	local option = MENU_CONFIG[menu]
	if not option then return end

	if option.func then
		option.params = option.params or returnArgs
		yj.menu.dispatchMenuItem(option)
		return
	end
	if not option.address then return end

	local viptierPtr = option.address
	local lengthMenu = gg.prompt(
		{L("vip 30 ")},
		{"30"},
		{"number"}
	)
	if not lengthMenu then
		return
	end

	local days = tonumber(lengthMenu[1])
	if not days or days <= 0 then
		gg.alert(L(""))
		return GameStatusvipstatus_UnlockVIPWithOneClick_Detail(baseAddress, field, name, Return, returnArgs)
	end
	local length = math.floor(86400 * days)

	local currentTimeStamp = os.time()
	local edits = {}

	edits[#edits + 1] = {
		address = targetPtr + hasBitsOffset,
		flags = 4,
		value = 0xFFFFFFFF,
	}
	edits[#edits + 1] = {
		address = targetPtr + expOffset,
		flags = 4,
		value = currentTimeStamp + length,
	}
	if skipCupsOffset then
		edits[#edits + 1] = {
			address = targetPtr + skipCupsOffset,
			flags = 4,
			value = 6,
		}
	end
	local optionalOffsets = { nextSkipOffset, nextFreeUpOffset, nextFreeTuneOffset }
	for _, o in ipairs(optionalOffsets) do
		if o then
			edits[#edits + 1] = {
				address = targetPtr + o,
				flags = 4,
				value = currentTimeStamp,
			}
		end
	end
	if isVipOffset then
		edits[#edits + 1] = {
			address = targetPtr + isVipOffset,
			flags = 1,
			value = 1,
		}
	end
	edits[#edits + 1] = {
		address = targetPtr + vipTierOffset,
		flags = 32,
		value = viptierPtr,
	}

	gg.setValues(edits)
	gg.toast(string.format(L("VIP %s"), days))
	return yj.runtime.executeFunction(Return, returnArgs)
end

function GameStatusactiveleaguetasks_ActivateAllLeagueTasks(baseAddress, field, name, Return, returnArgs)
	gg.clearList()
	gg.clearResults()
	local _LeagueTask = yj.runtime.requireClass("LeagueTask") or {}
	local target_Offset          = _LeagueTask.target_          and _LeagueTask.target_.offset
	local progress_Offset        = _LeagueTask.progress_        and _LeagueTask.progress_.offset
	local claimed_Offset         = _LeagueTask.claimed_         and _LeagueTask.claimed_.offset
	local createtimestamp_Offset = _LeagueTask.createtimestamp_ and _LeagueTask.createtimestamp_.offset
	if not target_Offset or not progress_Offset or not claimed_Offset or not createtimestamp_Offset then
		log.warn("ActivateAllLeagueTasks: metadata ")
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local leagueTaskPtrs = yj.mem.rpf.readElements(baseAddress + field.offset)
	if not leagueTaskPtrs or #leagueTaskPtrs < 1 then
		gg.alert(L(""))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local task1Addr = leagueTaskPtrs[1]
	local vtablePtr = yj.mem.qword.get(task1Addr)
	if not vtablePtr or vtablePtr == 0 then
		gg.alert(L(" vtable"))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	gg.searchNumber(vtablePtr, 32)
	local count = gg.getResultsCount()
	if not count or count < 1 then
		gg.clearResults()
		gg.alert(L(" LeagueTask "))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end
	local hits = gg.getResults(count)
	gg.clearResults()

	local tsAddrs = {}
	for i, result in ipairs(hits) do
		tsAddrs[i] = result.address + createtimestamp_Offset
	end
	local tsVals = yj.mem.dword.getBulk(tsAddrs)
	local tsMap = {}
	for _, v in ipairs(tsVals) do
		tsMap[v.address] = v.value
	end

	local validHits = {}
	for i, result in ipairs(hits) do
		local ts = tsMap[result.address + createtimestamp_Offset]
		if ts and ts ~= 0 then
			validHits[#validHits + 1] = result
		end
	end

	if #validHits < 1 then
		gg.alert(L("createtimestamp_ = 0"))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local allMods = {}
	local freezeItems = {}
	for i, result in ipairs(validHits) do
		allMods[#allMods + 1] = {
			address = result.address + target_Offset,
			flags   = 4,
			value   = 50,
		}
		allMods[#allMods + 1] = {
			address = result.address + progress_Offset,
			flags   = 4,
			value   = 50,
		}
		freezeItems[#freezeItems + 1] = {
			address = result.address + claimed_Offset,
			flags   = 1,
			value   = 0,
			freeze  = true,
		}
	end

	if #allMods > 0 then gg.setValues(allMods) end

	if #freezeItems > 0 then
		local ok, err = pcall(gg.addListItems, freezeItems)
		if not ok then
			log.warn("addListItems  freeze setValues:", tostring(err))
			local noFreeze = {}
			for i, item in ipairs(freezeItems) do
				noFreeze[i] = { address = item.address, flags = item.flags, value = item.value }
			end
			pcall(gg.addListItems, noFreeze)
			pcall(gg.setValues, freezeItems)
		end
	end

	gg.toast(string.format(L(" %d  %d "), #validHits, #hits))
	return yj.runtime.executeFunction(Return, returnArgs)
end

