function GameStatusvehiclestatus_VehicleTuningPartsMaxLevel(baseAddress, field, name, Return, returnArgs)
	local _VehicleStatus     = yj.runtime.requireClass("VehicleStatus") or {}
	local _TuningPartStatus  = yj.runtime.requireClass("TuningPartStatus") or {}
	local tuningparts_Offset     = _VehicleStatus.tuningparts_       and _VehicleStatus.tuningparts_.offset
	local _cached_size_Offset    = _TuningPartStatus._cached_size_   and _TuningPartStatus._cached_size_.offset
	local id_Offset              = _TuningPartStatus.id_             and _TuningPartStatus.id_.offset
	local level_Offset           = _TuningPartStatus.level_          and _TuningPartStatus.level_.offset
	local maxlevel_Offset        = _TuningPartStatus.maxlevel_       and _TuningPartStatus.maxlevel_.offset
	if not tuningparts_Offset or not _cached_size_Offset or not id_Offset
		or not level_Offset or not maxlevel_Offset then
		log.warn("VehicleTuningPartsMaxLevel: metadata ")
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local vehicleStautsPtrs = yj.mem.rpf.readElements(baseAddress + field.offset)
	if not vehicleStautsPtrs or #vehicleStautsPtrs < 1 then
		gg.alert(L(""))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local vehicle1Addr = vehicleStautsPtrs[1]
	local tuningpartsPtrs = yj.mem.rpf.readElements(vehicle1Addr + tuningparts_Offset)
	if not tuningpartsPtrs or #tuningpartsPtrs < 1 then
		gg.alert(L(" tuningpartsPtrs"))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local tuningparts1Addr = tuningpartsPtrs[1]
	local vtablePtr = yj.mem.qword.get(tuningparts1Addr)
	if not vtablePtr or vtablePtr == 0 then
		gg.alert(L(" vtable"))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	gg.searchNumber(vtablePtr, 32)
	local count = gg.getResultsCount()
	if not count or count < 1 then
		gg.clearResults()
		gg.alert(L(" TuningPartStatus "))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end
	local hits = gg.getResults(count)
	gg.clearResults()

	local tsAddrs = {}
	for i, result in ipairs(hits) do
		tsAddrs[i] = result.address + _cached_size_Offset
	end
	local tsVals = yj.mem.dword.getBulk(tsAddrs)
	local tsMap = {}
	for _, v in ipairs(tsVals) do
		tsMap[v.address] = v.value
	end

	local validHits = {}
	for i, result in ipairs(hits) do
		local ts = tsMap[result.address + _cached_size_Offset]
		if ts and ts ~= 0 then
			validHits[#validHits + 1] = result
		end
	end

	if #validHits < 1 then
		gg.alert(L("_cached_size_ = 0"))
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	if type(getDataVehicleTuningPartsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/VehicleTuningPartsData.lua")
		if not ok then
			log.error("VehicleTuningPartsMaxLevel: ", tostring(err))
			yj.runtime.executeFunction(Return, returnArgs)
			return
		end
	end
	local vehicles = getDataVehicleTuningPartsData()
	if not vehicles or #vehicles < 1 then
		log.error("VehicleTuningPartsMaxLevel: VehicleTuningPartsData ")
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local partLevels = {
		[1] = 15,
		[2] = 10,
		[3] = 7,
		[4] = 4,
		[6] = 3,
	}
	local Parts = {}
	for i = 1, #vehicles do
		local parts = vehicles[i].TuningParts or {}
		for j = 1, #parts do
			local p = parts[j]
			if p.id and p.id ~= "" and partLevels[p.rarity] then
				Parts[p.id] = partLevels[p.rarity]
			end
		end
	end

	local idPtrAddrs = {}
	for i, hit in ipairs(validHits) do
		idPtrAddrs[i] = hit.address + id_Offset
	end
	local idPtrVals = yj.mem.qword.getBulk(idPtrAddrs)

	local addrToStrObj = {}
	local strObjAddrs = {}
	for i, v in ipairs(idPtrVals) do
		local fieldAddr = idPtrAddrs[i]
		local strAddr = v and v.value
		if yj.mem.isValidPtr(strAddr) then
			addrToStrObj[fieldAddr] = strAddr
			strObjAddrs[#strObjAddrs + 1] = strAddr
		end
	end

	local strResults = yj.mem.stdstring.readBulk(strObjAddrs)
	local strAddrToId = {}
	for _, r in ipairs(strResults) do
		if r and r.address then
			strAddrToId[r.address] = r.str or ""
		end
	end

	local idToStatusAddr = {}
	for i, hit in ipairs(validHits) do
		local fieldAddr = hit.address + id_Offset
		local strAddr = addrToStrObj[fieldAddr]
		local idStr = strAddr and strAddrToId[strAddr]
		if idStr and idStr ~= "" then
			idToStatusAddr[idStr] = hit.address
		end
	end

	local allMods = {}
	local changed = 0
	for id, addr in pairs(idToStatusAddr) do
		local maxLv = Parts[id]
		if maxLv then
			allMods[#allMods + 1] = {
				address = addr + level_Offset,
				flags   = 4,
				value   = maxLv,
			}
			allMods[#allMods + 1] = {
				address = addr + maxlevel_Offset,
				flags   = 4,
				value   = maxLv,
			}
			changed = changed + 1
		end
	end

	if #allMods > 0 then
		gg.setValues(allMods)
	end

	gg.toast(string.format(L(" %d "), changed))
	return yj.runtime.executeFunction(Return, returnArgs)
end
