	)
	if not off then return nil end
	return Stack.libAddress + off
end

function GlobalVision()
	yj.menu.registerMenuItem('GlobalVision')

	local baseAddr = getBaseAddr()
	if not baseAddr then
		local act = gg.alert(
			L(""),
			L(""), L("Quay lại")
		)
		if act == 1 then return GlobalVisionLoadOffset() end
		return
	end

	local cur = 0
	local v = gg.getValues({{ address = baseAddr, flags = 16 }})
	if v and v[1] and v[1].value then cur = v[1].value end

	local MENU_CONFIG = {
		{name = L(""), func = "CustomizeGlobalVision"},
		{name = L("20"),  value = 20,  _kind = "preset"},
		{name = L("40"),  value = 40,  _kind = "preset"},
		{name = L("60"),  value = 60,  _kind = "preset"},
		{name = L("80"),  value = 80,  _kind = "preset"},
		{name = L("100"), value = 100, _kind = "preset"},
		{name = L("120"), value = 120, _kind = "preset"},
		{name = L("140"), value = 140, _kind = "preset"},
		{name = L("160"), value = 160, _kind = "preset"},
		{name = L("180"), value = 180, _kind = "preset"},
