local CLOSE_MAGIC = -1081011951

local function getAddr(force)
	local off = yj.offset.getOffsetfile(
		"VehicleGearShifting",
		"getOffsetVehicleGearShifting",
		force
	)
	if not off then return nil end
	return Stack.libAddress + off
end

local function writeValue(addr, flags, value)
	local ok, err = pcall(gg.setValues, {{
		address = addr, flags = flags, value = value
	}})
	if not ok then
		log.error("VehicleGearShifting: ", tostring(err))
		return false
	end
	return true
end

local function readCurrent(addr)
	local v = gg.getValues({{ address = addr, flags = 16 }})
	if v and v[1] and v[1].value then return v[1].value end
	return 0
end

function VehicleGearShifting()
	yj.menu.registerMenuItem("VehicleGearShifting")

	local addr = getAddr()
	if not addr then
		local act = gg.alert(
			L(""),
			L(""), L("Quay lại")
		)
		if act == 1 then return VehicleGearShiftingLoadingOffset() end
		return
	end

	local cur = readCurrent(addr)

	local MENU_CONFIG = {
		{name = L(""), func = "CustomizeCarSpeedCustom"},
		{name = L(": -1.05"), value = -1.05, _kind = "preset"},
		{name = L(": -1.00"), value = -1.00, _kind = "preset"},
		{name = L(": -0.95"), value = -0.95, _kind = "preset"},
		{name = L(": -0.90"), value = -0.90, _kind = "preset"},
		{name = L(": -0.85"), value = -0.85, _kind = "preset"},
		{name = L(": -0.80"), value = -0.80, _kind = "preset"},
		{name = L(""), _kind = "close"},
		{name = L(""), func = "VehicleGearShiftingLoadingOffset"},
		{name = L("Quay lại"), func = "CommonFunctionArea_",
		 module = "modules/ops/CommonFunctionArea_.lua"},
	}

	local menu = yj.menu.showMenu(
		'VehicleGearShifting',
		MENU_CONFIG,
		string.format(L("  %s"), cur)
	)
	if not menu then return end

	local item = MENU_CONFIG[menu]
	if not item then return end

	if item.func ~= "CommonFunctionArea_" then
		Stack.MenuIndex.VehicleGearShifting = menu
	end

	if item._kind == "preset" then
		if writeValue(addr, 16, item.value) then
			gg.toast(string.format(L(" %s"), item.value))
		else
			gg.alert(L(""))
		end
		return
	end

	if item._kind == "close" then

		if writeValue(addr, 4, CLOSE_MAGIC) then
			gg.toast(L(""))
		else
			gg.alert(L(""))
		end
		return
	end

	yj.menu.dispatchMenuItem(item)
end

function CustomizeCarSpeedCustom()
	yj.menu.registerMenuItem("CustomizeCarSpeedCustom")

	local addr = getAddr()
	if not addr then
		gg.alert(L(""))
		return VehicleGearShifting()
	end

	local MIN, MAX = -1.3, -0.6
	local cur = readCurrent(addr)

	local def = tostring(cur)
	if cur < MIN or cur > MAX then def = "-1.0" end

	local input = gg.prompt(
		{ L("  -1.3  -0.6 (-1.3, -0.6)") },
		{ def },
		{ "number" }
	)
	if not input or not input[1] then
		return VehicleGearShifting()
	end

	local num = tonumber(input[1])
	if not num then
		gg.alert(L("Dữ liệu nhập không hợp lệ"))
		return VehicleGearShifting()
	end
	if num < MIN or num > MAX then
		gg.alert(string.format(L(" %s ~ %s "), MIN, MAX))
		return VehicleGearShifting()
	end

	if writeValue(addr, 16, num) then
		gg.toast(string.format(L(" %s"), num))
	else
		gg.alert(L(""))
	end
	return VehicleGearShifting()
end

function VehicleGearShiftingLoadingOffset()
