		loadModule("modules/ops/CustomUnlock_/LootDefinition.lua")
	end

	local rewardOffset = _LeagueTaskDefinition.reward and _LeagueTaskDefinition.reward.offset
	if not rewardOffset then
		log.warn("LeagueTasks_ModifyAllRewards: metadata  reward")
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	local slotAddrs = {}
	for i = 1, #leagueTasksData do
		slotAddrs[i] = leagueTasksData[i].address + rewardOffset
	end

	local ptrVals = yj.mem.qword.getBulk(slotAddrs)
	local addressTable = {}
	for i = 1, #ptrVals do
