	local cur = 0
	local v = gg.getValues({{ address = baseAddress + field.offset, flags = 4 }})
	if v and v[1] and v[1].value then cur = v[1].value end
	local atPresent = _LeagueTaskType.byId and _LeagueTaskType.byId[cur]

	local ids = {}
	for id in pairs(_LeagueTaskType.byId or {}) do
		ids[#ids + 1] = id
	end
	table.sort(ids)

	local MENU_CONFIG = {}
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), func = Return, params = returnArgs }
	for _, id in ipairs(ids) do
		local displayName = _LeagueTaskType.byId[id]
