	if type(LootDefinitionMenu) ~= "function" then
		loadModule("modules/ops/CustomUnlock_/LootDefinition.lua")
	end

	local targetPtr = yj.mem.qword.get(baseAddress + field.offset)
	if not targetPtr or targetPtr == 0 then
		gg.alert(L("Không rõ") .. name)
		yj.runtime.executeFunction(Return, returnArgs)
		return
	end

	return LootDefinitionMenu({ targetPtr }, Return, returnArgs)
end
