function LootDefinition_unlockVectorString_EXECUTE(addressTable, selectedList, idOffset, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVectorString_EXECUTE',
		{addressTable, selectedList, idOffset, field, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn mục nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not idOffset then
		gg.toast(L("idOffset không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local fieldOffset = field.offset
	local count       = #selectedList
	local STR_SIZE    = 0x18

	local elemsAddr = yj.mem.allocZeroPage(count * STR_SIZE)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	for i = 1, count do
		local strAddr = selectedList[i].address + idOffset
		for k = 0, 5 do
			reads[(i - 1) * 6 + k + 1] = { address = strAddr + k * 4, flags = 4 }
		end
	end
	local values = gg.getValues(reads)

	local copyMods = {}
	for i = 1, #values do
		copyMods[i] = {
			address = elemsAddr + (i - 1) * 4,
			flags   = 4,
			value   = values[i].value,
		}
	end
	if #copyMods > 0 then gg.setValues(copyMods) end

	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + fieldOffset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + count * STR_SIZE }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + count * STR_SIZE }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_unlockVectorString_EXECUTE",
		string.format("elems=0x%X count=%d", elemsAddr, count))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), count))

	return yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_resetData(addressTable, Return, returnArgs)
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local rankAmountOffset = _LootDefinition.rankAmount and _LootDefinition.rankAmount.offset
	local useClientOffset  = _LootDefinition.useClientDecidedVehicleId and _LootDefinition.useClientDecidedVehicleId.offset
	if not rankAmountOffset or not useClientOffset then
		gg.toast(L("Metadata không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local allMods = {}
	for i = 1, #addressTable do
		local base = addressTable[i]
		for offset = rankAmountOffset, useClientOffset - 4, 4 do
			allMods[#allMods + 1] = {
				address = base + offset,
				flags   = 4,
				value   = 0,
			}
		end
	end

	if #allMods > 0 then
		gg.setValues(allMods)
		gg.toast(string.format(L("✓ Đã xóa %d trường"), #allMods))
	else
		gg.toast(L("⚠ Không có dữ liệu nào được thay đổi"))
	end

	yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_rankAmount(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_rankAmount', {addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local fieldOffset = field.offset
	local cur = 0
	local v = gg.getValues({{ address = addressTable[1] + fieldOffset, flags = 16 }})
	if v and v[1] and v[1].value then cur = v[1].value * 1000 end

	local input = gg.prompt(
		{ name },
		{ tostring(cur) },
		{ "number" }
	)
	if not input or not input[1] then
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local value = tonumber(input[1]) * 0.001
	if not value then
		gg.alert(L("Dữ liệu nhập không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local modifys = {}
	for i = 1, #addressTable do
		local base = addressTable[i]
		modifys[i] = {
			address = base + fieldOffset,
			flags   = 16,
			value   = value,
		}
	end
	gg.setValues(modifys)
	gg.toast(L("Thiết lập thành công") .. value)

	return
end

