function LootDefinition_unlockVehicles(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVehicles', {addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataVehiclesData) ~= "function" then
		loadModule("modules/get/data/VehiclesData.lua")
	end
	local vehiclesData = getDataVehiclesData()
	if not vehiclesData or #vehiclesData < 1 then
		log.error("LootDefinition_unlockVehicles: VehiclesData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = {name = L("Quay lại"), key = "return"}
	MENU_CONFIG[2] = {name = L("Chọn tất cả xe"), key = "all"}
	for i, k in ipairs(vehiclesData) do
		MENU_CONFIG[i + 2] = {name = k.name .. "\t\t~\t\t" .. k.id, key = "single", data = k}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Chọn xe ẩn"), key = "hiddenVehicle"}
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Quay lại"), key = "return"}

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end
	local choices = gg.multiChoice(SHOW_MENU, nil, name)
	if not choices then return end
	local selectedList = {}
	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "hiddenVehicle" then
				return yj.runtime.executeFunction("LootDefinition_unlockVehiclesHidden",
					{addressTable, field, name, "LootDefinition_unlockVehicles", {addressTable, field, name, Return, returnArgs}})
			elseif a.key == "all" then
				for j = 1, #vehiclesData do
					selectedList[#selectedList + 1] = vehiclesData[j]
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
			end
		end
	end
	if #selectedList > 0 then
		local _VehicleDefinition = yj.runtime.requireClass("VehicleDefinition") or {}
		local idOffset = _VehicleDefinition.id and _VehicleDefinition.id.offset
		if not idOffset then
			gg.toast(L("Thiếu VehicleDefinition.id trong metadata"))
			return yj.runtime.executeFunction(Return, returnArgs)
		end

		return yj.runtime.executeFunction("LootDefinition_unlockVectorString_EXECUTE",
			{addressTable, selectedList, idOffset, field, name, "LootDefinition_unlockVehicles",
			 {addressTable, field, name, Return, returnArgs}})
	end
	return
end

