function LootDefinition_unlockDriverAssets(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockDriverAssets', {addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataDriverAssetsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/DriverAssetsData.lua")
		if not ok then
			log.error("LootDefinition_unlockDriverAssets: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local driverAssetsData = getDataDriverAssetsData()
	if not driverAssetsData or next(driverAssetsData) == nil then
		log.error("LootDefinition_unlockDriverAssets: DriverAssetsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local seen = {}
	local allDriverAssetsData = {}
	for _, partList in pairs(driverAssetsData) do
		for i = 1, #partList do
			local item = partList[i]
			if type(item) == "table"
				and item.address
				and type(item.id) == "string" and item.id ~= ""
				and not seen[item.id] then
				seen[item.id] = true
				allDriverAssetsData[#allDriverAssetsData + 1] = item
			end
		end
	end
	if #allDriverAssetsData == 0 then
		log.error("LootDefinition_unlockDriverAssets: ")
		gg.toast(L("Không tìm thấy dữ liệu skin tài xế khả dụng"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	table.sort(allDriverAssetsData, function(a, b)
		return tostring(a.name) < tostring(b.name)
	end)

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = {name = L("Quay lại"), key = "return"}
	MENU_CONFIG[2] = {name = L("Chọn tất cả skin"), key = "all"}
	for i, k in ipairs(allDriverAssetsData) do
		MENU_CONFIG[i + 2] = {
			name = tostring(k.name) .. "\t\t~\t\t" .. tostring(k.id),
			key = "single",
			data = k,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Quay lại"), key = "return"}

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end
	local choices = gg.multiChoice(SHOW_MENU, nil, name)
	if not choices then return end

	local selectedList = {}
	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "all" then
				for j = 1, #allDriverAssetsData do
					selectedList[#selectedList + 1] = allDriverAssetsData[j]
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
			end
		end
	end

	if #selectedList > 0 then
		local _Customization = yj.runtime.requireClass("Customization") or {}
		local idOffset = _Customization.id and _Customization.id.offset
		if not idOffset then
			gg.toast(L("Thiếu Customization.id trong metadata"))
			return yj.runtime.executeFunction(Return, returnArgs)
		end

		return yj.runtime.executeFunction("LootDefinition_unlockVectorString_EXECUTE",
			{addressTable, selectedList, idOffset, field, name, "LootDefinition_unlockDriverAssets",
			 {addressTable, field, name, Return, returnArgs}})
	end
	return
end

