function LootDefinition_unlockVehiclePaints(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVehiclePaints',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataVehiclePaintsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/VehiclePaintsData.lua")
		if not ok then
			log.error("LootDefinition_unlockVehiclePaints: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local vehiclePaintsData = getDataVehiclePaintsData()
	if not vehiclePaintsData or #vehiclePaintsData < 1 then
		log.error("LootDefinition_unlockVehiclePaints: VehiclePaintsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local totalPaints = 0
	for i = 1, #vehiclePaintsData do
		totalPaints = totalPaints + ((vehiclePaintsData[i].Chassis and #vehiclePaintsData[i].Chassis) or 0)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn skin của tất cả xe"), totalPaints),
		key  = "all",
	}
	for i, v in ipairs(vehiclePaintsData) do
		local paintCount = (v.Chassis and #v.Chassis) or 0
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\t%s (%d)",
				tostring(v.name), tostring(v.id), paintCount),
			key  = "vehicle",
			data = v,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local choice = gg.choice(SHOW_MENU, nil, name .. "\n" .. L("Vui lòng chọn xe"))
	if not choice then return end

	local item = MENU_CONFIG[choice]
	if not item then return end

	if item.key == "return" then
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if item.key == "all" then
		if totalPaints < 1 then
			gg.toast(L("Không có skin khả dụng"))
			return LootDefinition_unlockVehiclePaints(addressTable, field, name, Return, returnArgs)
		end

		local act = gg.alert(
			string.format("%s\n\n%s: %d",
				L("Bạn có chắc muốn chọn skin của tất cả xe không?"),
				L("Tổng số"), totalPaints),
			L("Xác nhận"), L("Hủy")
		)
		if act ~= 1 then
			return LootDefinition_unlockVehiclePaints(addressTable, field, name, Return, returnArgs)
		end

		local selectedList = {}
		for i = 1, #vehiclePaintsData do
			local paints = vehiclePaintsData[i].Chassis or {}
			for j = 1, #paints do
				selectedList[#selectedList + 1] = paints[j]
			end
		end

		if #selectedList < 1 then
			gg.toast(L("Không tìm thấy skin khả dụng"))
			return LootDefinition_unlockVehiclePaints(addressTable, field, name, Return, returnArgs)
		end

		return yj.runtime.executeFunction("LootDefinition_unlockVehiclePaints_EXECUTE",
			{addressTable, selectedList, field, name, "LootDefinition_unlockVehiclePaints",
			 {addressTable, field, name, Return, returnArgs}})
	end

	if item.key == "vehicle" then
		local vehicle = item.data
		local paints  = vehicle.Chassis or {}
		if #paints < 1 then
			gg.alert(L("Xe này không có skin khả dụng"))
			return LootDefinition_unlockVehiclePaints(addressTable, field, name, Return, returnArgs)
		end

		return LootDefinition_unlockVehiclePaints_SelectPaint(
