end

function LootDefinition_unlockVehiclePaints_EXECUTE(addressTable, selectedList, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVehiclePaints_EXECUTE',
		{addressTable, selectedList, field, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn mục nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _UnlockablePaint = yj.runtime.requireClass("UnlockablePaint") or {}
	local vehicleIdOffset = _UnlockablePaint.vehicleId and _UnlockablePaint.vehicleId.offset
	local paintIdOffset   = _UnlockablePaint.paintId   and _UnlockablePaint.paintId.offset
	local size            = _UnlockablePaint.__Size
	if not vehicleIdOffset or not paintIdOffset or not size or size == 0 then
		gg.toast(L("Metadata UnlockablePaint không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _CarSprite = yj.runtime.requireClass("CarSprite") or {}
	local _Customization = yj.runtime.requireClass("Customization") or {}

	local srcVehicleIdOffset = _Customization.vehicleId and _Customization.vehicleId.offset
	local srcPaintIdOffset   = _Customization.id and _Customization.id.offset
	if not srcVehicleIdOffset or not srcPaintIdOffset then
		gg.toast(L("Thiếu trường Customization trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local count    = #selectedList
	local STR_SIZE = 0x18

	local elemsAddr = yj.mem.allocZeroPage(count * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	local readMeta = {}
	for i = 1, count do
		local srcAddr = selectedList[i].address

		local vAddr = srcAddr + srcVehicleIdOffset

		local pAddr = srcAddr + srcPaintIdOffset
		for k = 0, 5 do
			readMeta[#readMeta + 1] = { address = vAddr + k * 4, dstBase = (i - 1) * size + vehicleIdOffset, k = k }
			readMeta[#readMeta + 1] = { address = pAddr + k * 4, dstBase = (i - 1) * size + paintIdOffset,   k = k }
		end
	end
	for i = 1, #readMeta do
		reads[i] = { address = readMeta[i].address, flags = 4 }
	end
	local values = gg.getValues(reads)

	local copyMods = {}
	for i = 1, #values do
		local meta = readMeta[i]
		copyMods[#copyMods + 1] = {
			address = elemsAddr + meta.dstBase + meta.k * 4,
			flags   = 4,
			value   = values[i].value,
		}
	end
	if #copyMods > 0 then gg.setValues(copyMods) end

	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + count * size }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + count * size }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_unlockVehiclePaints_EXECUTE",
		string.format("elems=0x%X count=%d", elemsAddr, count))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), count))

	return yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_unlockVehicleSpriteVariants(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVehicleSpriteVariants',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataVehicleSpriteVariantsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/VehicleSpriteVariantsData.lua")
		if not ok then
			log.error("LootDefinition_unlockVehicleSpriteVariants: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local vehicleSpriteVariantsData = getDataVehicleSpriteVariantsData()
	if not vehicleSpriteVariantsData or #vehicleSpriteVariantsData < 1 then
		log.error("LootDefinition_unlockVehicleSpriteVariants: VehicleSpriteVariantsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local totalVariants = 0
	for i = 1, #vehicleSpriteVariantsData do
		totalVariants = totalVariants + ((vehicleSpriteVariantsData[i].Wheel and #vehicleSpriteVariantsData[i].Wheel) or 0)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn biến thể của tất cả xe"), totalVariants),
		key  = "all",
	}
	for i, v in ipairs(vehicleSpriteVariantsData) do
		local variantCount = (v.Wheel and #v.Wheel) or 0
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\t%s (%d)",
				tostring(v.name), tostring(v.id), variantCount),
			key  = "vehicle",
			data = v,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local choice = gg.choice(SHOW_MENU, nil, name .. "\n" .. L("Vui lòng chọn xe"))
	if not choice then return end

	local item = MENU_CONFIG[choice]
	if not item then return end

	if item.key == "return" then
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if item.key == "all" then
		if totalVariants < 1 then
			gg.toast(L("Không có biến thể xe khả dụng"))
			return LootDefinition_unlockVehicleSpriteVariants(addressTable, field, name, Return, returnArgs)
		end
		local act = gg.alert(
			string.format("%s\n\n%s: %d",
				L("Bạn có chắc muốn chọn biến thể của tất cả xe không?"),
				L("Tổng số"), totalVariants),
			L("Xác nhận"), L("Hủy")
		)
		if act ~= 1 then
			return LootDefinition_unlockVehicleSpriteVariants(addressTable, field, name, Return, returnArgs)
		end

		local selectedList = {}
		for i = 1, #vehicleSpriteVariantsData do
			local variants = vehicleSpriteVariantsData[i].Wheel or {}
			for j = 1, #variants do
				selectedList[#selectedList + 1] = variants[j]
			end
		end
		if #selectedList < 1 then
			gg.toast(L("Không tìm thấy biến thể xe khả dụng"))
			return LootDefinition_unlockVehicleSpriteVariants(addressTable, field, name, Return, returnArgs)
		end
		return yj.runtime.executeFunction("LootDefinition_unlockVehicleSpriteVariants_EXECUTE",
			{addressTable, selectedList, field, name, "LootDefinition_unlockVehicleSpriteVariants",
			 {addressTable, field, name, Return, returnArgs}})
	end

	if item.key == "vehicle" then
		local vehicle = item.data
		local variants = vehicle.Wheel or {}
		if #variants < 1 then
			gg.alert(L("Xe này không có biến thể khả dụng"))
			return LootDefinition_unlockVehicleSpriteVariants(addressTable, field, name, Return, returnArgs)
		end
		return LootDefinition_unlockVehicleSpriteVariants_SelectVariant(
			addressTable, field, name, Return, returnArgs, vehicle)
	end
end

