function LootDefinition_unlockVehicleSpriteVariants_EXECUTE(addressTable, selectedList, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockVehicleSpriteVariants_EXECUTE',
		{addressTable, selectedList, field, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn mục nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _UnlockableSpriteVariant = yj.runtime.requireClass("UnlockableSpriteVariant") or {}
	local vehicleIdOffset = _UnlockableSpriteVariant.vehicleId and _UnlockableSpriteVariant.vehicleId.offset
	local partIdOffset    = _UnlockableSpriteVariant.partId    and _UnlockableSpriteVariant.partId.offset
	local variantIdOffset = _UnlockableSpriteVariant.variantId and _UnlockableSpriteVariant.variantId.offset
	local size            = _UnlockableSpriteVariant.__Size
	if not vehicleIdOffset or not partIdOffset or not variantIdOffset or not size or size == 0 then
		gg.toast(L("Metadata UnlockableSpriteVariant không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _Customization = yj.runtime.requireClass("Customization") or {}
	local srcVehicleIdOffset = _Customization.vehicleId and _Customization.vehicleId.offset
	local srcVariantIdOffset = _Customization.id        and _Customization.id.offset
	if not srcVehicleIdOffset or not srcVariantIdOffset then
		gg.toast(L("Thiếu trường Customization trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local count = #selectedList

	local PART_ID_STR = "wheel"
	local tmpPartStr = yj.mem.allocZeroPage(0x18)
	if not tmpPartStr or tmpPartStr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	yj.mem.stdstring.write(tmpPartStr, PART_ID_STR)

	local partDwords = yj.mem.dword.getBulk({
		tmpPartStr,      tmpPartStr + 4,  tmpPartStr + 8,
		tmpPartStr + 12, tmpPartStr + 16, tmpPartStr + 20,
	})
	local partBuf = {}
	for i = 1, 6 do
		partBuf[i] = partDwords[i] and partDwords[i].value or 0
	end

	local elemsAddr = yj.mem.allocZeroPage(count * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	local readMeta = {}
	for i = 1, count do
		local srcAddr = selectedList[i].address
		local vAddr = srcAddr + srcVehicleIdOffset
		local rAddr = srcAddr + srcVariantIdOffset
		for k = 0, 5 do
			readMeta[#readMeta + 1] = { address = vAddr + k * 4, dstBase = (i - 1) * size + vehicleIdOffset, k = k }
			readMeta[#readMeta + 1] = { address = rAddr + k * 4, dstBase = (i - 1) * size + variantIdOffset, k = k }
		end
	end
	for i = 1, #readMeta do
		reads[i] = { address = readMeta[i].address, flags = 4 }
	end
	local values = gg.getValues(reads)

	local writeMods = {}
	for i = 1, #values do
		local meta = readMeta[i]
		writeMods[#writeMods + 1] = {
			address = elemsAddr + meta.dstBase + meta.k * 4,
			flags   = 4,
			value   = values[i].value,
		}
	end

	for i = 1, count do
		local base = elemsAddr + (i - 1) * size + partIdOffset
		for k = 0, 5 do
			writeMods[#writeMods + 1] = {
				address = base + k * 4,
				flags   = 4,
				value   = partBuf[k + 1],
			}
		end
	end

	if #writeMods > 0 then gg.setValues(writeMods) end

	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + count * size }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + count * size }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_unlockVehicleSpriteVariants_EXECUTE",
		string.format("elems=0x%X count=%d partId=%s", elemsAddr, count, PART_ID_STR))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), count))

	return yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_unlockAdventureMaps(addressTable, field, name, Return, returnArgs)
