	end

	if #selectedList > 0 then
		local _EditorTheme = yj.runtime.requireClass("EditorTheme") or {}
		local idOffset = _EditorTheme.id and _EditorTheme.id.offset
		if not idOffset then
			gg.toast(L("Thiếu EditorTheme.id trong metadata"))
			return yj.runtime.executeFunction(Return, returnArgs)
		end

		return yj.runtime.executeFunction("LootDefinition_unlockVectorString_EXECUTE",
			{addressTable, selectedList, idOffset, field, name, "LootDefinition_unlockEditorThemes",
			 {addressTable, field, name, Return, returnArgs}})
	end
	return
end

function LootDefinition_chests(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_chests',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataSpecialCupRewardsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/SpecialCupRewardsData.lua")
		if not ok then
			log.error("LootDefinition_chests: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local chestsData = getDataSpecialCupRewardsData()
	if not chestsData or #chestsData < 1 then
		log.error("LootDefinition_chests: SpecialCupRewardsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local chests = {}
	for i = 1, #chestsData do
		local c = chestsData[i]
		chests[i] = {
			address = c.address,
			id      = c.id,
			name    = c.name,
			key     = i,
		}
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	for i, c in ipairs(chests) do
		MENU_CONFIG[i + 1] = {
			name = string.format("[%d] %s\t\t~\t\t%s",
				c.key, tostring(c.name), tostring(c.id)),
			key  = "single",
			data = c,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local choices = gg.multiChoice(SHOW_MENU, nil, name .. "\n" .. L("Vui lòng chọn rương cần thêm"))
	if not choices then return end

	local selectedList = {}
	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
			end
		end
	end

	if #selectedList < 1 then
		return
	end

	local input = gg.prompt(
		{ string.format("%s\n\n%s: %d\n%s",
			L("Nhập số lượng cần ghi cho mỗi rương"),
			L("Số rương đã chọn"), #selectedList,
			L("Ví dụ: 3 → ghi mỗi rương 3 lần")) },
		{ "1" },
		{ "number" }
	)
	if not input or not input[1] then
		return LootDefinition_chests(addressTable, field, name, Return, returnArgs)
	end

	local countPerChest = tonumber(input[1])
	if not countPerChest or countPerChest < 1 then
		gg.alert(L("Số lượng không hợp lệ, phải ≥ 1"))
		return LootDefinition_chests(addressTable, field, name, Return, returnArgs)
	end
	countPerChest = math.floor(countPerChest)

	local totalItems = #selectedList * countPerChest
	local confirm = gg.alert(
		string.format("%s\n\n%s: %d\n%s: %d\n%s: %d",
			L("Xác nhận ghi dữ liệu?"),
			L("Rương đã chọn"), #selectedList,
			L("Số lượng mỗi mục"), countPerChest,
			L("Tổng số mục"), totalItems),
		L("Xác nhận"), L("Hủy")
	)
	if confirm ~= 1 then
		return LootDefinition_chests(addressTable, field, name, Return, returnArgs)
	end

	return yj.runtime.executeFunction("LootDefinition_chests_EXECUTE",
		{addressTable, field, selectedList, countPerChest, name,
		 "LootDefinition_chests",
		 {addressTable, field, name, Return, returnArgs}})
end

function LootDefinition_chests_EXECUTE(addressTable, field, selectedList, countPerChest, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_chests_EXECUTE',
		{addressTable, field, selectedList, countPerChest, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn rương nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	countPerChest = tonumber(countPerChest) or 1
	countPerChest = math.floor(countPerChest)
	if countPerChest < 1 then countPerChest = 1 end

	local values = {}
	for i = 1, #selectedList do
		local chest = selectedList[i]
		local key = tonumber(chest.key)
		if not key then
			gg.toast(L("Chỉ số rương không hợp lệ: ") .. tostring(chest.id))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
		local v = key - 1
		if v < 0 then v = 0 end
		for _ = 1, countPerChest do
			values[#values + 1] = v
		end
	end

	if #values < 1 then
		gg.toast(L("Dữ liệu ghi đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local totalBytes = #values * 4
	local elemsAddr = yj.mem.allocZeroPage(totalBytes)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local edits = {}
	for i = 1, #values do
		edits[i] = {
			address = elemsAddr + (i - 1) * 4,
			flags   = 4,
			value   = values[i],
		}
	end
	gg.setValues(edits)

	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + totalBytes }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + totalBytes }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_chests_EXECUTE",
		string.format("elems=0x%X count=%d perChest=%d",
			elemsAddr, #values, countPerChest))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), #values))

	return yj.runtime.executeFunction(Return, returnArgs)
end

