function LootDefinition_vehicleChests_EXECUTE(addressTable, field, chest, vehicle, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_vehicleChests_EXECUTE',
		{addressTable, field, chest, vehicle, name, Return, returnArgs})

	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not chest or not chest.key then
		gg.toast(L("Dữ liệu rương không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not vehicle or not vehicle.address then
		gg.toast(L("Dữ liệu xe không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _VehicleChest = yj.runtime.requireClass("VehicleChest") or {}
	local vehicleIdOffset   = _VehicleChest.vehicleId   and _VehicleChest.vehicleId.offset
	local chestIndexOffset  = _VehicleChest.chestIndex  and _VehicleChest.chestIndex.offset
	local targetIndexOffset = _VehicleChest.targetIndex and _VehicleChest.targetIndex.offset
	local size              = _VehicleChest.__Size
	if not vehicleIdOffset or not chestIndexOffset or not targetIndexOffset or not size or size == 0 then
		gg.toast(L("Metadata VehicleChest không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _VehicleDefinition = yj.runtime.requireClass("VehicleDefinition") or {}
	local srcVehicleIdOffset = _VehicleDefinition.id and _VehicleDefinition.id.offset
	if not srcVehicleIdOffset then
		gg.toast(L("Thiếu VehicleDefinition.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local elemsAddr = yj.mem.allocZeroPage(size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local srcVidAddr = vehicle.address + srcVehicleIdOffset
	local reads = {}
	for k = 0, 5 do
		reads[#reads + 1] = { address = srcVidAddr + k * 4, flags = 4 }
	end
	local values = gg.getValues(reads)

	local writeMods = {}
	for k = 0, 5 do
		writeMods[#writeMods + 1] = {
			address = elemsAddr + vehicleIdOffset + k * 4,
			flags   = 4,
			value   = values[k + 1] and values[k + 1].value or 0,
		}
	end

	local chestIndexValue = tonumber(chest.key) - 1
	if chestIndexValue < 0 then chestIndexValue = 0 end
	writeMods[#writeMods + 1] = {
		address = elemsAddr + chestIndexOffset,
		flags   = 4,
		value   = chestIndexValue,
	}

	writeMods[#writeMods + 1] = {
		address = elemsAddr + targetIndexOffset,
		flags   = 4,
		value   = 0,
	}

	gg.setValues(writeMods)

	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + size }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + size }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_vehicleChests_EXECUTE",
		string.format("elems=0x%X chest=%s(idx=%d) vehicle=%s",
			elemsAddr, tostring(chest.id), chestIndexValue, tostring(vehicle.id)))
	gg.toast(string.format(L("✓ Đã ghi: %s → %s"),
		tostring(vehicle.name or vehicle.id),
		tostring(chest.name or chest.id)))

	return yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_currencies(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_currencies',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataCurrenciesData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/CurrenciesData.lua")
		if not ok then
			log.error("LootDefinition_currencies: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local currenciesData = getDataCurrenciesData()
	if not currenciesData or #currenciesData < 1 then
		log.error("LootDefinition_currencies: CurrenciesData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	Stack.Data = Stack.Data or {}
	if type(Stack.Data.LootCurrenciesCount) ~= "number" then
		Stack.Data.LootCurrenciesCount = 1
	end
	if type(Stack.Data.LootCurrenciesAmount) ~= "number" then
		Stack.Data.LootCurrenciesAmount = 1
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s: %d", L("Đặt số lượng"), Stack.Data.LootCurrenciesCount),
		key  = "set_count",
	}
	MENU_CONFIG[3] = {
		name = string.format("%s: %d", L("Đặt số tiền"), Stack.Data.LootCurrenciesAmount),
		key  = "set_amount",
	}
	MENU_CONFIG[4] = { name = string.format("%s (%d)", L("Chọn tất cả loại tiền tệ"), #currenciesData), key = "all" }
	for i, c in ipairs(currenciesData) do
		MENU_CONFIG[i + 4] = {
			name = string.format("%s\t\t~\t\t%s", tostring(c.name), tostring(c.id)),
			key  = "single",
			data = c,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local title = string.format("%s\n%s: %d  %s: %d",
		name,
		L("Số lượng"), Stack.Data.LootCurrenciesCount,
		L("Số tiền"), Stack.Data.LootCurrenciesAmount)

	local choices = gg.multiChoice(SHOW_MENU, nil, title)
	if not choices then return end

	local needReload = false
	local selectedList = {}

	local pickKeys = {}
	for i in pairs(choices) do pickKeys[#pickKeys + 1] = i end
	table.sort(pickKeys)

	for _, i in ipairs(pickKeys) do
		local a = MENU_CONFIG[i]
		if a then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "set_count" then
				local input = gg.prompt(
					{ L("Nhập số lần lặp cho mỗi loại tiền tệ") },
					{ tostring(Stack.Data.LootCurrenciesCount) },
					{ "number" }
				)
				if input and input[1] then
					local n = math.floor(tonumber(input[1]) or 0)
					if n >= 1 and n <= 10000 then
						Stack.Data.LootCurrenciesCount = n
						needReload = true
					else
						gg.alert(L("Số lượng phải từ 1 đến 10000"))
					end
				end
			elseif a.key == "set_amount" then
				local input = gg.prompt(
					{ L("Nhập số tiền cho mỗi loại tiền tệ") },
					{ tostring(Stack.Data.LootCurrenciesAmount) },
					{ "number" }
				)
				if input and input[1] then
					local n = math.floor(tonumber(input[1]) or 0)
					if n >= 1 then
						Stack.Data.LootCurrenciesAmount = n
						needReload = true
					else
						gg.alert(L("Số tiền phải ≥ 1"))
					end
				end
			elseif a.key == "all" then
				for j = 1, #currenciesData do
					selectedList[#selectedList + 1] = currenciesData[j]
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
			end
		end
	end

	if needReload then

		return LootDefinition_currencies(addressTable, field, name, Return, returnArgs)
	end

	if #selectedList < 1 then
		return
	end

	local totalItems = #selectedList * Stack.Data.LootCurrenciesCount
	local confirm = gg.alert(
		string.format("%s\n\n%s: %d\n%s: %d\n%s: %d\n%s: %d",
			L("Xác nhận ghi dữ liệu?"),
			L("Tiền tệ đã chọn"), #selectedList,
			L("Số lần lặp mỗi mục"), Stack.Data.LootCurrenciesCount,
			L("Số tiền mỗi mục"), Stack.Data.LootCurrenciesAmount,
			L("Tổng số mục"), totalItems),
		L("Xác nhận"), L("Hủy")
	)
	if confirm ~= 1 then
		return LootDefinition_currencies(addressTable, field, name, Return, returnArgs)
	end

	return yj.runtime.executeFunction("LootDefinition_currencies_EXECUTE",
		{addressTable, field, selectedList,
		 Stack.Data.LootCurrenciesCount, Stack.Data.LootCurrenciesAmount,
		 name, "LootDefinition_currencies",
		 {addressTable, field, name, Return, returnArgs}})
end

function LootDefinition_currencies_EXECUTE(addressTable, field, selectedList, countPer, amount, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_currencies_EXECUTE',
		{addressTable, field, selectedList, countPer, amount, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn loại tiền tệ nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	countPer = math.floor(tonumber(countPer) or 1)
	amount   = math.floor(tonumber(amount)   or 1)
	if countPer < 1 then countPer = 1 end
	if countPer > 10000 then countPer = 10000 end

	local _CurrencyAmount = yj.runtime.requireClass("CurrencyAmount") or {}
	local currencyOffset = _CurrencyAmount.currency and _CurrencyAmount.currency.offset
	local amountOffset   = _CurrencyAmount.amount   and _CurrencyAmount.amount.offset
	local padOffset      = _CurrencyAmount.field_1c and _CurrencyAmount.field_1c.offset
	local size           = _CurrencyAmount.__Size
	if not currencyOffset or not amountOffset or not size or size == 0 then
		gg.toast(L("Metadata CurrencyAmount không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _CurrencyDefinition = yj.runtime.requireClass("CurrencyDefinition") or {}
	local srcIdOffset = _CurrencyDefinition.id and _CurrencyDefinition.id.offset
	if not srcIdOffset then
		gg.toast(L("Thiếu CurrencyDefinition.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local flatList = {}
	for i = 1, #selectedList do
		local cur = selectedList[i]
		if not cur or not cur.address then
			gg.toast(L("Dữ liệu tiền tệ không hợp lệ"))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
		for _ = 1, countPer do
			flatList[#flatList + 1] = cur
		end
	end

	local total = #flatList
	if total < 1 then
		gg.toast(L("Dữ liệu ghi đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local elemsAddr = yj.mem.allocZeroPage(total * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local readCache = {}
	for i = 1, total do
		local cur = flatList[i]
		if not readCache[cur.address] then
			local srcAddr = cur.address + srcIdOffset
			local reads = {}
			for k = 0, 5 do
				reads[#reads + 1] = { address = srcAddr + k * 4, flags = 4 }
			end
			readCache[cur.address] = gg.getValues(reads)
		end
	end

	local writeMods = {}
	for i = 1, total do
		local cur = flatList[i]
		local base = elemsAddr + (i - 1) * size

		local srcVals = readCache[cur.address]
		for k = 0, 5 do
			writeMods[#writeMods + 1] = {
				address = base + currencyOffset + k * 4,
				flags   = 4,
				value   = srcVals[k + 1] and srcVals[k + 1].value or 0,
			}
		end

		writeMods[#writeMods + 1] = {
			address = base + amountOffset,
			flags   = 4,
			value   = amount,
		}

		if padOffset then
			writeMods[#writeMods + 1] = {
				address = base + padOffset,
				flags   = 4,
				value   = 0,
			}
		end
	end
	if #writeMods > 0 then gg.setValues(writeMods) end

	local totalBytes = total * size
	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + totalBytes }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + totalBytes }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_currencies_EXECUTE",
		string.format("elems=0x%X total=%d per=%d amount=%d",
			elemsAddr, total, countPer, amount))
	gg.toast(string.format(L("✓ Đã ghi %d mục (mỗi mục %d lần)"), total, amount))

	return yj.runtime.executeFunction(Return, returnArgs)
end

