function LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_tuningParts',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataVehicleTuningPartsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/VehicleTuningPartsData.lua")
		if not ok then
			log.error("LootDefinition_tuningParts: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local vehicles = getDataVehicleTuningPartsData()
	if not vehicles or #vehicles < 1 then
		log.error("LootDefinition_tuningParts: VehicleTuningPartsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local totalParts = 0
	for i = 1, #vehicles do
		totalParts = totalParts + ((vehicles[i].TuningParts and #vehicles[i].TuningParts) or 0)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn phụ tùng của tất cả xe"), totalParts),
		key  = "all",
	}
	for i, v in ipairs(vehicles) do
		local partCount = (v.TuningParts and #v.TuningParts) or 0
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\t%s (%d)",
				tostring(v.name), tostring(v.id), partCount),
			key  = "vehicle",
			data = v,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local choice = gg.choice(SHOW_MENU, nil, name .. "\n" .. L("Vui lòng chọn xe"))
	if not choice then return end

	local item = MENU_CONFIG[choice]
	if not item then return end

	if item.key == "return" then
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if item.key == "all" then
		if totalParts < 1 then
			gg.toast(L("Không có phụ tùng khả dụng"))
			return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
		end
		local act = gg.alert(
			string.format("%s\n\n%s: %d",
				L("Bạn có chắc muốn chọn toàn bộ phụ tùng của tất cả xe không?"),
				L("Tổng số"), totalParts),
			L("Xác nhận"), L("Hủy")
		)
		if act ~= 1 then
			return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
		end

		local selectedList = {}
		for i = 1, #vehicles do
			local v = vehicles[i]
			local parts = v.TuningParts or {}
			for j = 1, #parts do
				local p = parts[j]
				selectedList[#selectedList + 1] = {
					id             = p.id,
					address        = p.address,
					rarity         = p.rarity,
					vehicleAddress = v.address,
					vehicleId      = v.id,
					vehicleName    = v.name,
				}
			end
		end
		if #selectedList < 1 then
			gg.toast(L("Không tìm thấy phụ tùng khả dụng"))
			return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
		end
		return yj.runtime.executeFunction("LootDefinition_tuningParts_EXECUTE",
			{addressTable, field, selectedList, name, "LootDefinition_tuningParts",
			 {addressTable, field, name, Return, returnArgs}})
	end

	if item.key == "vehicle" then
		local vehicle = item.data
		local parts = vehicle.TuningParts or {}
		if #parts < 1 then
			gg.alert(L("Xe này không có phụ tùng khả dụng"))
			return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
		end
		return LootDefinition_tuningParts_SelectParts(
			addressTable, field, name, Return, returnArgs, vehicle)
	end
end

function LootDefinition_tuningParts_SelectParts(addressTable, field, name, Return, returnArgs, vehicle)
	yj.menu.registerMenuItem('LootDefinition_tuningParts_SelectParts',
		{addressTable, field, name, Return, returnArgs, vehicle})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not vehicle or not vehicle.TuningParts then
		gg.toast(L("Dữ liệu xe không hợp lệ"))
		return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
	end

	local parts = vehicle.TuningParts
	if #parts < 1 then
		gg.alert(L("Xe này không có phụ tùng khả dụng"))
		return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn tất cả phụ tùng"), #parts),
		key  = "all",
	}
	for i, p in ipairs(parts) do
		local r = tostring(p.rarity or "?")
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\trarity=%s",
				tostring(p.id), r),
			key  = "single",
			data = p,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local title = string.format("%s — %s (%d)",
		name, tostring(vehicle.name or vehicle.id), #parts)
	local choices = gg.multiChoice(SHOW_MENU, nil, title)
	if not choices then return end

	local selectedList = {}
	local function wrap(p)
		return {
			id             = p.id,
			address        = p.address,
			rarity         = p.rarity,
			vehicleAddress = vehicle.address,
			vehicleId      = vehicle.id,
			vehicleName    = vehicle.name,
		}
	end

	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
			elseif a.key == "all" then
				for j = 1, #parts do
					selectedList[#selectedList + 1] = wrap(parts[j])
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = wrap(a.data)
			end
		end
	end

	if #selectedList < 1 then
		return LootDefinition_tuningParts(addressTable, field, name, Return, returnArgs)
	end

	return yj.runtime.executeFunction("LootDefinition_tuningParts_EXECUTE",
		{addressTable, field, selectedList, name, "LootDefinition_tuningParts",
		 {addressTable, field, name, Return, returnArgs}})
end

function LootDefinition_tuningParts_EXECUTE(addressTable, field, selectedList, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_tuningParts_EXECUTE',
		{addressTable, field, selectedList, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn phụ tùng nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _TuningPartLoot = yj.runtime.requireClass("TuningPartLoot") or {}
	local idOffset       = _TuningPartLoot.id        and _TuningPartLoot.id.offset
	local vehicleIdOffset = _TuningPartLoot.vehicleId and _TuningPartLoot.vehicleId.offset
	local amountOffset   = _TuningPartLoot.amount    and _TuningPartLoot.amount.offset
	local rarityOffset   = _TuningPartLoot.rarity    and _TuningPartLoot.rarity.offset
	local size           = _TuningPartLoot.__Size
	if not idOffset or not vehicleIdOffset or not amountOffset or not rarityOffset or not size or size == 0 then
		gg.toast(L("Metadata TuningPartLoot không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _TuningPartParams = yj.runtime.requireClass("TuningPartParams") or {}
	local srcPartIdOffset = _TuningPartParams.id and _TuningPartParams.id.offset
	if not srcPartIdOffset then
		gg.toast(L("Thiếu TuningPartParams.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _VehicleDefinition = yj.runtime.requireClass("VehicleDefinition") or {}
	local srcVehicleIdOffset = _VehicleDefinition.id and _VehicleDefinition.id.offset
	if not srcVehicleIdOffset then
		gg.toast(L("Thiếu VehicleDefinition.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local RARITY_AMOUNT = {
		[1] = 2018,
		[2] = 368,
		[3] = 134,
		[4] = 30,
		[6] = 13,
	}

	local count = #selectedList
	local elemsAddr = yj.mem.allocZeroPage(count * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	local readMeta = {}
	for i = 1, count do
		local item = selectedList[i]
		local partAddr = item.address
		local vehAddr  = item.vehicleAddress

		for k = 0, 5 do
			readMeta[#readMeta + 1] = { address = partAddr + srcPartIdOffset + k * 4,
										dstBase = (i - 1) * size + idOffset, k = k }
		end

		for k = 0, 5 do
			readMeta[#readMeta + 1] = { address = vehAddr + srcVehicleIdOffset + k * 4,
										dstBase = (i - 1) * size + vehicleIdOffset, k = k }
		end
	end
	for i = 1, #readMeta do
		reads[i] = { address = readMeta[i].address, flags = 4 }
	end
	local values = gg.getValues(reads)

	local writeMods = {}
	for i = 1, #values do
		local meta = readMeta[i]
		writeMods[#writeMods + 1] = {
			address = elemsAddr + meta.dstBase + meta.k * 4,
			flags   = 4,
			value   = values[i] and values[i].value or 0,
		}
	end

	for i = 1, count do
		local item = selectedList[i]
		local rarity = tonumber(item.rarity) or 0
		local amount = RARITY_AMOUNT[rarity] or 1

		local base = elemsAddr + (i - 1) * size
		writeMods[#writeMods + 1] = {
			address = base + amountOffset,
			flags   = 4,
			value   = amount,
		}
		writeMods[#writeMods + 1] = {
			address = base + rarityOffset,
			flags   = 4,
			value   = rarity,
		}
	end

	if #writeMods > 0 then gg.setValues(writeMods) end

	local totalBytes = count * size
	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + totalBytes }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + totalBytes }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_tuningParts_EXECUTE",
		string.format("elems=0x%X count=%d", elemsAddr, count))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), count))

	return yj.runtime.executeFunction(Return, returnArgs)
end

