function LootDefinition_unlockHomeProps(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockHomeProps',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataHomeCosmeticsPropsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/HomeCosmeticsPropsData.lua")
		if not ok then
			log.error("LootDefinition_unlockHomeProps: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local propsData = getDataHomeCosmeticsPropsData()
	if not propsData or #propsData < 1 then
		log.error("LootDefinition_unlockHomeProps: HomeCosmeticsPropsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	Stack.Data = Stack.Data or {}
	if type(Stack.Data.LootHomePropsAmount) ~= "number" then
		Stack.Data.LootHomePropsAmount = 1
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s: %d", L("Đặt số lượng"), Stack.Data.LootHomePropsAmount),
		key  = "set_amount",
	}
	MENU_CONFIG[3] = { name = string.format("%s (%d)", L("Chọn tất cả vật phẩm nhà"), #propsData), key = "all" }
	for i, p in ipairs(propsData) do
		MENU_CONFIG[i + 3] = {
			name = string.format("%s\t\t~\t\t%s", tostring(p.name), tostring(p.id)),
			key  = "single",
			data = p,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local title = string.format("%s\n%s: %d",
		name, L("Số lượng"), Stack.Data.LootHomePropsAmount)

	local choices = gg.multiChoice(SHOW_MENU, nil, title)
	if not choices then return end

	local needReload = false
	local selectedList = {}

	local pickKeys = {}
	for i in pairs(choices) do pickKeys[#pickKeys + 1] = i end
	table.sort(pickKeys)

	for _, i in ipairs(pickKeys) do
		local a = MENU_CONFIG[i]
		if a then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "set_amount" then
				local input = gg.prompt(
					{ L("Nhập số lượng cho mỗi vật phẩm nhà") },
					{ tostring(Stack.Data.LootHomePropsAmount) },
					{ "number" }
				)
				if input and input[1] then
					local n = math.floor(tonumber(input[1]) or 0)
					if n >= 1 then
						Stack.Data.LootHomePropsAmount = n
						needReload = true
					else
						gg.alert(L("Số lượng phải ≥ 1"))
					end
				end
			elseif a.key == "all" then
				for j = 1, #propsData do
					selectedList[#selectedList + 1] = propsData[j]
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
			end
		end
	end

	if needReload then
		return LootDefinition_unlockHomeProps(addressTable, field, name, Return, returnArgs)
	end

	if #selectedList < 1 then
		return
	end

	local confirm = gg.alert(
		string.format("%s\n\n%s: %d\n%s: %d",
			L("Xác nhận ghi dữ liệu?"),
			L("Vật phẩm nhà đã chọn"), #selectedList,
			L("Số lượng mỗi mục"), Stack.Data.LootHomePropsAmount),
		L("Xác nhận"), L("Hủy")
	)
	if confirm ~= 1 then
		return LootDefinition_unlockHomeProps(addressTable, field, name, Return, returnArgs)
	end

	return yj.runtime.executeFunction("LootDefinition_unlockHomeProps_EXECUTE",
		{addressTable, field, selectedList, Stack.Data.LootHomePropsAmount,
		 name, "LootDefinition_unlockHomeProps",
		 {addressTable, field, name, Return, returnArgs}})
end

function LootDefinition_unlockHomeProps_EXECUTE(addressTable, field, selectedList, amount, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockHomeProps_EXECUTE',
		{addressTable, field, selectedList, amount, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn vật phẩm nhà nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	amount = math.floor(tonumber(amount) or 1)
	if amount < 1 then amount = 1 end

	local _HomePropLoot = yj.runtime.requireClass("HomePropLoot") or {}
	local idOffset     = _HomePropLoot.id       and _HomePropLoot.id.offset
	local amountOffset = _HomePropLoot.amount   and _HomePropLoot.amount.offset
	local padOffset    = _HomePropLoot.field_1c and _HomePropLoot.field_1c.offset
	local size         = _HomePropLoot.__Size
	if not idOffset or not amountOffset or not size or size == 0 then
		gg.toast(L("Metadata HomePropLoot không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _HomePropDefinition = yj.runtime.requireClass("HomePropDefinition") or {}
	local srcIdOffset = _HomePropDefinition.id and _HomePropDefinition.id.offset
	if not srcIdOffset then
		gg.toast(L("Thiếu HomePropDefinition.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local count = #selectedList
	local elemsAddr = yj.mem.allocZeroPage(count * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	local readMeta = {}
	for i = 1, count do
		local srcAddr = selectedList[i].address + srcIdOffset
		for k = 0, 5 do
			readMeta[#readMeta + 1] = {
				address = srcAddr + k * 4,
				dstBase = (i - 1) * size + idOffset,
				k       = k,
			}
		end
	end
	for i = 1, #readMeta do
		reads[i] = { address = readMeta[i].address, flags = 4 }
	end
	local values = gg.getValues(reads)

	local writeMods = {}
	for i = 1, #values do
		local meta = readMeta[i]
		writeMods[#writeMods + 1] = {
			address = elemsAddr + meta.dstBase + meta.k * 4,
			flags   = 4,
			value   = values[i] and values[i].value or 0,
		}
	end

	for i = 1, count do
		local base = elemsAddr + (i - 1) * size
		writeMods[#writeMods + 1] = {
			address = base + amountOffset,
			flags   = 4,
			value   = amount,
		}
		if padOffset then
			writeMods[#writeMods + 1] = {
				address = base + padOffset,
				flags   = 4,
				value   = 0,
			}
		end
	end
	if #writeMods > 0 then gg.setValues(writeMods) end

	local totalBytes = count * size
	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + totalBytes }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + totalBytes }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_unlockHomeProps_EXECUTE",
		string.format("elems=0x%X count=%d amount=%d", elemsAddr, count, amount))
	gg.toast(string.format(L("✓ Đã ghi %d mục (mỗi mục %d lần)"), count, amount))

	return yj.runtime.executeFunction(Return, returnArgs)
end

function LootDefinition_unlockHomeBackgrounds(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_unlockHomeBackgrounds', {addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataHomeCosmeticsBackgroundsData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/HomeCosmeticsBackgroundsData.lua")
		if not ok then
			log.error("LootDefinition_unlockHomeBackgrounds: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local homeBackgroundsData = getDataHomeCosmeticsBackgroundsData()
	if not homeBackgroundsData or #homeBackgroundsData < 1 then
		log.error("LootDefinition_unlockHomeBackgrounds: HomeCosmeticsBackgroundsData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = {name = L("Quay lại"), key = "return"}
	MENU_CONFIG[2] = {name = L("Chọn tất cả hình nền nhà"), key = "all"}
	for i, k in ipairs(homeBackgroundsData) do
		MENU_CONFIG[i + 2] = {name = k.name .. "\t\t~\t\t" .. k.id, key = "single", data = k}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Quay lại"), key = "return"}

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end
	local choices = gg.multiChoice(SHOW_MENU, nil, name)
	if not choices then return end

	local selectedList = {}
	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return yj.runtime.executeFunction(Return, returnArgs)
			elseif a.key == "all" then
				for j = 1, #homeBackgroundsData do
					selectedList[#selectedList + 1] = homeBackgroundsData[j]
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = a.data
