		end
	end

	if #selectedList > 0 then
		local _HomePropDefinition = yj.runtime.requireClass("HomePropDefinition") or {}
		local idOffset = _HomePropDefinition.id and _HomePropDefinition.id.offset
		if not idOffset then
			gg.toast(L("Thiếu HomePropDefinition.id trong metadata"))
			return yj.runtime.executeFunction(Return, returnArgs)
		end

		return yj.runtime.executeFunction("LootDefinition_unlockVectorString_EXECUTE",
			{addressTable, selectedList, idOffset, field, name, "LootDefinition_unlockHomeBackgrounds",
			 {addressTable, field, name, Return, returnArgs}})
	end
	return
