function LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_styleShards',
		{addressTable, field, name, Return, returnArgs})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if type(getDataVehicleStyleTracksData) ~= "function" then
		local ok, err = pcall(loadModule, "modules/get/data/VehicleStyleTracksData.lua")
		if not ok then
			log.error("LootDefinition_styleShards: ", tostring(err))
			return yj.runtime.executeFunction(Return, returnArgs)
		end
	end
	local vehicles = getDataVehicleStyleTracksData()
	if not vehicles or #vehicles < 1 then
		log.error("LootDefinition_styleShards: VehicleStyleTracksData ")
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local totalItems = 0
	for i = 1, #vehicles do
		totalItems = totalItems + #vehicles[i].StyleTracks
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn tất cả vật phẩm phong cách của mọi xe"), totalItems),
		key  = "all",
	}
	for i, v in ipairs(vehicles) do
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\t%s (%d)",
				tostring(v.name), tostring(v.id), #v.StyleTracks),
			key  = "vehicle",
			data = v,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local choice = gg.choice(SHOW_MENU, nil, name .. "\n" .. L("Vui lòng chọn xe"))
	if not choice then return end

	local item = MENU_CONFIG[choice]
	if not item then return end

	if item.key == "return" then
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	if item.key == "all" then
		if totalItems < 1 then
			gg.toast(L("Không có vật phẩm phong cách khả dụng"))
			return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
		end
		local act = gg.alert(
			string.format("%s\n\n%s: %d",
				L("Bạn có chắc muốn chọn tất cả vật phẩm phong cách của mọi xe không?"),
				L("Tổng số"), totalItems),
			L("Xác nhận"), L("Hủy")
		)
		if act ~= 1 then
			return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
		end

		local selectedList = {}
		for i = 1, #vehicles do
			local v = vehicles[i]
			for j = 1, #v.StyleTracks do
				local p = v.StyleTracks[j]
				selectedList[#selectedList + 1] = {
					id             = p.id,
					address        = p.address,
					vehicleId      = p.vehicleId,
					vehicleAddress = v.address,
					vehicleName    = v.name,
				}
			end
		end
		if #selectedList < 1 then
			gg.toast(L("Không tìm thấy vật phẩm phong cách khả dụng"))
			return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
		end
		return yj.runtime.executeFunction("LootDefinition_styleShards_EXECUTE",
			{addressTable, field, selectedList, name, "LootDefinition_styleShards",
			 {addressTable, field, name, Return, returnArgs}})
	end

	if item.key == "vehicle" then
		local vehicle = item.data
		if #vehicle.StyleTracks < 1 then
			gg.alert(L("Xe này không có vật phẩm phong cách khả dụng"))
			return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
		end
		return LootDefinition_styleShards_SelectItem(
			addressTable, field, name, Return, returnArgs, vehicle)
	end
end

function LootDefinition_styleShards_SelectItem(addressTable, field, name, Return, returnArgs, vehicle)
	yj.menu.registerMenuItem('LootDefinition_styleShards_SelectItem',
		{addressTable, field, name, Return, returnArgs, vehicle})
	addressTable = addressTable or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not vehicle or not vehicle.StyleTracks then
		gg.toast(L("Dữ liệu xe không hợp lệ"))
		return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
	end

	local items = vehicle.StyleTracks
	if #items < 1 then
		gg.alert(L("Xe này không có vật phẩm phong cách khả dụng"))
		return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
	end

	local MENU_CONFIG = {}
	MENU_CONFIG[1] = { name = L("Quay lại"), key = "return" }
	MENU_CONFIG[2] = {
		name = string.format("%s (%d)", L("Chọn tất cả vật phẩm phong cách"), #items),
		key  = "all",
	}
	for i, p in ipairs(items) do
		MENU_CONFIG[i + 2] = {
			name = string.format("%s\t\t~\t\t%s",
				tostring(p.id), tostring(p.vehicleId)),
			key  = "single",
			data = p,
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = { name = L("Quay lại"), key = "return" }

	local SHOW_MENU = {}
	for i = 1, #MENU_CONFIG do
		SHOW_MENU[i] = MENU_CONFIG[i].name
	end

	local title = string.format("%s — %s (%d)",
		name, tostring(vehicle.name or vehicle.id), #items)
	local choices = gg.multiChoice(SHOW_MENU, nil, title)
	if not choices then return end

	local function wrap(p)
		return {
			id             = p.id,
			address        = p.address,
			vehicleId      = p.vehicleId,
			vehicleAddress = vehicle.address,
			vehicleName    = vehicle.name,
		}
	end

	local selectedList = {}
	for i, v in pairs(choices) do
		local a = MENU_CONFIG[i]
		if a and v then
			if a.key == "return" then
				return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
			elseif a.key == "all" then
				for j = 1, #items do
					selectedList[#selectedList + 1] = wrap(items[j])
				end
			elseif a.key == "single" then
				selectedList[#selectedList + 1] = wrap(a.data)
			end
		end
	end

	if #selectedList < 1 then
		return LootDefinition_styleShards(addressTable, field, name, Return, returnArgs)
	end

	return yj.runtime.executeFunction("LootDefinition_styleShards_EXECUTE",
		{addressTable, field, selectedList, name, "LootDefinition_styleShards",
		 {addressTable, field, name, Return, returnArgs}})
end

function LootDefinition_styleShards_EXECUTE(addressTable, field, selectedList, name, Return, returnArgs)
	yj.menu.registerMenuItem('LootDefinition_styleShards_EXECUTE',
		{addressTable, field, selectedList, name, Return, returnArgs})

	addressTable = addressTable or {}
	selectedList = selectedList or {}
	if #addressTable < 1 then
		gg.toast(L("Dữ liệu địa chỉ đang trống"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if #selectedList < 1 then
		gg.toast(L("Chưa chọn mục nào"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end
	if not field or not field.offset then
		gg.toast(L("Trường dữ liệu không hợp lệ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _StyleShardReward = yj.runtime.requireClass("StyleShardReward") or {}
	local itemIdOffset    = _StyleShardReward.itemId    and _StyleShardReward.itemId.offset
	local vehicleIdOffset = _StyleShardReward.vehicleId and _StyleShardReward.vehicleId.offset
	local rarityOffset    = _StyleShardReward.rarity    and _StyleShardReward.rarity.offset
	local amountOffset    = _StyleShardReward.amount    and _StyleShardReward.amount.offset
	local size            = _StyleShardReward.__Size
	if not itemIdOffset or not vehicleIdOffset or not rarityOffset or not amountOffset or not size or size == 0 then
		gg.toast(L("Metadata StyleShardReward không đầy đủ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local _VehicleStyleTrackItem = yj.runtime.requireClass("VehicleStyleTrackItem") or {}
	local _VehicleDefinition     = yj.runtime.requireClass("VehicleDefinition") or {}
	local srcItemIdOffset    = _VehicleStyleTrackItem.id and _VehicleStyleTrackItem.id.offset
	local srcVehicleIdOffset = _VehicleDefinition.id    and _VehicleDefinition.id.offset
	if not srcItemIdOffset or not srcVehicleIdOffset then
		gg.toast(L("Thiếu VehicleStyleTrackItem.id / VehicleDefinition.id trong metadata"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local RARITY_FIXED = 0
	local AMOUNT_FIXED = 280

	local count = #selectedList
	local elemsAddr = yj.mem.allocZeroPage(count * size)
	if not elemsAddr or elemsAddr == 0 then
		gg.toast(L("Không thể cấp phát bộ nhớ"))
		return yj.runtime.executeFunction(Return, returnArgs)
	end

	local reads = {}
	local readMeta = {}
	for i = 1, count do
		local item = selectedList[i]
		local itemAddr    = item.address
		local vehicleAddr = item.vehicleAddress

		for k = 0, 5 do
			readMeta[#readMeta + 1] = {
				address = itemAddr + srcItemIdOffset + k * 4,
				dstBase = (i - 1) * size + itemIdOffset,
				k       = k,
			}
		end

		for k = 0, 5 do
			readMeta[#readMeta + 1] = {
				address = vehicleAddr + srcVehicleIdOffset + k * 4,
				dstBase = (i - 1) * size + vehicleIdOffset,
				k       = k,
			}
		end
	end
	for i = 1, #readMeta do
		reads[i] = { address = readMeta[i].address, flags = 4 }
	end
	local values = gg.getValues(reads)

	local writeMods = {}
	for i = 1, #values do
		local meta = readMeta[i]
		writeMods[#writeMods + 1] = {
			address = elemsAddr + meta.dstBase + meta.k * 4,
			flags   = 4,
			value   = values[i] and values[i].value or 0,
		}
	end

	for i = 1, count do
		local base = elemsAddr + (i - 1) * size
		writeMods[#writeMods + 1] = {
			address = base + rarityOffset,
			flags   = 4,
			value   = RARITY_FIXED,
		}
		writeMods[#writeMods + 1] = {
			address = base + amountOffset,
			flags   = 4,
			value   = AMOUNT_FIXED,
		}
	end
	if #writeMods > 0 then gg.setValues(writeMods) end

	local totalBytes = count * size
	local headerMods = {}
	for i = 1, #addressTable do
		local vecAddr = addressTable[i] + field.offset
		headerMods[#headerMods + 1] = { address = vecAddr,        flags = 32, value = elemsAddr }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x8,  flags = 32, value = elemsAddr + totalBytes }
		headerMods[#headerMods + 1] = { address = vecAddr + 0x10, flags = 32, value = elemsAddr + totalBytes }
	end
	if #headerMods > 0 then gg.setValues(headerMods) end

	log.info("LootDefinition_styleShards_EXECUTE",
		string.format("elems=0x%X count=%d rarity=%d amount=%d",
			elemsAddr, count, RARITY_FIXED, AMOUNT_FIXED))
	gg.toast(string.format(L("✓ Đã ghi %d mục"), count))

	return yj.runtime.executeFunction(Return, returnArgs)
end

