	},
}

local function normVer(s)
	if type(s) ~= "string" then return "" end
	return (s:gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s*%-%s*", "-"))
end

local function readLanguage()
	local il = Info and Info.Language
	PEM.language = "vi"
	return PEM.language
end
PEM.language = readLanguage()

local function loadBuiltin(relative, label, hard)
	local ok, mod = pcall(loadModule, "data/" .. PEM.path .. relative)
	if not ok or mod == nil then
		local msg = string.format("PEM : %s (%s)", label, tostring(mod))
		if hard then log.error(msg) else log.warn(msg) end
		return nil
	end
	return mod
end

local function initBuiltin()
	local versions = loadBuiltin("versions.lua", "versions.lua", true)
	if type(versions) ~= "table" or #versions == 0 then
		log.error("PEM: versions.lua  fallback")
		versions = { "1.0.0" }
	end
	PEM._builtin.versions = versions
	PEM._builtin.version = versions[#versions]
	local vd = PEM._builtin.version .. "/"
	PEM._builtin.customReward  = loadBuiltin(vd .. "customReward.lua", "customReward")
	PEM._builtin.update.zh      = loadBuiltin(vd .. "zh/update.lua", "update.zh")
	PEM._builtin.update.en      = loadBuiltin(vd .. "en/update.lua", "update.en")
	PEM._builtin.message.zh     = loadBuiltin(vd .. "zh/message.lua", "message.zh")
	PEM._builtin.message.en     = loadBuiltin(vd .. "en/message.lua", "message.en")
end
initBuiltin()

local function writeConfig(relativePath, name, data)
	if data == nil then return false end
	local ok, result = pcall(yj.config.file, relativePath, name, data)
	if not ok or result == nil then
		log.warn("PEM: ", relativePath, name)
		return false
	end
	return true
end

local function syncBuiltinToLocal()
	local ver = PEM._builtin.version
	if not ver then return false end

	local meta = yj.config.file(PEM.path, "_meta")
	if type(meta) == "table" and meta.version == ver then
		log.info("PEM: ", ver)
		return false
	end

	log.info("PEM: ", ver)
	local vd = PEM.path .. ver .. "/"
	if PEM._builtin.customReward then writeConfig(vd, "customReward", PEM._builtin.customReward) end
	if PEM._builtin.update.zh  then writeConfig(vd .. "zh/", "update", PEM._builtin.update.zh) end
	if PEM._builtin.update.en  then writeConfig(vd .. "en/", "update", PEM._builtin.update.en) end
	if PEM._builtin.message.zh then writeConfig(vd .. "zh/", "message", PEM._builtin.message.zh) end
	if PEM._builtin.message.en then writeConfig(vd .. "en/", "message", PEM._builtin.message.en) end
	writeConfig(PEM.path, "_meta", { version = ver })
	return true
end
syncBuiltinToLocal()

local function readLocalVersions()
	local list = yj.config.file(PEM.path, "versions")
	if type(list) ~= "table" or #list == 0 then
		list = PEM._builtin.versions
		if type(list) ~= "table" or #list == 0 then
			log.warn("PEMversions  {\"1.0.0\"}")
			list = { "1.0.0" }
		end
		yj.config.file(PEM.path, "versions", list)
	end
	PEM.versions = list
	return PEM.versions
end

local function readLocalVersion()
	local list = readLocalVersions()
	PEM.version = list[#list] or "1.0.0"
	return PEM.version
end

local function readConfig(relativePath, name)
	if type(relativePath) ~= "string" or type(name) ~= "string" or name == "" then
		log.warn("PEM: readConfig ", tostring(relativePath), tostring(name))
		return nil
	end
	local ok, result = pcall(yj.config.file, relativePath, name)
	if not ok or result == nil then
		log.warn("PEM: ", relativePath, name)
		return nil
	end
	return result
end

local function loadLocalData(version)
	if not version then return nil end
	PEM.version = version
	local vd = PEM.path .. version .. "/"
	PEM.customReward = readConfig(vd, "customReward") or PEM._builtin.customReward
	PEM.update.vi    = readConfig(vd .. "vi/", "update")  or PEM._builtin.update.vi
	PEM.message.vi   = readConfig(vd .. "vi/", "message") or PEM._builtin.message.vi
	PEM.customReward = PEM.customReward or ""
	PEM.update.vi    = PEM.update.vi    or ""
	PEM.message.vi   = PEM.message.vi   or ""
end
loadLocalData(readLocalVersion())

