	for i, v in ipairs(versions) do
		MENU_CONFIG[#MENU_CONFIG + 1] = {
			name = v .. (v == version and " ⏺" or ""),
			func = "PEM_switchVersion",
			params = {v},
		}
	end
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L(""), func = "PEM_showCheckUpdate"}
	MENU_CONFIG[#MENU_CONFIG + 1] = {name = L("Quay lại"), func = "PublicEventMod"}

	local title = L("\n: ") .. (PEM.version or L("Không rõ"))
	local menu = yj.menu.showMenu("PEM_version", MENU_CONFIG, title)
	if not menu then return end
	Stack.MenuIndex.PEM_version = menu

	local option = MENU_CONFIG[menu]
	if option and option.func then
		yj.menu.dispatchMenuItem(option)
	end
end

function PEM_switchVersion(version)
	if not version then return PEM_version() end
	PEM.versions = readLocalVersions() or {}

	local target
	for _, v in ipairs(PEM.versions) do
		if v == version then target = v; break end
	end

	if not target then
		gg.toast(L("") .. ": " .. tostring(version))
		return PEM_version()
	end
	if target == PEM.version then
		gg.toast(L("") .. ": " .. target)
		return PEM_version()
	end

	loadLocalData(target)
	gg.toast(L("") .. ": " .. target)
	return PEM_version()
end

function PEM_showCheckUpdate()
	gg.toast(L("..."))

	local cloudVer = (function()
		local url = PEM.url.version
		if type(url) ~= "string" or url == "" then return nil end
		local ok, content = pcall(function()
			if yj.net and yj.net.makeRequest then return yj.net.makeRequest(url) end
			local r = gg.makeRequest(url)
			return r and r.code == 200 and r.content or nil
		end)
		if not ok or type(content) ~= "string" or #content == 0 then return nil end
		return content:gsub("^%s+", ""):gsub("%s+$", "")
	end)()

	if not cloudVer then
		gg.alert(L("❌ \n\n"))
		return PEM_version()
	end

	local localVer = readLocalVersion() or ""
	if normVer(cloudVer) == normVer(localVer) then
		gg.alert(string.format(
			"✅ %s\n\n%s: %s",
			L(""),
			L(""), localVer
		))
		return PEM_version()
	end

	local act = gg.alert(
		string.format(
			"🌐 %s\n\n%s: %s\n%s: %s\n\n%s",
			L(""),
			L(""), localVer,
			L(""), cloudVer,
			L("")
		),
		L(""), L("Hủy")
	)

	if act == 1 then
		return PEM_refreshCloud(cloudVer)
	end
	return PEM_version()
end

function PEM_refreshCloud(cloudVer)
	if not cloudVer then
		cloudVer = readLocalVersion()
	end
	if not cloudVer then
		gg.alert(L(""))
		return PEM_version()
	end

	local relativePath = PEM.path .. cloudVer .. "/"
	local data = {
		{ url = PEM.url.customReward, relativePath = relativePath,        name = "customReward", builtin = PEM._builtin.customReward },
		{ url = PEM.url.update.zh,    relativePath = relativePath .. "zh/", name = "update",       builtin = PEM._builtin.update.zh },
		{ url = PEM.url.update.en,    relativePath = relativePath .. "en/", name = "update",       builtin = PEM._builtin.update.en },
		{ url = PEM.url.message.zh,   relativePath = relativePath .. "zh/", name = "message",      builtin = PEM._builtin.message.zh },
		{ url = PEM.url.message.en,   relativePath = relativePath .. "en/", name = "message",      builtin = PEM._builtin.message.en },
	}

	local failCount = 0
	for i = 1, #data do
		local k = data[i]
		local ok, fetchResult = pcall(yj.config.fetchCloudFile,
			k.url, k.relativePath, k.name, k.builtin, true)
		if not ok or fetchResult == nil then
			log.error("PEM: ", k.name, tostring(fetchResult))
			failCount = failCount + 1
		else
			log.info("PEM: ", k.name)
		end
	end

	if failCount > 0 then
		gg.alert(string.format(L(" (%d/%d)"), failCount, #data))
	else
		gg.toast(L(""))
	end

	local versions = readLocalVersions() or {}
	local found = false
	for _, v in ipairs(versions) do
		if v == cloudVer then found = true; break end
	end
	if not found then
		versions[#versions + 1] = cloudVer
		PEM.versions = versions
		yj.config.file(PEM.path, "versions", versions)
	end
	loadLocalData(cloudVer)

	return PEM_version()
end

