local HCR2_PKG = "com.fingersoft.hcr2"
local VM_PKG   = "com.waxmoon.ma.gp"

local function selectUserPath()
	local paths, labels = {}, {}

	local function addCandidate(lbl, p)
		for _, existing in ipairs(paths) do
			if existing == p then return end
		end
		paths[#paths + 1] = p
		labels[#labels + 1] = lbl
	end

	local function exists(p)
		if not p then return false end
		local f = File(p)
		return f and f:exists()
	end

	local rootDir = File("/data/user/0/" .. VM_PKG .. "/rootfs/data/user/")
	local foundUids = {}
	if rootDir and rootDir:exists() and rootDir:isDirectory() then
		local files = rootDir:listFiles()
		if files then
			for i = 1, #files do
				local name = files[i]:getName()
				if name and name:match("^%d+$") then
					foundUids[#foundUids + 1] = name
				end
			end
		end
	end
	table.sort(foundUids, function(a, b) return tonumber(a) < tonumber(b) end)

	for _, uid in ipairs(foundUids) do
		local vmPath = string.format("/data/user/0/%s/rootfs/data/user/%s/%s/files/content_cache/json/events/",
			VM_PKG, uid, HCR2_PKG)
		if exists(vmPath) or exists(string.format("/data/user/0/%s/rootfs/data/user/%s/%s", VM_PKG, uid, HCR2_PKG)) then
			addCandidate("User " .. (tonumber(uid) + 1), vmPath)
		end
	end

	if #paths == 0 then
		local native = "/data/user/0/" .. HCR2_PKG .. "/files/content_cache/json/events/"
		if exists(native) then addCandidate("User 1 (Native)", native) end
		local main = "/data/data/" .. HCR2_PKG .. "/files/content_cache/json/events/"
		if exists(main) then addCandidate("Main System", main) end
	end

	if #paths == 0 then
		addCandidate("User 1 (Default)",
			string.format("/data/user/0/%s/rootfs/data/user/0/%s/files/content_cache/json/events/", VM_PKG, HCR2_PKG))
	end

	if #paths == 1 then
		return paths[1], labels[1]
	end

	local choice
	while not choice or choice == 0 do
		choice = gg.choice(labels, nil,
			string.format(L("\n %d  HCR2"), #paths))
		if not choice or choice == 0 then gg.toast(L("")) end
	end
	return paths[choice], labels[choice]
end

local function readEncryptedJson(srcPath)
	local dec = srcPath .. ".pem_tmp"
	local meta = Crypto.decrypt(srcPath, dec)
	if not meta then return nil, "" end
	local f = io.open(dec, "r")
	if not f then return nil, "" end
	local content = f:read("*a")
	f:close()
	os.remove(dec)
	local ok, data = pcall(yj.json.decode, content)
	if not ok or not data then return nil, "JSON " end
	return data, nil, meta
end

local function writeEncryptedJson(dstPath, data, meta)
	local ok, content = pcall(yj.json.encode, data)
	if not ok or not content then return false, "JSON " end

	local dec = dstPath .. ".pem_tmp"
	local f = io.open(dec, "w")
	if not f then return false, "" end
	f:write(content)
	f:flush()
	f:close()

	local ok2, err = pcall(Crypto.encrypt, dec, dstPath, meta)
	os.remove(dec)
	if not ok2 then return false, ": " .. tostring(err) end
	return true
end

function PEM_patchRewards()
	yj.menu.registerMenuItem("PEM_patchRewards")
	gg.toast(L("....."))

	if not Crypto or not Zip then
		gg.alert(L(" Crypto/Zip "))
		return PublicEventMod()
	end

	local modContent
	local ok, modContent = pcall(Zip.decompress, PEM.customReward)
	if not ok or not modContent then
		gg.alert(L(": ") .. tostring(modContent))
		return PublicEventMod()
	end

	local jsonMod = yj.json.safeDecode and yj.json.safeDecode(modContent) or yj.json.decode(modContent)
	if not jsonMod or not jsonMod.eventRewards then
		gg.alert(L(" eventRewards"))
		return PublicEventMod()
	end
	local eventRewardsData = jsonMod.eventRewards

	local path, spaceName = selectUserPath()
	if not path then return PublicEventMod() end

	local jsonActive, readErr = readEncryptedJson(path .. "active_events.json")
	if not jsonActive then
		gg.alert(L(" active_events : ") .. tostring(readErr))
		return PublicEventMod()
	end

	local gameEvents = jsonActive.gameEvents or {}
	if #gameEvents == 0 then
		gg.alert(L(""))
		return PublicEventMod()
	end

	local labels = {}
	for i, eventName in ipairs(gameEvents) do
		local ev, _, _ = readEncryptedJson(path .. eventName .. ".json")
		local displayName = eventName
		if ev and ev.name then
			if type(ev.name) == "table" and ev.name.value then
				displayName = ev.name.value .. " (" .. eventName .. ")"
			elseif type(ev.name) == "string" then
				displayName = ev.name .. " (" .. eventName .. ")"
			end
		end
		labels[i] = displayName
	end

	local promptMsg = L(":")
	if spaceName then promptMsg = promptMsg .. "\n" .. L(": ") .. spaceName end
	local selections = gg.multiChoice(labels, nil, promptMsg)
	if not selections then return PublicEventMod() end

	local successList, failedList = {}, {}

	local function patchEventName(v)
		local text, localize = "", ""
		if type(v) == "table" then
			text = v.value or ""
			localize = v.localize or ""
		else
			text = tostring(v or "")
		end
		if not text:find("Lan9118 Mod") then
			text = text .. " (Lan9118 Mod)"
		end
		return { value = text, localize = localize }
	end

	local function replaceMaxCollectAmount(data)
		if type(data) ~= "table" then return end
		for k, v in pairs(data) do
			if k == "maxCollectAmount" then
				data[k] = -1
			elseif type(v) == "table" then
				replaceMaxCollectAmount(v)
			end
		end
	end

	local function removeCriteriaCurve(t)
		if type(t) ~= "table" then return end
		for k, v in pairs(t) do
			if k == "criteriaCurve" then
				t[k] = nil
			elseif type(v) == "table" then
				removeCriteriaCurve(v)
			end
		end
	end

	for idx, selected in pairs(selections) do
		if selected then
			local eventName = gameEvents[idx]
			if not eventName then
				failedList[#failedList + 1] = L(": ") .. tostring(idx)
			else
				local evPath = path .. eventName .. ".json"
				local jsonEvent, evErr, evMeta = readEncryptedJson(evPath)
				if not jsonEvent then
					failedList[#failedList + 1] = eventName .. ": " .. tostring(evErr)
				else
					jsonEvent.eventRewards = eventRewardsData
					jsonEvent.name = patchEventName(jsonEvent.name)
					replaceMaxCollectAmount(jsonEvent)
					for _, item in ipairs(jsonEvent.rotatingEventRewards or {}) do
						if item.rewardCondition then item.rewardCondition.criteria = 0 end
					end
					for _, item in ipairs(jsonEvent.eventSpecials or {}) do
						if item.rewardCondition then item.rewardCondition.criteria = 0 end
					end
					removeCriteriaCurve(jsonEvent)

					local wok, werr = writeEncryptedJson(evPath, jsonEvent, evMeta)
					if wok then
						successList[#successList + 1] = eventName
					else
						failedList[#failedList + 1] = eventName .. ": " .. tostring(werr)
					end
				end
			end
		end
	end

	local msg = ""
	if #successList > 0 then
		msg = msg .. L(":\n") .. table.concat(successList, "\n") .. "\n\n"
	end
	if #failedList > 0 then
		msg = msg .. L(":\n") .. table.concat(failedList, "\n")
	end
	if msg == "" then msg = L("") end
	gg.alert(msg)

	if #successList > 0 then
		if gg.alert(L(""), L("Xác nhận"), L("Hủy")) == 1 then
			gg.processKill()
			gg.sleep(500)
			os.exit()
		end
	end
	return PublicEventMod()
end

function PEM_restoreReward()
	yj.menu.registerMenuItem("PEM_restoreReward")
	gg.toast(L("....."))

	if not Crypto then
		gg.alert(L(" Crypto "))
		return PublicEventMod()
	end

	local path, spaceName = selectUserPath()
	if not path then return PublicEventMod() end

	local jsonActive, readErr = readEncryptedJson(path .. "active_events.json")
	if not jsonActive then
		gg.alert(L(" active_events : ") .. tostring(readErr))
		return PublicEventMod()
	end

	local gameEvents = jsonActive.gameEvents or {}
	if #gameEvents == 0 then
		gg.alert(L(""))
		return PublicEventMod()
	end

	local labels = {}
	for i, eventName in ipairs(gameEvents) do
		local ev = readEncryptedJson(path .. eventName .. ".json")
		local displayName = eventName
		if ev and ev.name then
			if type(ev.name) == "table" and ev.name.value then
				displayName = ev.name.value .. " (" .. eventName .. ")"
			elseif type(ev.name) == "string" then
				displayName = ev.name .. " (" .. eventName .. ")"
			end
		end
		labels[i] = displayName
	end

	local promptMsg = L(":")
	if spaceName then promptMsg = promptMsg .. "\n" .. L(": ") .. spaceName end
	local selections = gg.multiChoice(labels, nil, promptMsg)
	if not selections then return PublicEventMod() end

	local deleted, failed = {}, {}
	for idx, selected in pairs(selections) do
		if selected then
			local eventName = gameEvents[idx]
			if not eventName then
				failed[#failed + 1] = L(": ") .. tostring(idx)
			else
				local evPath = path .. eventName .. ".json"
				local ok = os.remove(evPath)
				if ok then
					deleted[#deleted + 1] = eventName
				else
					failed[#failed + 1] = eventName
				end
			end
		end
	end

	local msg = ""
	if #deleted > 0 then
		msg = msg .. L(":\n") .. table.concat(deleted, "\n") .. "\n\n"
	end
	if #failed > 0 then
		msg = msg .. L(":\n") .. table.concat(failed, "\n")
	end
	if msg == "" then msg = L("") end
	gg.alert(msg)

	if #deleted > 0 then
		if gg.alert(L(""), L("Xác nhận"), L("Hủy")) == 1 then
			gg.processKill()
			gg.sleep(500)
			os.exit()
		end
	end
	return PublicEventMod()
end

function PEM_kill()
	if gg.alert(L("\n"), L("Xác nhận"), L("Hủy")) == 1 then
		local printData = (
			string.format(L("%d\n"), os.time() - Info.script.startTime)
			 .. L("\n") .. (yj.str.randomWords() or "")
		)
		gg.clearResults()
		gg.setRanges(Stack.BaseRegion)
		print(printData)
		log.info(": ", printData)

		local StackLog = yj.table.deepCopyWithout(Stack, {
			"BYTE2CHAR",
			"Language",
			"TargetInfo.activities",
			"Menus",
			"Menu",
		})
		log.info("Stack: ", StackLog)
		log.flush()

		gg.processKill()
		gg.sleep(500)
		os.exit()
	else
		return PublicEventMod()
	end
end

