__vfs['modules/ops/MoreSettings_/AIChat.lua'] = [[yj.json         = yj.json         or loadModule("core/utils/json/json.lua")
yj.fs.writeFile = yj.fs.writeFile or loadModule("core/utils/fs/writeFile.lua")
yj.fs.readFile  = yj.fs.readFile  or loadModule("core/utils/fs/readFile.lua")

local API_URL  = "https://open.bigmodel.cn/api/paas/v4/chat/completions"
local MODEL    = "glm-4.7"
local KEY_API  = "AI.Chat.ApiKey"
local KEY_SYS  = "AI.Chat.System"
local KEY_TYPE = "AI.Chat.Typewriter"

local DEFAULT_API_KEY = "0640d555cf6c495aadafeaeaf5bd795b.la5GjG6TjfpmD6wp"
local DEFAULT_SYSTEM  = "AI"

local HISTORY_FILE = "/sdcard/Gentle/chat_history.txt"

local session = session or { history = nil }
local function resetSession()
	session.history = {
		{ role = "system", content = yj.config.configItem(KEY_SYS) or DEFAULT_SYSTEM }
	}
end

local function getApiKey()
	local k = yj.config.configItem(KEY_API)
	if type(k) == "string" and k ~= "" then return k end
	yj.config.configItem(KEY_API, DEFAULT_API_KEY)
	return DEFAULT_API_KEY
end

local function isTypewriterOn()
	return tostring(yj.config.configItem(KEY_TYPE)) ~= "0"
end

local function typewriterShow(text, name)
	name = name or "🤖"
	local STEP  = 12
	local delay = 40

	if not utf8 then
		for i = 1, #text, STEP * 3 do
			gg.toast(name .. "> " .. text:sub(1, i))
			gg.sleep(delay)
		end
		return
	end

	local chars = {}
	for _, c in utf8.codes(text) do chars[#chars + 1] = utf8.char(c) end
	local buf = ""
	for i = 1, #chars do
		buf = buf .. chars[i]
		if i % STEP == 0 or i == #chars then
			gg.toast(name .. "> " .. buf)
			gg.sleep(delay)
		end
	end
end

local function callGLM(messages)
	local payload = yj.json.encode({
		model = MODEL,
		messages = messages,
		stream = false,
	})

	local ok, res = pcall(function()
		return gg.makeRequest(API_URL, {
			["Content-Type"]  = "application/json",
			["Authorization"] = "Bearer " .. getApiKey(),
		}, payload)
	end)

	if not ok then
		return nil, ": " .. tostring(res)
	end
	if type(res) ~= "table" then
		return nil, ""
	end
	if tonumber(res.code) ~= 200 then
		local msg = "HTTP " .. tostring(res.code)
		local err = yj.json.decode(res.content or "")
		if err and err.error and err.error.message then
			msg = msg .. "\n" .. tostring(err.error.message)
		end
		return nil, msg
	end

	local data = yj.json.decode(res.content or "")
	if not data or not data.choices or not data.choices[1] then
		return nil, ""
	end
	return data.choices[1].message.content
end

function AIChat_StartChat()
	yj.menu.registerMenuItem("AIChat")
	if not session.history then resetSession() end

	local input = gg.prompt(
		{ L("") },
		{ "" },
		{ "text" }
	)
	if not input or not input[1] or input[1] == "" then
		return AIChat()
	end

	session.history[#session.history + 1] = { role = "user", content = input[1] }

	gg.toast(L("AI ..."))
	local reply, err = callGLM(session.history)

	if reply then
		session.history[#session.history + 1] = { role = "assistant", content = reply }

		if isTypewriterOn() then
			typewriterShow(reply, "🤖")
		end

		local act = gg.alert(
			"🤖 " .. L("AI ") .. ":\n\n" .. reply .. "\n\n————\n" .. L(""),
			L(""), L(""), L("")
		)
		if act == 1 then
			AIChat_Export()
		elseif act == 3 then
			resetSession()
			gg.toast(L(""))
		end
	else
		table.remove(session.history)
		gg.alert("⚠️ " .. L("") .. ":\n\n" .. tostring(err))
	end

	return AIChat()
end

function AIChat_ClearChat()
	yj.menu.registerMenuItem("AIChat")
	resetSession()
	gg.toast(L(""))
	return AIChat()
end

function AIChat_Export()
	yj.menu.registerMenuItem("AIChat")
	if not session.history or #session.history <= 1 then
		gg.alert(L(""))
		return AIChat()
	end

	local lines = {
		"===== Gentle AI  =====",
		os.date(": %Y-%m-%d %H:%M:%S"),
		": " .. MODEL,
		"",
	}
	for _, m in ipairs(session.history) do
		local who = ({ system = "⚙ ", user = "👤 ", assistant = "🤖 AI" })[m.role] or m.role
		lines[#lines + 1] = who .. ":"
		lines[#lines + 1] = m.content
		lines[#lines + 1] = ""
	end

	local ok, err = yj.fs.writeFile(HISTORY_FILE, table.concat(lines, "\n"))
	if ok then
		gg.alert("✅ " .. L("") .. ":\n" .. HISTORY_FILE)
	else
		gg.alert("⚠️ " .. L("") .. ":\n" .. tostring(err))
	end
	return AIChat()
end

function AIChat_ViewHistory()
	yj.menu.registerMenuItem("AIChat")
	local content, err = yj.fs.readFile(HISTORY_FILE)
	if not content then
		gg.alert("⚠️ " .. L("") .. ":\n" .. tostring(err))
		return AIChat()
	end

	local MAX = 3000
	if #content > MAX then
		content = "...(" .. L("") .. ")...\n" .. content:sub(-MAX)
	end
	gg.alert("📂 " .. L("") .. ":\n\n" .. content)
	return AIChat()
end

function AIChat_SetApiKey()
	yj.menu.registerMenuItem("AIChat")
	local input = gg.prompt(
		{ L(" API Key") },
		{ getApiKey() },
		{ "text" }
	)
	if input and input[1] and input[1] ~= "" then
		yj.config.configItem(KEY_API, input[1])
		gg.toast(L("API Key "))
	end
	return AIChat()
end

function AIChat_SetSystem()
	yj.menu.registerMenuItem("AIChat")
	local input = gg.prompt(
		{ L("AI ") },
		{ yj.config.configItem(KEY_SYS) or DEFAULT_SYSTEM },
		{ "text" }
	)
	if input and input[1] and input[1] ~= "" then
		yj.config.configItem(KEY_SYS, input[1])
		resetSession()
