	return AIChat()
end

function AIChat_ToggleTypewriter()
	yj.menu.registerMenuItem("AIChat")
	local on = isTypewriterOn()
	yj.config.configItem(KEY_TYPE, on and "0" or "1")
	gg.toast(on and L("") or L(""))
	return AIChat()
end

local _menuReentry = 0
function AIChat()
	_menuReentry = _menuReentry + 1
	if _menuReentry > 200 then
		_menuReentry = 0
		return
	end

	local MENU_CONFIG = {
		{ name = L("💬 "),        func = "AIChat_StartChat" },
		{ name = L("🗑 "),        func = "AIChat_ClearChat" },
		{ name = L("💾 "),    func = "AIChat_Export" },
		{ name = L("📂 "),    func = "AIChat_ViewHistory" },
		{ name = L("🔑  API Key"),    func = "AIChat_SetApiKey" },
		{ name = L("🎭 "),   func = "AIChat_SetSystem" },
		{ name = L("⌨️ "),   func = "AIChat_ToggleTypewriter" },
		{ name = L("🔙 "),            func = "MoreSettings_", module = "modules/ops/MoreSettings_.lua" },
	}

	local turns = session.history and (#session.history - 1) or 0
	local menu = yj.menu.showMenu(
		'AIChat',
		MENU_CONFIG,
		string.format("🤖 %s (%s: %d · %s)", L("AI "), L(""), turns,
			isTypewriterOn() and L("") or L(""))
	)
	if not menu then return end

	local item = MENU_CONFIG[menu]
	if not item then return end

	if menu == 8 then
		MoreSettings_()
		return
	end

	Stack.MenuIndex.AIChat = menu
	yj.menu.dispatchMenuItem(item)
end
]]

