__vfs['modules/ops/MoreSettings_/Exit_0.lua'] = [[yj.str.randomWords     = yj.str.randomWords     or loadModule("core/utils/str/randomWords.lua")
yj.table.deepCopyWithout = yj.table.deepCopyWithout or loadModule("core/utils/table/deepCopyWithout.lua")

function Exit_0()
	local exit = gg.alert("Bạn có chắc chắn muốn thoát script không?", "Thoát", "Hủy")
	if exit == 1 then
		Exit()
	else
		Main()
	end
end

function Exit()
	local printData = (
		string.format(L("%d\n"), os.time() - Info.script.startTime)
		 .. L("\n") .. yj.str.randomWords()
	)
	gg.clearResults()
	gg.setRanges(Stack.BaseRegion)
	print(printData)
	log.info(": ", printData)

	local StackLog = yj.table.deepCopyWithout(Stack, {
		"BYTE2CHAR",
		"Language",
		"TargetInfo.activities",
		"Menus",
	})
	log.info("Stack: ", StackLog)
	log.flush()
	os.exit()
end
