__vfs['modules/ops/MoreSettings_/ThemeSettings.lua'] = [[function ThemeSettings()
	yj.menu.registerMenuItem("ThemeSettings")

	local names = yj.ui.theme.list()
	local current = yj.ui.theme.getName()

	local items = {}
	for _, n in ipairs(names) do
		local t, kind = yj.ui.theme.get(n)
		local mark = (n == current) and " ⏺" or ""
		local tag = (kind == "builtin") and L(" []") or L(" []")
		items[#items + 1] = {name = n .. tag .. mark}
	end

	local engineLabel = (yj.ui.engine == "luajava") and L("LuaJava ") or L("GG ")
	items[#items + 1] = {name = L("🖼 ") .. ": " .. engineLabel}

	items[#items + 1] = {name = L("➕ ")}
	items[#items + 1] = {name = L("✏️ ")}
	items[#items + 1] = {name = L("🗑 ")}
	items[#items + 1] = {name = L("📤 ")}
	items[#items + 1] = {name = L("🔙 ")}

	local choice = yj.menu.showMenu("ThemeSettings", items, L("🎨 "))
	if not choice then return end
	Stack.MenuIndex.ThemeSettings = choice

	local base = #names

	if choice >= 1 and choice <= base then
		local name = names[choice] or ""
		yj.ui.theme.set(name)
		gg.toast(L("") .. ": " .. name)
		return ThemeSettings()
	end

	if choice == base + 1 then
		return ThemeEngineSettings()
	end
	if choice == base + 2 then return ThemeNew() end
	if choice == base + 3 then return ThemeEdit() end
	if choice == base + 4 then return ThemeDelete() end
	if choice == base + 5 then return ThemeExport() end
	if choice == base + 6 then return MoreSettings_() end
end

function ThemeEngineSettings()
	yj.menu.registerMenuItem("ThemeEngineSettings")

	local items = {
		L("GG ") .. (yj.ui.engine == "gg" and " ⏺" or ""),
		L("LuaJava ") .. (yj.ui.engine == "luajava" and " ⏺" or ""),
		L("🔙 "),
	}
	local choice = gg.choice(items, nil, L("🖼 "))
	if not choice then return ThemeSettings() end

	if choice == 1 then
		yj.ui.setEngine("gg")
		gg.toast(L("") .. ": " .. L("GG "))
	elseif choice == 2 then

		local Tools = yj.java and yj.java.Classes and yj.java.Classes.Tools
		local Ui = yj.java and yj.java.Classes and yj.java.Classes.Ui
		if not Tools or not Ui or not Tools.e() then
			gg.alert(L("❌ LuaJava Tools/Ui/ctx "))
			return ThemeEngineSettings()
		end
		yj.ui.setEngine("luajava")
		gg.toast(L("") .. ": " .. L("LuaJava "))
	end
	return ThemeSettings()
end

local THEME_KEYS = { "BG", "HEADER", "CARD", "ACCENT", "MUTED", "TEXT", "SUB", "STROKE" }

local function parseThemeColors(colors)
	local t = {}
	for i, k in ipairs(THEME_KEYS) do
		local hex = colors[i]:gsub("^0[xX]", "")
		local n = tonumber(hex, 16)
		if not n then
			return nil, colors[i]
		end
		t[k] = n
	end
	return t
end

function ThemeNew()
	local input = gg.prompt(
		{ L("//") },
		{ "my_theme" },
		{ "text" }
	)
	if not input or not input[1] or input[1] == "" then return ThemeSettings() end
	local name = input[1]

	local cur = yj.ui.theme.getCurrent()
	local defaults = {}
	for i, k in ipairs(THEME_KEYS) do
		defaults[i] = string.format("0x%08X", cur[k] & 0xFFFFFFFF)
	end

	local colors = gg.prompt(
		THEME_KEYS,
		defaults,
		{ "text", "text", "text", "text", "text", "text", "text", "text" }
	)
	if not colors then return ThemeSettings() end

	local t, bad = parseThemeColors(colors)
	if not t then
		gg.alert(L("") .. ": " .. bad)
		return ThemeNew()
	end

	local ok, err = yj.ui.theme.save(name, t)
	if ok then
		gg.toast(L("") .. ": " .. name)
		yj.ui.theme.set(name)
	else
		gg.alert(L("") .. ": " .. tostring(err))
	end
	return ThemeSettings()
end

function ThemeEdit()
	local name = yj.ui.theme.getName()
	local t, kind = yj.ui.theme.get(name)

	if not t then
		gg.alert(L(""))
		return ThemeSettings()
	end
	if kind == "builtin" then
		gg.alert(L(""))
		return ThemeNew()
	end

	local defaults = {}
	for i, k in ipairs(THEME_KEYS) do
		defaults[i] = string.format("0x%08X", t[k] & 0xFFFFFFFF)
	end

	local colors = gg.prompt(THEME_KEYS, defaults,
		{ "text","text","text","text","text","text","text","text" })
	if not colors then return ThemeSettings() end

	local newT, bad = parseThemeColors(colors)
	if not newT then
		gg.alert(L("") .. ": " .. bad)
		return ThemeEdit()
	end

	local ok, err = yj.ui.theme.save(name, newT)
	if ok then
		yj.ui.theme.set(name)
		gg.toast(L("") .. ": " .. name)
	else
		gg.alert(L("") .. ": " .. tostring(err))
	end
	return ThemeSettings()
end

function ThemeDelete()
	local names = {}
	for _, n in ipairs(yj.ui.theme.list()) do
		local _, kind = yj.ui.theme.get(n)
		if kind == "user" then names[#names + 1] = n end
	end
	if #names == 0 then
		gg.alert(L(""))
		return ThemeSettings()
	end

	local choice = gg.choice(names, nil, L(""))
	if not choice then return ThemeSettings() end

	local target = names[choice]
	if not target then return ThemeSettings() end

	local ok = yj.ui.theme.delete(target)
	gg.toast(ok and L("") or L(""))
	return ThemeSettings()
end

function ThemeExport()
	local name = yj.ui.theme.getName()
	local code = yj.ui.theme.export(name)
	if not code then
		gg.alert(L(""))
		return ThemeSettings()
	end

	if type(gg) == "table" and type(gg.copyText) == "function" then
		gg.copyText(code)
		gg.alert(L("") .. ":\n\n" .. code)
	else
		gg.alert(code)
	end
	return ThemeSettings()
end
]]

