		{name = L(""), key = "nextbonuslevelrank_"},
		{name = L(""), key = "shopchestsopened_"},
		{name = L(""), key = "gemstotalpaid_"},
		{name = L(""), key = "chestspends_", func = "GameStatuschestspends_"},
		{name = L("Quay lại"), func = "OtherMenu_", module = "modules/ops/OtherMenu_.lua"},
		["__title"] = L(""),
	}
	for i = 1, #MENU_CONFIG do
		local m = MENU_CONFIG[i]
		if m.key then
			local field = _GameStatus[m.key]
			if field then
				m.func = m.func or "yj.menu.browseDispatch"
				m.params = {Stack.BaseGameStatus, field, m.name, "GameStatus", {}}
			end
		end
	end
	yj.menu.unifiedRenderer("GameStatus", {}, MENU_CONFIG)
end

