-- ── VFS  bundle.py  loadModule ──
-- __vfs 
--        load(src, key, "t") 
--
-- VFS  dofile
--   ·  EXCLUDE_DIRS 
--      nil  nil 
-- nil/false 


local _moduleCache = {}
local _moduleLoaded = {}

function loadModule(name)
    local key = name:gsub("^%./", "")
    if not key:match("%.lua$") then key = key .. ".lua" end
    --  VFS / 
    if _moduleLoaded[key] then return _moduleCache[key] end

    -- 1) VFS 
    local src = __vfs[key]
    if src then
        local chunk, err = load(src, key, "t")
        if not chunk then
            gg.alert("VFS compile failed: " .. key .. "\n" .. tostring(err))
            os.exit()
        end
        local ret = chunk()
        _moduleCache[key]  = ret
        _moduleLoaded[key] = true
        return ret
    end

    -- 2)  nil loadModule 
    return nil
end


-- ── MAIN ENTRYPOINT ──────────────────────────────────────────────────────


-- ════════════════════════════════
-- GENTLE — Hill Climb Racing 2 (com.fingersoft.hcr2)  ·  v2.8
-- ════════════════════════════════

-- ───────────────────────────

-- ─────────────────────── initialize.lua
local _ok, _err = pcall(loadModule, "core/initialize.lua")
if not _ok then
	gg.alert("⚠️ \n\n" .. tostring(_err))
	os.exit()
end
-- ───────────────────────────────

function Main()
    local MENU_CONFIG = {
        {
            name = "🔓 CUSTOM UNLOCK",
            func = "CustomUnlock_",
            module = "modules/ops/CustomUnlock_.lua"
        },
        {
            name = "🚪 Thoát script",
            func = "Exit_0",
            module = "modules/ops/MoreSettings_/Exit_0.lua"
        },
    }

    MENU_CONFIG.__title = "ANHDEPZAI | CUSTOM UNLOCK"
    yj.menu.unifiedRenderer("Main", {}, MENU_CONFIG)
end

Main()

while true do
	gg.sleep(100)
	if gg.isVisible(true) then
		gg.setVisible(false)
		local lastItem = Stack.Menu[#Stack.Menu]
		if lastItem then
			yj.runtime.executeFunction(lastItem[1], lastItem[2])
		else
			Main()
		end
	end
end
